INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe0ed2a-1471-4cf6-a43a-d0ca5ecf6f2e', '和友人送趙能卿東歸', '和友人送趙能卿东归', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["一第時難得，歸期日已過。","相看玄鬢少，共憶白雲多。","楚闊天垂草，吳空月上波。","無人不有遇，之子獨狂歌。"]', '["一第时难得，归期日已過。","相看玄鬢少，共憶白云多。","楚闊天垂草，吳空月上波。","無人不有遇，之子独狂歌。"]', '诗', 'shi', '', NULL, '和友人送趙能卿東歸 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e43ae3ae-1cf5-4680-95fa-c9516256f0ef', '送人歸南中', '送人归南中', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["有家誰不別，經亂獨難尋。","遠路波濤惡，窮荒雨霧深。","燒驚山象出，雷觸海鼇沉。","爲問南遷客，何人在瘴林。"]', '["有家誰不別，經亂独难尋。","远路波濤惡，窮荒雨霧深。","燒驚山象出，雷觸海鼇沉。","爲问南遷客，何人在瘴林。"]', '诗', 'shi', '', NULL, '送人歸南中 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdf51ded-5463-4147-b991-5c3918f3a09c', '塞下曲', '塞下曲', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["邊事多更變，天心亦爲憂。","胡兵來作寇，漢將也封侯。","夜燒衝星赤，寒塵翳日愁。","無門展微畧，空上望西樓。"]', '["邊事多更变，天心亦爲憂。","胡兵来作寇，漢將也封侯。","夜燒衝星赤，寒塵翳日愁。","無门展微畧，空上望西楼。"]', '诗', 'shi', '', NULL, '塞下曲 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a772e775-ae84-4512-98d2-cb3058761c38', '邊將二首 一', '邊將二首 一', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["歷戰燕然北，功高劒有威。","聞名外國懼，輕命故人稀。","角怨星芒動，塵愁日色微。","從爲漢都護，未得脫征衣。"]', '["歷戰燕然北，功高劒有威。","闻名外国懼，轻命故人稀。","角怨星芒动，塵愁日色微。","從爲漢都護，未得脫征衣。"]', '诗', 'shi', '', NULL, '邊將二首 一 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d9365bf-dd1c-4eb1-bf90-23ba3bf8c468', '邊將二首 二', '邊將二首 二', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["按劒立城樓，西看極海頭。","承家爲上將，開地得邊州。","磧迥兵難伏，天寒馬易收。","胡風一度獵，吹裂錦貂裘。"]', '["按劒立城楼，西看極海头。","承家爲上將，开地得邊州。","磧迥兵难伏，天寒马易收。","胡风一度獵，吹裂錦貂裘。"]', '诗', 'shi', '', NULL, '邊將二首 二 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09832539-f138-4c32-b7f4-76b9fca56b42', '朔方書事', '朔方书事', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["秋盡角聲苦，逢人唯荷戈。","城池向隴少，岐路出關多。","雁遠行垂地，烽高影入河。","仍聞黑山寇，又覓漢家和。"]', '["秋尽角声苦，逢人唯荷戈。","城池向隴少，岐路出关多。","雁远行垂地，烽高影入河。","仍闻黑山寇，又覓漢家和。"]', '诗', 'shi', '', NULL, '朔方書事 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f10f8ddc-8d21-4976-b52c-b2e1ab31b942', '經荒驛', '經荒驛', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["古驛成幽境，雲蘿隔四隣。","夜燈移宿鳥，秋雨禁行人。","廢巷荆叢合，荒庭虎迹新。","昔年經此地，終日是紅塵。"]', '["古驛成幽境，云蘿隔四隣。","夜灯移宿鸟，秋雨禁行人。","廢巷荆叢合，荒庭虎迹新。","昔年經此地，終日是紅塵。"]', '诗', 'shi', '', NULL, '經荒驛 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e5a101e-7ad9-451b-be33-642b54b4af42', '贈棲白大師', '贈棲白大師', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["剃髮得時名，僧應別應星。","偶題皆有詔，閑論便成經。","埽葉寒燒鼎，融冰曉注瓶。","長因內齋出，多客叩禪扃。"]', '["剃髮得时名，僧應別應星。","偶題皆有詔，闲論便成經。","埽葉寒燒鼎，融冰晓注瓶。","长因內斋出，多客叩禪扃。"]', '诗', 'shi', '', NULL, '贈棲白大師 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae54e2a3-61fa-478a-92f9-7bc71ecdbb6a', '贈聞一上人', '贈闻一上人', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["見面雖年少，聞名似白頭。","玄談窮釋旨，清思掩詩流。","果落痕生砌，松高影上樓。","壇場在三殿，應召入焚修。"]', '["见面雖年少，闻名似白头。","玄談窮釋旨，清思掩诗流。","果落痕生砌，松高影上楼。","壇場在三殿，應召入焚修。"]', '诗', 'shi', '', NULL, '贈聞一上人 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea1ac2f0-dec1-4698-9025-00b70a57f5cb', '贈可倫上人', '贈可倫上人', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["師教本於空，流來不自東。","修從多劫後，行出衆人中。","衲冷湖山雨，幡輕海甸風。","遊吳累夏講，還與虎溪同。"]', '["師教本於空，流来不自东。","修從多劫後，行出衆人中。","衲冷湖山雨，幡轻海甸风。","游吳累夏講，還與虎溪同。"]', '诗', 'shi', '', NULL, '贈可倫上人 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f696bd7-3a60-415c-84e5-73df3619085b', '寄法乾寺令諲太師', '寄法乾寺令諲太師', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["師居中禁寺，外請已無緣。","望幸唯修偈，承恩不亂禪。","院多喧種藥，池有化生蓮。","何日龍宮裏，相尋借法船。"]', '["師居中禁寺，外請已無緣。","望幸唯修偈，承恩不亂禪。","院多喧種藥，池有化生蓮。","何日龙宮裏，相尋借法船。"]', '诗', 'shi', '', NULL, '寄法乾寺令諲太師 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67b4f143-4d1c-4605-97c9-2a9ed4238d60', '寄太白禪師', '寄太白禪師', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["何年萬仞頂，獨有坐禪僧。","客上應無路，人傳或見燈。","齋廚唯有橡，講石任生藤。","遙想東林社，如師誰復能。"]', '["何年万仞頂，独有坐禪僧。","客上應無路，人傳或见灯。","斋廚唯有橡，講石任生藤。","遙想东林社，如師誰复能。"]', '诗', 'shi', '', NULL, '寄太白禪師 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee0e65e5-92a0-43db-b646-cb4598128f5e', '遇道者', '遇道者', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["數里白雲裏，身輕無履蹤。","故尋多不見，偶到即相逢。","古井生雲水，高壇出異松。","聊看杏花酌，便似換顏容。"]', '["數里白云裏，身轻無履蹤。","故尋多不见，偶到即相逢。","古井生云水，高壇出異松。","聊看杏花酌，便似換顏容。"]', '诗', 'shi', '', NULL, '遇道者 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08295fd6-27a2-4eee-9f5f-aeecfbdf19db', '贈道者', '贈道者', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["得道疑人識，都城獨閉關。","頭從白後黑，心向鬧中閑。","飢渴唯調氣，兒孫亦駐顏。","始知仙者隱，殊不在深山。"]', '["得道疑人識，都城独閉关。","头從白後黑，心向鬧中闲。","飢渴唯調氣，兒孫亦駐顏。","始知仙者隐，殊不在深山。"]', '诗', 'shi', '', NULL, '贈道者 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d3f0541-27ab-45ed-8205-fe52b9da752c', '雨', '雨', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["半夜西亭雨，離人獨啓關。","桑麻荒舊國，雷電照前山。","細滴高槐底，繁聲疊漏間。","唯應孤鏡裏，明月長愁顏。"]', '["半夜西亭雨，離人独啓关。","桑麻荒旧国，雷電照前山。","細滴高槐底，繁声叠漏间。","唯應孤镜裏，明月长愁顏。"]', '诗', 'shi', '', NULL, '雨 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61198f01-55a4-472d-b25c-87671bbb8aab', '長安春望', '长安春望', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["明時不敢臥煙霞，又見秦城換物華。","殘雪未銷雙鳳闕，新春已發五侯家。","甘貧祗擬長緘酒，忍病猶期強採花。","故國別來桑柘盡，十年兵踐海西艖。"]', '["明时不敢臥煙霞，又见秦城換物华。","殘雪未銷雙鳳闕，新春已發五侯家。","甘貧祗擬长緘酒，忍病猶期強採花。","故国別来桑柘尽，十年兵踐海西艖。"]', '诗', 'shi', '', NULL, '長安春望 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f9a704b-739f-4e6a-9824-451e53c74b6e', '過黃牛峽', '過黄牛峽', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["黃牛來勢瀉巴川，疊日孤舟逐峽前。","雷電夜驚猿落樹，波濤愁恐客離船。","盤渦逆入嵌空地，斷壁高分繚繞天。","多少人經過此去，一生魂夢怕潺湲。"]', '["黄牛来勢瀉巴川，叠日孤舟逐峽前。","雷電夜驚猿落樹，波濤愁恐客離船。","盤渦逆入嵌空地，斷壁高分繚繞天。","多少人經過此去，一生魂梦怕潺湲。"]', '诗', 'shi', '', NULL, '過黃牛峽 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e096ee6b-9af7-4dd8-a201-7f91615f0c07', '逢道者', '逢道者', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["縱意出山無遠近，還如孤鶴在空虛。","昔年親種樹皆老，此世相逢人自疎。","野葉細苞深洞藥，巖蘿閒束古仙書。","秪尋隱跡歸何處，方說煙霞不定居。"]', '["縱意出山無远近，還如孤鹤在空虛。","昔年親種樹皆老，此世相逢人自疎。","野葉細苞深洞藥，巖蘿閒束古仙书。","秪尋隐跡归何处，方说煙霞不定居。"]', '诗', 'shi', '', NULL, '逢道者 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29ec173f-defa-4893-955e-cebf30541061', '邊情', '邊情', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["窮荒始得靜天驕，又說天兵擬渡遼。","聖主尚嫌蕃界近，將軍莫恨漢庭遙。","草枯朔野春難發，冰結河源夏半銷。","惆悵臨戎皆効國，豈無人似霍嫖姚。"]', '["窮荒始得静天驕，又说天兵擬渡遼。","聖主尚嫌蕃界近，將軍莫恨漢庭遙。","草枯朔野春难發，冰結河源夏半銷。","惆悵臨戎皆効国，豈無人似霍嫖姚。"]', '诗', 'shi', '', NULL, '邊情 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d83adc-da70-443f-bfe0-1a0b2f8e86d8', '贈李司徒', '贈李司徒', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["承家拓定隴關西，勳貴名應上將齊。","金庫夜開龍甲冷，玉堂秋閉鳳笙低。","歡筵每恕嬌娥醉，閑櫪猶驚戰馬嘶。","長怪魯儒頭枉白，不親弓劒覓丹梯。"]', '["承家拓定隴关西，勳貴名應上將齊。","金庫夜开龙甲冷，玉堂秋閉鳳笙低。","歡筵每恕嬌娥醉，闲櫪猶驚戰马嘶。","长怪魯儒头枉白，不親弓劒覓丹梯。"]', '诗', 'shi', '', NULL, '贈李司徒 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc14c432-8a77-4491-9ac8-539bbdb766ca', '送盧尚書赴靈武', '送盧尚书赴靈武', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["西北正傳烽候急，靈州共喜信臣居。","從軍盡是清才去，屬郡無非大將除。","新地進圖移漢界，古城遺碣見蕃書。","山川不異江湖景，賓館常聞食有魚。"]', '["西北正傳烽候急，靈州共喜信臣居。","從軍尽是清才去，屬郡無非大將除。","新地進圖移漢界，古城遺碣见蕃书。","山川不異江湖景，賓館常闻食有鱼。"]', '诗', 'shi', '', NULL, '送盧尚書赴靈武 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb77c11f-932d-485f-a2fa-1dd72b5e8603', '投翰林張侍郎', '投翰林張侍郎', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["舉家貧拾海邊樵，來認仙宗在碧霄。","丹穴雖無凡羽翼，靈椿還向細枝條。","九衢馬識他門少，十載身辭故國遙。","願與吾君作霖雨，且應平地活枯苗。"]', '["舉家貧拾海邊樵，来認仙宗在碧霄。","丹穴雖無凡羽翼，靈椿還向細枝條。","九衢马識他门少，十載身辞故国遙。","願與吾君作霖雨，且應平地活枯苗。"]', '诗', 'shi', '', NULL, '投翰林張侍郎 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2326d1b9-844e-48d8-91c4-f80d2647274b', '投翰林蕭侍郎', '投翰林蕭侍郎', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["九仞牆邊絕路岐，野才非合自求知。","靈湫豈要魚棲浪，仙桂那容鳥寄枝。","纖草不銷春氣力，微塵還助岳形儀。","從來爲學投文鏡，文鏡如今更有誰。"]', '["九仞牆邊絕路岐，野才非合自求知。","靈湫豈要鱼棲浪，仙桂那容鸟寄枝。","纖草不銷春氣力，微塵還助岳形儀。","從来爲学投文镜，文镜如今更有誰。"]', '诗', 'shi', '', NULL, '投翰林蕭侍郎 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41a67142-8cf8-4475-b5aa-b683de3e05c8', '宴駙馬宅', '宴駙马宅', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["牙香禁樂鎮相攜，日日君恩降紫泥。","紅藥院深人半醉，綠楊門掩馬頻嘶。","座中古物多仙意，壁上新詩有御題。","別向庭蕪寘吟石，不教宮妓踏成蹊。"]', '["牙香禁乐鎮相携，日日君恩降紫泥。","紅藥院深人半醉，綠楊门掩马頻嘶。","座中古物多仙意，壁上新诗有御題。","別向庭蕪寘吟石，不教宮妓踏成蹊。"]', '诗', 'shi', '', NULL, '宴駙馬宅 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db0ba7e4-7848-4244-a940-50e015705458', '邊將', '邊將', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["上馬乘秋欲建勳，飛弧夜闕出師頻。","若無紫塞煙塵事，誰識青樓歌舞人。","戰骨沙中金鏃在，賀筵花畔玉蟬新。","由來邊卒皆如此，只是君門合殺身。"]', '["上马乘秋欲建勳，飞弧夜闕出師頻。","若無紫塞煙塵事，誰識青楼歌舞人。","戰骨沙中金鏃在，賀筵花畔玉蟬新。","由来邊卒皆如此，只是君门合殺身。"]', '诗', 'shi', '', NULL, '邊將 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b483f9b-d13f-495e-8577-cde296b8212a', '贈水軍都將', '贈水軍都將', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["平生爲有安邦術，便別秋曹最上階。","戰艦却容儒客臥，公廳唯伴野僧齋。","裁書榭迥冰膠筆，養藥堂深蘚惹鞋。","直待門前見幢節，始應高愜聖君懷。"]', '["平生爲有安邦術，便別秋曹最上階。","戰艦却容儒客臥，公廳唯伴野僧斋。","裁书榭迥冰膠笔，養藥堂深蘚惹鞋。","直待门前见幢節，始應高愜聖君懷。"]', '诗', 'shi', '', NULL, '贈水軍都將 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16742e54-08cb-4c42-b3c1-c253524aeddc', '贈九江太守', '贈九江太守', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["江頭蹔駐木蘭船，漁父來誇太守賢。","二邑旋添新戶口，四營漸廢舊戈鋋。","笙歌不似經荒後，禮樂猶如未戰前。","昨日西亭從游騎，信旗風裏說詩篇。"]', '["江头蹔駐木蘭船，漁父来誇太守賢。","二邑旋添新戶口，四營漸廢旧戈鋋。","笙歌不似經荒後，禮乐猶如未戰前。","昨日西亭從游騎，信旗风裏说诗篇。"]', '诗', 'shi', '', NULL, '贈九江太守 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('155afb06-3a48-4437-a23b-37efc566e85c', '贈信安太守', '贈信安太守', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["三衢正對福星時，喜得君侯玅撫綏。","甲士散教耕壠畝，書生閑許從旌旗。","條章最是貧家喜，禾黍仍防別郡饑。","昨日中官說天意，即飛丹詔立新碑。"]', '["三衢正对福星时，喜得君侯玅撫綏。","甲士散教耕壠畝，书生闲許從旌旗。","條章最是貧家喜，禾黍仍防別郡饑。","昨日中官说天意，即飞丹詔立新碑。"]', '诗', 'shi', '', NULL, '贈信安太守 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('658881a7-cd11-406e-91b2-d9e5bd6ca2bd', '贈江都鄭明府', '贈江都鄭明府', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["他人豈是稱才術，才術須觀力有餘。","兵亂幾年臨劇邑，公清終日似閑居。","牀頭怪石神仙畫，篋裏華牋將相書。","更欲棲蹤近彭澤，香爐峰下結茅廬。"]', '["他人豈是稱才術，才術須观力有餘。","兵亂幾年臨劇邑，公清終日似闲居。","牀头怪石神仙畫，篋裏华牋將相书。","更欲棲蹤近彭澤，香爐峰下結茅廬。"]', '诗', 'shi', '', NULL, '贈江都鄭明府 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f414e9-6bca-470d-9658-564e72bf8d9d', '贈南昌宰', '贈南昌宰', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["假邑邀真邑命分，明庭元有至公存。","每鋤奸弊同荆棘，唯撫孤惸似子孫。","折獄不曾偏下筆，靈襟長是大開門。","新銜便合兼朱紱，應待蒼生更舉論。"]', '["假邑邀真邑命分，明庭元有至公存。","每鋤奸弊同荆棘，唯撫孤惸似子孫。","折獄不曾偏下笔，靈襟长是大开门。","新銜便合兼朱紱，應待蒼生更舉論。"]', '诗', 'shi', '', NULL, '贈南昌宰 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('950afc8e-1e50-4ec8-bea2-819479831333', '贈丘衙推', '贈丘衙推', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["仙都高處掩柴扉，人世聞名見者稀。","詩逸不拘凡對屬，易窮皆達聖玄微。","偶攜童穉離青嶂，便被君侯換白衣。","任醉賓筵莫深隱，綺羅絲竹勝漁磯。"]', '["仙都高处掩柴扉，人世闻名见者稀。","诗逸不拘凡对屬，易窮皆達聖玄微。","偶携童穉離青嶂，便被君侯換白衣。","任醉賓筵莫深隐，綺羅絲竹勝漁磯。"]', '诗', 'shi', '', NULL, '贈丘衙推 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('965d4a76-a2cb-49c4-952c-eff0ba7485b2', '獻所知', '獻所知', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["跡熟荀家見弟兄，九霄同與指前程。","吹噓漸覺馨香出，夢寐長疑羽翼生。","住僻驊騮皆識路，來頻鸚鵡亦知名。","登龍不敢懷他願，祗望爲霖致太平。"]', '["跡熟荀家见弟兄，九霄同與指前程。","吹噓漸覺馨香出，梦寐长疑羽翼生。","住僻驊騮皆識路，来頻鸚鵡亦知名。","登龙不敢懷他願，祗望爲霖致太平。"]', '诗', 'shi', '', NULL, '獻所知 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91f6db43-fde4-4eb9-bae9-9be001d86d84', '投所知', '投所知', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["十五年看帝里春，一枝頭白未酬身。","自聞離亂開公道，漸數孤平少屈人。","劣馬再尋商嶺路，扁舟重寄越溪濱。","省郎門似龍門峻，應借風雷變涸鱗。"]', '["十五年看帝里春，一枝头白未酬身。","自闻離亂开公道，漸數孤平少屈人。","劣马再尋商嶺路，扁舟重寄越溪濱。","省郎门似龙门峻，應借风雷变涸鱗。"]', '诗', 'shi', '', NULL, '投所知 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac38a01-c45f-4989-8976-c5dd7ef60de3', '南康夜宴東溪留別郡守陸郎中', '南康夜宴东溪留別郡守陸郎中', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["飄然野客才無取，多謝君侯獨見知。","竹葉樽前教駐樂，桃花紙上待君詩。","香迷蛺蝶投紅燭，舞拂蒹葭倚翠帷。","明發別愁何處去，片帆天際酒醒時。"]', '["飄然野客才無取，多謝君侯独见知。","竹葉樽前教駐乐，桃花紙上待君诗。","香迷蛺蝶投紅燭，舞拂蒹葭倚翠帷。","明發別愁何处去，片帆天際酒醒时。"]', '诗', 'shi', '', NULL, '南康夜宴東溪留別郡守陸郎中 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('386a6b1b-f93c-46ed-81ef-d807f9fbf7d1', '言懷', '言懷', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["十載聲沈覺自非，賤身元合衣荷衣。","豈能得路陪先達，却擬還家望少微。","戰馬到秋長淚落，傷禽無夜不魂飛。","平生祗學穿楊箭，更向何門是見機。"]', '["十載声沈覺自非，賤身元合衣荷衣。","豈能得路陪先達，却擬還家望少微。","戰马到秋长泪落，傷禽無夜不魂飞。","平生祗学穿楊箭，更向何门是见機。"]', '诗', 'shi', '', NULL, '言懷 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('247ae2dd-b95d-4e2b-8d0a-a534186dbd82', '喜友人日南迴', '喜友人日南迴', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["南遊曾去海南涯，此去遊人不易歸。","白日霧昏張夜燭，窮冬氣暖著春衣。","溪荒毒鳥隨船啅，洞黑冤蛇出樹飛。","重入帝城何[寂]寞，共迴遷客半輕肥。"]', '["南游曾去海南涯，此去游人不易归。","白日霧昏張夜燭，窮冬氣暖著春衣。","溪荒毒鸟隨船啅，洞黑冤蛇出樹飞。","重入帝城何[寂]寞，共迴遷客半轻肥。"]', '诗', 'shi', '', NULL, '喜友人日南迴 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac55935d-b1b5-4324-81d9-3a633ca7ab77', '下第述懷', '下第述懷', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["十載長安跡未安，杏花還是看人看。","名從近事方知險，詩到窮玄更覺難。","世薄不慚雲路晚，家貧唯怯草堂寒。","如何直道爲身累，坐月眠霜思枉乾。"]', '["十載长安跡未安，杏花還是看人看。","名從近事方知險，诗到窮玄更覺难。","世薄不慚云路晚，家貧唯怯草堂寒。","如何直道爲身累，坐月眠霜思枉乾。"]', '诗', 'shi', '', NULL, '下第述懷 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb277d01-8ce2-4141-bbf9-a1a3fc7b2ac3', '華陽道者', '华陽道者', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["華陽洞裏持真經，心嫌來客風塵腥。","惟餐白石過白日，擬騎青竹上青冥。","翔螭豈作漢武駕，神娥徒降燕昭庭。","長生不必論貴賤，却是幽人骨主靈。"]', '["华陽洞裏持真經，心嫌来客风塵腥。","惟餐白石過白日，擬騎青竹上青冥。","翔螭豈作漢武駕，神娥徒降燕昭庭。","长生不必論貴賤，却是幽人骨主靈。"]', '诗', 'shi', '', NULL, '華陽道者 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81da578d-ba4c-4c25-8b44-9596d6251225', '夏日題老將林亭', '夏日題老將林亭', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["百戰功成翻愛靜，侯門漸欲似仙家。","牆頭雨細垂纖草，水面風回聚落花。","井放轆轤閑侵酒，籠開鸚鵡報煎茶。","幾人圖在凌煙閣，曾不交鋒向塞沙。"]', '["百戰功成翻愛静，侯门漸欲似仙家。","牆头雨細垂纖草，水面风回聚落花。","井放轆轤闲侵酒，籠开鸚鵡報煎茶。","幾人圖在凌煙閣，曾不交鋒向塞沙。"]', '诗', 'shi', '', NULL, '夏日題老將林亭 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26e9864d-194e-4ade-b786-143ca0333196', '觀江南牡丹', '观江南牡丹', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["北地花開南地風，寄根還與客心同。","羣芳盡怯千般態，幾醉能消一番紅。","舉世秪將華勝實，真禪元喻色爲空。","近年明主思王道，不許新栽滿六宮。"]', '["北地花开南地风，寄根還與客心同。","羣芳尽怯千般態，幾醉能消一番紅。","舉世秪將华勝實，真禪元喻色爲空。","近年明主思王道，不許新栽满六宮。"]', '诗', 'shi', '', NULL, '觀江南牡丹 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecbb8d15-0107-47f4-809d-595543887ab7', '錢塘夜宴留別郡守', '錢塘夜宴留別郡守', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["四方騷動一州安，夜列罇罍伴客懽。","觱栗調高山閣迥，蝦蟆更促海聲寒。","屏間佩響藏歌妓，幕外刀光立從官。","沈醉不愁歸棹遠，晚風吹上子陵灘。"]', '["四方騷动一州安，夜列罇罍伴客懽。","觱栗調高山閣迥，蝦蟆更促海声寒。","屏间佩响藏歌妓，幕外刀光立從官。","沈醉不愁归棹远，晚风吹上子陵灘。"]', '诗', 'shi', '', NULL, '錢塘夜宴留別郡守 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffe9fccb-9372-4058-9706-f3702a446a58', '送薛郎中赴江州', '送薛郎中赴江州', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["幾州聞出刺，謠美有江民。","正面傳天旨，懸心禱岳神。","尺書先假路，紅斾旋燒塵。","郡顯山川別，衙開將吏新。","散招僧坐暑，閑載客行春。","聽事棊忘着，探題酒亂巡。","好編高隱傳，多貌上昇真。","近日居清近，求人在此人。"]', '["幾州闻出刺，謠美有江民。","正面傳天旨，懸心禱岳神。","尺书先假路，紅斾旋燒塵。","郡显山川別，衙开將吏新。","散招僧坐暑，闲載客行春。","听事棊忘着，探題酒亂巡。","好編高隐傳，多貌上昇真。","近日居清近，求人在此人。"]', '诗', 'shi', '', NULL, '送薛郎中赴江州 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f551f55f-cdb7-46d3-b7da-bf7468a2931e', '送南海僧遊蜀', '送南海僧游蜀', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["真修絕故鄉，一衲度暄涼。","此世能先覺，他生豈再忘。","定中船過海，臘後路沿湘。","野迥鴉隨笠，山深虎背囊。","瀑流垂石室，蘿蔓蓋銅梁。","却後何年會，西方有上房。"]', '["真修絕故乡，一衲度暄涼。","此世能先覺，他生豈再忘。","定中船過海，臘後路沿湘。","野迥鴉隨笠，山深虎背囊。","瀑流垂石室，蘿蔓蓋銅梁。","却後何年會，西方有上房。"]', '诗', 'shi', '', NULL, '送南海僧遊蜀 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f9407c4-0856-4cc6-81c6-07f7cf6ebc36', '和友人許裳題宣平里古藤', '和友人許裳題宣平里古藤', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["欲結千年茂，生來便近松。","迸根通井潤，交葉覆庭穠。","歷代頻更主，盤空漸變龍。","晝風圓影亂，宵雨細聲重。","蓋密勝丹桂，層危類遠峰。","嫩條懸野鼠，枯節呌秋蛩。","翠老霜難蝕，皴多蘚乍封。","幾家遙共翫，何寺不堪容。","客對忘離榻，僧看誤過鐘。","頃因陪預作，終夕遶枝筇。"]', '["欲結千年茂，生来便近松。","迸根通井潤，交葉覆庭穠。","歷代頻更主，盤空漸变龙。","晝风圓影亂，宵雨細声重。","蓋密勝丹桂，層危類远峰。","嫩條懸野鼠，枯節呌秋蛩。","翠老霜难蝕，皴多蘚乍封。","幾家遙共翫，何寺不堪容。","客对忘離榻，僧看誤過鐘。","頃因陪預作，終夕遶枝筇。"]', '诗', 'shi', '', NULL, '和友人許裳題宣平里古藤 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12dfba16-5098-40a1-a6cb-2be66dedcaad', '十五夜與友人對月', '十五夜與友人对月', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["每到月圓思共醉，不宜同醉不成歡。","一千二百如輪夜，浮世誰能得盡看。"]', '["每到月圓思共醉，不宜同醉不成歡。","一千二百如輪夜，浮世誰能得尽看。"]', '诗', 'shi', '', NULL, '十五夜與友人對月 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5d78dab-3433-4e10-ba3c-cfb5ef0017d3', '青塚', '青塚', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["傾國可能勝效國，無勞冥寞更思回。","太真雖是承恩死，祗作飛塵向馬嵬。"]', '["傾国可能勝效国，無勞冥寞更思回。","太真雖是承恩死，祗作飞塵向马嵬。"]', '诗', 'shi', '', NULL, '青塚 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d2f6226-7718-4bd7-9561-88b8b536e8b5', '古戰場', '古戰場', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["荒骨潛銷壘已平，漢家曾說此交兵。","如何萬古冤魂在，風雨時聞有戰聲。"]', '["荒骨潛銷壘已平，漢家曾说此交兵。","如何万古冤魂在，风雨时闻有戰声。"]', '诗', 'shi', '', NULL, '古戰場 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('254a21cf-e0b1-4759-8d83-7e9c0fdda393', '贈段逸人', '贈段逸人', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["長筇自擔藥兼琴，話著名山即擬尋。","從聽世人權似火，不能燒得臥雲心。"]', '["长筇自擔藥兼琴，話著名山即擬尋。","從听世人權似火，不能燒得臥云心。"]', '诗', 'shi', '', NULL, '贈段逸人 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7215e05d-8d74-43b1-9d8b-c2c504f03193', '贈鄭司業', '贈鄭司業', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["晚學更求來世達，正懷非與百邪侵。","古人名在今人口，不合于名不苦心。"]', '["晚学更求来世達，正懷非與百邪侵。","古人名在今人口，不合于名不苦心。"]', '诗', 'shi', '', NULL, '贈鄭司業 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f552ab51-e7c1-44b5-90aa-855511ee4b82', '上所知', '上所知', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["初向衆中留姓氏，敢期言下致時名。","而今馬亦知人意，每到門前不肯行。"]', '["初向衆中留姓氏，敢期言下致时名。","而今马亦知人意，每到门前不肯行。"]', '诗', 'shi', '', NULL, '上所知 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac74fda7-e3ce-4efb-aeae-564a7f0bc2ba', '別鄭仁表', '別鄭仁表', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["春雷醉別鏡湖邊，官顯才狂正少年。","紅燭滿汀歌舞散，美人迎上木蘭船。"]', '["春雷醉別镜湖邊，官显才狂正少年。","紅燭满汀歌舞散，美人迎上木蘭船。"]', '诗', 'shi', '', NULL, '別鄭仁表 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b9faa76-5aa3-4005-bb25-c7407b50da55', '言懷', '言懷', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["不將高蓋竟煙塵，自向蓬茅認此身。","唐祖本來成大業，豈非姚宋是平人。"]', '["不將高蓋竟煙塵，自向蓬茅認此身。","唐祖本来成大業，豈非姚宋是平人。"]', '诗', 'shi', '', NULL, '言懷 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fae65d7c-8e6f-4ef5-8d0d-58c5ada651e4', '敘懷', '敘懷', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["月裏路從何處上，江邊身合幾時歸。","十年九陌寒風夜，夢掃蘆花絮客衣。"]', '["月裏路從何处上，江邊身合幾时归。","十年九陌寒风夜，梦掃蘆花絮客衣。"]', '诗', 'shi', '', NULL, '敘懷 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da9e9165-dfbe-402a-8180-8c2792a901a0', '抒懷', '抒懷', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["幾出東堂謝不才，便甘閒望故山迴。","翻思未是離家久，更有人從外國來。"]', '["幾出东堂謝不才，便甘閒望故山迴。","翻思未是離家久，更有人從外国来。"]', '诗', 'shi', '', NULL, '抒懷 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9093373-aa79-433c-976d-9a71da487bb5', '自諷', '自諷', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["鹿鳴筵上強稱賢，一送離家十四年。","同隱海山燒藥伴，不求丹桂却登仙。"]', '["鹿鳴筵上強稱賢，一送離家十四年。","同隐海山燒藥伴，不求丹桂却登仙。"]', '诗', 'shi', '', NULL, '自諷 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9fd38fa-0e95-453a-9245-09ccdb6da64a', '傷賈島', '傷賈島', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["生爲明代苦吟身，死作長江一逐臣。","可是當時少知己，不知知己是何人。"]', '["生爲明代苦吟身，死作长江一逐臣。","可是當时少知己，不知知己是何人。"]', '诗', 'shi', '', NULL, '傷賈島 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd488dd2-8d1a-4a36-9d3e-be14dcbbc5d6', '再游西山贈許尊師', '再游西山贈許尊師', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["別後已聞師得道，不期猶在此山頭。","昔時霜鬢今如漆，疑是年光却倒流。"]', '["別後已闻師得道，不期猶在此山头。","昔时霜鬢今如漆，疑是年光却倒流。"]', '诗', 'shi', '', NULL, '再游西山贈許尊師 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c53aee5f-e65c-45f4-90d1-de9e1c850fd0', '宮詞', '宮词', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["日透珠簾見冕旒，六宮爭逐百花毬。","迴看不覺君王去，已聽笙歌在遠樓。"]', '["日透珠簾见冕旒，六宮爭逐百花毬。","迴看不覺君王去，已听笙歌在远楼。"]', '诗', 'shi', '', NULL, '宮詞 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f184c1da-bc1b-4756-b7c8-e0137889d24a', '經范蠡舊居', '經范蠡旧居', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["一變姓名離百越，越城猶在范家無。","他人不見扁舟意，却笑輕生泛五湖。"]', '["一变姓名離百越，越城猶在范家無。","他人不见扁舟意，却笑轻生泛五湖。"]', '诗', 'shi', '', NULL, '經范蠡舊居 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49088c37-d122-44cc-9d39-aded27724de8', '題嘉陵驛', '題嘉陵驛', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["嘉陵路惡石和泥，行到長亭日已西。","獨倚闌干正惆悵，海棠花裏鷓鴣啼。"]', '["嘉陵路惡石和泥，行到长亭日已西。","独倚闌干正惆悵，海棠花裏鷓鴣啼。"]', '诗', 'shi', '', NULL, '題嘉陵驛 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e2222a7-b3b1-4312-ac5a-8bb7697cd03e', '龜山寺晚望', '龟山寺晚望', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["四面湖光絕路岐，鸊鵜飛起暮鐘時。","漁舟不用懸帆席，歸去乘風插柳枝。"]', '["四面湖光絕路岐，鸊鵜飞起暮鐘时。","漁舟不用懸帆席，归去乘风插柳枝。"]', '诗', 'shi', '', NULL, '龜山寺晚望 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('898fffa1-deca-41a7-8f0e-a778b361cb02', '華山孤松', '华山孤松', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["石罅引根非土力，冒寒猶助岳蓮光。","綠槐生在膏腴地，何得無心拒雪霜。"]', '["石罅引根非土力，冒寒猶助岳蓮光。","綠槐生在膏腴地，何得無心拒雪霜。"]', '诗', 'shi', '', NULL, '華山孤松 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b3a9cb-f331-44ed-a241-b0268135467c', '弔萬人塚', '弔万人塚', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["兵罷淮邊客路通，亂鴉來去噪寒空。","可憐白骨攢孤塚，盡爲將軍覓戰功。"]', '["兵罷淮邊客路通，亂鴉来去噪寒空。","可怜白骨攢孤塚，尽爲將軍覓戰功。"]', '诗', 'shi', '', NULL, '弔萬人塚 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db3eade6-af37-4ce5-95d3-c54e16b77287', '送友尉蜀中', '送友尉蜀中', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["故友漢中尉，請爲西蜀吟。","人家多種橘，風土愛彈琴。","水向昆明闊，山通大夏深。","理閑無別事，時寄一登臨。"]', '["故友漢中尉，請爲西蜀吟。","人家多種橘，风土愛彈琴。","水向昆明闊，山通大夏深。","理闲無別事，时寄一登臨。"]', '诗', 'shi', '', NULL, '送友尉蜀中 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cf5cb88-3fc2-4a9a-a294-908e15c6d893', '長安寓懷', '长安寓懷', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["九衢秋雨掩閑扉，不似干名似息機。","貧病却慙牆上土，年來猶自換新衣。"]', '["九衢秋雨掩闲扉，不似干名似息機。","貧病却慙牆上土，年来猶自換新衣。"]', '诗', 'shi', '', NULL, '長安寓懷 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('964eb1ff-4222-44e4-a9fa-97deebcc4463', '費徵君舊居', '費徵君旧居', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["浮世拋身外，棲蹤入九華。","遺篇補樂府，舊籍隸仙家。","池靜龜昇樹，庭荒鶴隱花。","古來天子命，還少到煙霞。"]', '["浮世拋身外，棲蹤入九华。","遺篇補乐府，旧籍隸仙家。","池静龟昇樹，庭荒鹤隐花。","古来天子命，還少到煙霞。"]', '诗', 'shi', '', NULL, '費徵君舊居 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ab7c0f-9874-4ff9-a228-119ee27af0e1', '晨興', '晨兴', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["晨起竹軒外，逍遙清興多。","早涼生戶牖，孤月照關河。","旅食甘藜藿，歸心憶薜蘿。","一尊如有地，放意且狂歌。"]', '["晨起竹軒外，逍遙清兴多。","早涼生戶牖，孤月照关河。","旅食甘藜藿，归心憶薜蘿。","一尊如有地，放意且狂歌。"]', '诗', 'shi', '', NULL, '晨興 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46b4ff28-2a7b-4614-a7fb-0a9272402673', '題莒潭安閩院', '題莒潭安閩院', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["祧宗營祀舍，幽異勝珠林。","名士穿雲訪，飛禽傍竹吟。","牕含孤岫影，牧臥斷霞陰。","景福滋閩壤，芳名亙古今。"]', '["祧宗營祀舍，幽異勝珠林。","名士穿云訪，飞禽傍竹吟。","牕含孤岫影，牧臥斷霞陰。","景福滋閩壤，芳名亙古今。"]', '诗', 'shi', '', NULL, '題莒潭安閩院 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7748cb83-de94-4490-89e8-acf7f63891d6', '華下霽後曉眺', '华下霽後晓眺', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["結茅幽寂近禪林，霽景煙光著柳陰。","千嶂華山雲外秀，萬重鄉思望中深。","老嫌白髮還偷鑷，貧對春風亦強吟。","花畔水邊人不會，騰騰閑步一披襟。"]', '["結茅幽寂近禪林，霽景煙光著柳陰。","千嶂华山云外秀，万重乡思望中深。","老嫌白髮還偷鑷，貧对春风亦強吟。","花畔水邊人不會，腾腾闲步一披襟。"]', '诗', 'shi', '', NULL, '華下霽後曉眺 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25e33a42-1282-46a9-86c2-452529c39459', '喜弟承檢登科', '喜弟承檢登科', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["兩篇佳句敵瓊瑰，憐我三清道路開。","荆璞獻多還得售，桂堂恩在敢輕回。","花繁不怕尋香客，榜到應傾賀喜杯。","知爾苦心功業就，早攜長策出山來。"]', '["兩篇佳句敵瓊瑰，怜我三清道路开。","荆璞獻多還得售，桂堂恩在敢轻回。","花繁不怕尋香客，榜到應傾賀喜杯。","知爾苦心功業就，早携长策出山来。"]', '诗', 'shi', '', NULL, '喜弟承檢登科 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5e77a36-baf1-4a20-b89d-b7d795a2bf84', '蒙閩王改賜鄉里', '蒙閩王改賜乡里', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["鄉名文秀里光賢，別向鈞台造化權。","閥閱便因今日貴，德音兼與後人傳。","自從受賜身無力，向未酬恩骨肯鐫。","歸闕路遙心更切，不嫌扶病倚旌旃。"]', '["乡名文秀里光賢，別向鈞台造化權。","閥閱便因今日貴，德音兼與後人傳。","自從受賜身無力，向未酬恩骨肯鐫。","归闕路遙心更切，不嫌扶病倚旌旃。"]', '诗', 'shi', '', NULL, '蒙閩王改賜鄉里 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81cd84c7-3a4c-47fb-bdff-9036aca26854', '訪建陽馬驛僧亞齊', '訪建陽马驛僧亞齊', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["蕭蕭風雨建陽溪，溪畔維舟訪亞齊。","一軸新詩劒潭北，十年舊識華山西。","吟魂惜向江村老，空性元知世路迷。","應笑乘軺青瑣客，此時無暇聽猿啼。"]', '["蕭蕭风雨建陽溪，溪畔維舟訪亞齊。","一軸新诗劒潭北，十年旧識华山西。","吟魂惜向江村老，空性元知世路迷。","應笑乘軺青瑣客，此时無暇听猿啼。"]', '诗', 'shi', '', NULL, '訪建陽馬驛僧亞齊 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89f07435-de68-4a0b-8287-f412c3461d8a', '題景祥院', '題景祥院', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["一溪拖碧遶崔嵬，瓶鉢偏宜向此隈。","農罷樹陰黃犢臥，齋時山下白衣來。","松多往日門人種，路是前朝釋子開。","三卷貝多金粟語，可能心煉得成灰。"]', '["一溪拖碧遶崔嵬，瓶鉢偏宜向此隈。","農罷樹陰黄犢臥，斋时山下白衣来。","松多往日门人種，路是前朝釋子开。","三卷貝多金粟語，可能心煉得成灰。"]', '诗', 'shi', '', NULL, '題景祥院 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b8f9399-a622-464a-9e45-251df29d9c70', '寄舍弟承裕員外', '寄舍弟承裕員外', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["江花岸草晚萋萋，公子王孫思合迷。","無主園林饒採伐，忘情鷗鳥恣高低。","長江月上魚翻鬣，荒圃人稀獺印蹄。","何事斜陽再回首，休愁離別峴山西。"]', '["江花岸草晚萋萋，公子王孫思合迷。","無主园林饒採伐，忘情鷗鸟恣高低。","长江月上鱼翻鬣，荒圃人稀獺印蹄。","何事斜陽再回首，休愁離別峴山西。"]', '诗', 'shi', '', NULL, '寄舍弟承裕員外 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df228056-e03c-4fe3-bf53-21ca012797fd', '文明殿受冊封閩王', '文明殿受冊封閩王', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["龍墀班聽漏聲長，竹帛昭勳撲御香。","鳴佩洞庭辭帝主，登車故里冊閩王。","一千年改江山瑞，十萬軍蒙雨露光。","吟寄短篇追往事，留文功業不尋常。"]', '["龙墀班听漏声长，竹帛昭勳撲御香。","鳴佩洞庭辞帝主，登车故里冊閩王。","一千年改江山瑞，十万軍蒙雨露光。","吟寄短篇追往事，留文功業不尋常。"]', '诗', 'shi', '', NULL, '文明殿受冊封閩王 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c339aada-2847-40ff-af64-38dd9418c6b0', '御命歸鄉蒙賜錦衣', '御命归乡蒙賜錦衣', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["九重宣旨下丹墀，面對天顏賜錦衣。","中使擎來三殿曉，寶箱開處五雲飛。","德音耳聆君恩重，金印腰懸已力微。","更待臨軒陳鼓吹，星軺便指故鄉歸。"]', '["九重宣旨下丹墀，面对天顏賜錦衣。","中使擎来三殿晓，寶箱开处五云飞。","德音耳聆君恩重，金印腰懸已力微。","更待臨軒陳鼓吹，星軺便指故乡归。"]', '诗', 'shi', '', NULL, '御命歸鄉蒙賜錦衣 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14342e9b-d554-4933-bed0-bcfb5b3ffcf8', '奉使封閩王歸京洛', '奉使封閩王归京洛', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["泥緘紫誥御恩光，信馬嘶風出洛陽。","此去願言歸梓里，預憑魂夢展維桑。","客程回首瞻文陛，驛路乘軺憶故鄉。","指日還家堪自重，恩榮晝錦賀封王。"]', '["泥緘紫誥御恩光，信马嘶风出洛陽。","此去願言归梓里，預憑魂梦展維桑。","客程回首瞻文陛，驛路乘軺憶故乡。","指日還家堪自重，恩榮晝錦賀封王。"]', '诗', 'shi', '', NULL, '奉使封閩王歸京洛 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35cb5b3d-110c-4646-99fd-391758d87d3a', '奉使封王次宜春驛', '奉使封王次宜春驛', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["微宦淹留鬢已斑，此心長憶舊林泉。","不因列土封千乘，爭得銜恩拜二天。","雲斷自宜鄉樹出，月高猶伴客心懸。","夜來夢到南臺上，徧看江山勝往年。"]', '["微宦淹留鬢已斑，此心长憶旧林泉。","不因列土封千乘，爭得銜恩拜二天。","云斷自宜乡樹出，月高猶伴客心懸。","夜来梦到南台上，徧看江山勝往年。"]', '诗', 'shi', '', NULL, '奉使封王次宜春驛 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9e367e1-d74f-4f72-8a53-35a3054b1509', '甲子歲銜命到家至榕城冊封次日閩王降旌旗於新豐市堤餞別', '甲子歲銜命到家至榕城冊封次日閩王降旌旗於新豐市堤餞別', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["登庸樓上方停樂，新市堤邊又舉杯。","正是離情傷遠別，忽聞台旨許重來。","此時暫與交親好，今日還將簡冊回。","爭得長房猶在世，縮教地近釣魚臺。"]', '["登庸楼上方停乐，新市堤邊又舉杯。","正是離情傷远別，忽闻台旨許重来。","此时暫與交親好，今日還將簡冊回。","爭得长房猶在世，縮教地近釣鱼台。"]', '诗', 'shi', '', NULL, '甲子歲銜命到家至榕城冊封次日閩王降旌旗於新豐市堤餞別 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce166e0a-2419-4868-a743-e5c9da3f1f3e', '寄示兒孫', '寄示兒孫', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["力學燒丹二十年，辛勤方得遇真仙。","便隨羽客歸三島，旋聽霓裳適九天。","得路自能酬造化，立身何必戀林泉。","予家藥鼎分明在，好把仙方次第傳。"]', '["力学燒丹二十年，辛勤方得遇真仙。","便隨羽客归三島，旋听霓裳適九天。","得路自能酬造化，立身何必戀林泉。","予家藥鼎分明在，好把仙方次第傳。"]', '诗', 'shi', '', NULL, '寄示兒孫 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4d5c8a6-9304-4c3b-b737-f2b439d07b1b', '天祐元年以右拾遺使冊閩王而作', '天祐元年以右拾遺使冊閩王而作', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["蓬萊宮闕曉光勻，紅案舁麻降紫宸。","鸞奏八音諧律呂，鳳銜五色顯絲綸。","蕭何相印鈞衡重，韓信齋壇雨露新。","得侍丹墀官異寵，此身何幸沐恩頻。"]', '["蓬萊宮闕晓光勻，紅案舁麻降紫宸。","鸾奏八音諧律呂，鳳銜五色显絲綸。","蕭何相印鈞衡重，韓信斋壇雨露新。","得侍丹墀官異寵，此身何幸沐恩頻。"]', '诗', 'shi', '', NULL, '天祐元年以右拾遺使冊閩王而作 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b868c3b2-605a-4bd5-93ee-e6476795e05a', '漢上登舟憶閩', '漢上登舟憶閩', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["漢臯亭畔起西風，半挂征帆立向東。","久客自憐歸路近，筭程不怕酒觴空。","參差雁陣天初碧，零落漁家蓼欲紅。","一片歸心隨去櫂，願言指日拜文翁。"]', '["漢臯亭畔起西风，半挂征帆立向东。","久客自怜归路近，筭程不怕酒觴空。","參差雁陣天初碧，零落漁家蓼欲紅。","一片归心隨去櫂，願言指日拜文翁。"]', '诗', 'shi', '', NULL, '漢上登舟憶閩 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4088b9dc-6391-463f-a3d6-957d23315974', '對雨述懷示弟承檢', '对雨述懷示弟承檢', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["淋淋霎霎結秋霖，欲使秦城歎陸沈。","曉勢遮回朝客馬，夜聲滴破旅人心。","青苔重疊封顏巷，白髮蕭疎引越吟。","不有惠連同此景，江南歸思幾般深。"]', '["淋淋霎霎結秋霖，欲使秦城歎陸沈。","晓勢遮回朝客马，夜声滴破旅人心。","青苔重叠封顏巷，白髮蕭疎引越吟。","不有惠連同此景，江南归思幾般深。"]', '诗', 'shi', '', NULL, '對雨述懷示弟承檢 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3f44556-98a6-420e-a217-65276ff3ae60', '題壺山', '題壺山', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["井邑斜連北，蓬瀛直倚東。","秋高巖溜白，日上海波紅。"]', '["井邑斜連北，蓬瀛直倚东。","秋高巖溜白，日上海波紅。"]', '诗', 'shi', '', NULL, '題壺山 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dc476f3-51a8-4f31-a740-46e33cc8ac90', '題故居', '題故居', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["一爲鵝子二連花，三望青湖四石斜。","惟有嶺湖居第五，山前却是宰臣家。"]', '["一爲鵝子二連花，三望青湖四石斜。","惟有嶺湖居第五，山前却是宰臣家。"]', '诗', 'shi', '', NULL, '題故居 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe88847b-c015-4d15-a5e0-45176b085c7e', '題槐', '題槐', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["雨中妝點望中黃，句引蟬聲送夕陽。","憶昔當年隨計吏，馬蹄終日爲君忙。"]', '["雨中妝点望中黄，句引蟬声送夕陽。","憶昔當年隨計吏，马蹄終日爲君忙。"]', '诗', 'shi', '', NULL, '題槐 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61172123-ca47-40ae-9d97-184b2c4b94c3', '擢進士', '擢進士', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["霓旌引上大羅天，別領新銜意自憐。","蝴蝶流鶯莫先去，滿城春色屬羣仙。"]', '["霓旌引上大羅天，別領新銜意自怜。","蝴蝶流鶯莫先去，满城春色屬羣仙。"]', '诗', 'shi', '', NULL, '擢進士 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05795c6a-9bbc-4d79-99d7-78ce34226791', '擢探花使三首 一', '擢探花使三首 一', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["洪崖差遣探花來，檢點芳叢飲數杯。","深紫濃香三百朵，明朝爲我一時開。"]', '["洪崖差遣探花来，檢点芳叢饮數杯。","深紫濃香三百朵，明朝爲我一时开。"]', '诗', 'shi', '', NULL, '擢探花使三首 一 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce4914a9-0b49-4ac4-8c7f-fa906a8b46a3', '擢探花使三首 二', '擢探花使三首 二', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["九重煙暖折槐芽，自是升平好物華。","今日始知春氣味，長安虛過四年花。"]', '["九重煙暖折槐芽，自是升平好物华。","今日始知春氣味，长安虛過四年花。"]', '诗', 'shi', '', NULL, '擢探花使三首 二 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dd8336f-2d6c-4220-9d8d-33d26897752c', '擢探花使三首 三', '擢探花使三首 三', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["探花時節日偏長，恬淡春風稱意忙。","每到黃昏醉歸去，紵衣惹得牡丹香。"]', '["探花时節日偏长，恬淡春风稱意忙。","每到黄昏醉归去，紵衣惹得牡丹香。"]', '诗', 'shi', '', NULL, '擢探花使三首 三 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f56d6b74-fa43-449a-9f29-e0e5648f89b6', '書齋謾興二首 一', '书斋謾兴二首 一', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["池塘四五尺深水，籬落兩三般樣花。","過客不須頻問姓，讀書聲裏是吾家。"]', '["池塘四五尺深水，籬落兩三般樣花。","過客不須頻问姓，读书声裏是吾家。"]', '诗', 'shi', '', NULL, '書齋謾興二首 一 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5e242ee-05ee-4f01-b00c-4cf105c78db5', '書齋謾興二首 二', '书斋謾兴二首 二', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["官事歸來衣雪埋，兒童燈火小茅齋。","人家不必論貧富，惟有讀書聲最佳。"]', '["官事归来衣雪埋，兒童灯火小茅斋。","人家不必論貧富，惟有读书声最佳。"]', '诗', 'shi', '', NULL, '書齋謾興二首 二 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26b38ced-e3c8-4d1a-8f19-bacb51f59ceb', '辭閩王歸朝寄倪先輩', '辞閩王归朝寄倪先輩', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["時人莫訝再還鄉，簡冊分明劒佩光。","駟馬高車太常樂，登庸門下憶賢良。"]', '["时人莫訝再還乡，簡冊分明劒佩光。","駟马高车太常乐，登庸门下憶賢良。"]', '诗', 'shi', '', NULL, '辭閩王歸朝寄倪先輩 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('807011ad-2028-4340-9246-8663810e249e', '曉望', '晓望', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["清霜散漫似輕嵐，玉闕參差萬象涵。","獨上秦臺最高處，舊山依約在東南。"]', '["清霜散漫似轻嵐，玉闕參差万象涵。","独上秦台最高处，旧山依約在东南。"]', '诗', 'shi', '', NULL, '曉望 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2764e79a-2c59-4970-b5aa-a7a08b282657', '萬壽寺牡丹', '万壽寺牡丹', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["爛熳香風引貴遊，高僧移步亦遲留。","可憐殿角長松色，不得王孫一舉頭。"]', '["爛熳香风引貴游，高僧移步亦遲留。","可怜殿角长松色，不得王孫一舉头。"]', '诗', 'shi', '', NULL, '萬壽寺牡丹 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05dfab6f-2a9e-46b0-9dc4-4c6ccc5ff1e3', '松', '松', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["倚澗臨溪自屈蟠，雪花銷盡蘚花乾。","幽枝好折爲談柄，入手方知有歲寒。"]', '["倚澗臨溪自屈蟠，雪花銷尽蘚花乾。","幽枝好折爲談柄，入手方知有歲寒。"]', '诗', 'shi', '', NULL, '松 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c539fb-cab8-4676-b7f7-d0fa73eb3b4b', '柳 一', '柳 一', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["斜拂中橋遠映樓，翠光駘蕩曉煙收。","洛陽才子多情思，橫把金鞭約馬頭。"]', '["斜拂中橋远映楼，翠光駘蕩晓煙收。","洛陽才子多情思，橫把金鞭約马头。"]', '诗', 'shi', '', NULL, '柳 一 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad975330-d999-4367-89dd-4a9bd459ee66', '柳 二', '柳 二', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["高出營門遠出墻，朱闌門閉綠成行。","將軍宴罷東風急，閑襯旌旗簇畫堂。"]', '["高出營门远出墻，朱闌门閉綠成行。","將軍宴罷东风急，闲襯旌旗簇畫堂。"]', '诗', 'shi', '', NULL, '柳 二 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('636c7781-73e8-476e-a8f6-d1038653340e', '柳 三', '柳 三', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["彭澤先生酒滿船，五株栽向九江邊。","長條細葉無窮盡，管領春風不計年。"]', '["彭澤先生酒满船，五株栽向九江邊。","长條細葉無窮尽，管領春风不計年。"]', '诗', 'shi', '', NULL, '柳 三 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7164d9aa-b510-4258-ae4e-e44ee5de9328', '柳 四', '柳 四', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["煬帝東遊意緒多，宮娃眉翠兩相和。","一聲水調春風暮，千里交陰鎖汴河。"]', '["煬帝东游意緒多，宮娃眉翠兩相和。","一声水調春风暮，千里交陰鎖汴河。"]', '诗', 'shi', '', NULL, '柳 四 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48b50413-6116-423a-b704-87348cac4267', '柳 五', '柳 五', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["纏繞春情卒未休，秦娥蕭史兩相求。","玉句闌內朱簾卷，瑟瑟絲籠十二樓。"]', '["纏繞春情卒未休，秦娥蕭史兩相求。","玉句闌內朱簾卷，瑟瑟絲籠十二楼。"]', '诗', 'shi', '', NULL, '柳 五 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03a8fb6d-6062-4f55-a322-bb3378d17590', '隋堤柳', '隋堤柳', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["春半煙深汴水東，黃金絲軟不勝風。","輕籠行殿迷天子，拋擲長安似夢中。"]', '["春半煙深汴水东，黄金絲軟不勝风。","轻籠行殿迷天子，拋擲长安似梦中。"]', '诗', 'shi', '', NULL, '隋堤柳 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf176573-24f0-4ea7-bcf1-5dbdad107033', '句', '句', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["煙蘿況逼神仙窟，丹竈還應許獨尋。"]', '["煙蘿況逼神仙窟，丹竈還應許独尋。"]', '诗', 'shi', '', NULL, '句 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5d1f87f-2ce0-477d-9f2a-1dac7b61c746', '送僧歸北巖寺', '送僧归北巖寺', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["北巖泉石清，本自高僧住。","新松五十年，藤蘿成古樹。","題詩昔佳士，清風二林喻。","上智失扣關，多被浮名誤。","蓮扃壓月澗，空美黃金布。","江翻島嶼沈，木落樓臺露。","伊余東還際，每起煙霞慕。","旋爲儉府招，未得窮野步。","西軒白雲閣，師辭洞庭寓。","越城今送歸，心到焚香處。"]', '["北巖泉石清，本自高僧住。","新松五十年，藤蘿成古樹。","題诗昔佳士，清风二林喻。","上智失扣关，多被浮名誤。","蓮扃壓月澗，空美黄金布。","江翻島嶼沈，木落楼台露。","伊余东還際，每起煙霞慕。","旋爲儉府招，未得窮野步。","西軒白云閣，師辞洞庭寓。","越城今送归，心到焚香处。"]', '诗', 'shi', '', NULL, '送僧歸北巖寺 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5646af5-3b1d-4ef8-aa76-c94e9ecf8085', '寓言', '寓言', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["流年五十前，朝朝倚少年。","流年五十後，日日侵皓首。","非通非介人，誰論四十九。","賢哉蘧伯玉，清風獨不朽。"]', '["流年五十前，朝朝倚少年。","流年五十後，日日侵皓首。","非通非介人，誰論四十九。","賢哉蘧伯玉，清风独不朽。"]', '诗', 'shi', '', NULL, '寓言 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec8fe1f7-3c66-45fe-9065-ef1e33cedd7e', '長安書事', '长安书事', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["終不離青山，誰道雲無心。","卻是白雲士，有時出中林。","昨日擎紫泥，明日要黃金。","炎夏羣木死，北海驚波深。","伏蒲無一言，草疏賀德音。"]', '["終不離青山，誰道云無心。","卻是白云士，有时出中林。","昨日擎紫泥，明日要黄金。","炎夏羣木死，北海驚波深。","伏蒲無一言，草疏賀德音。"]', '诗', 'shi', '', NULL, '長安書事 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96fa9f49-f073-41df-8545-c22af44e51aa', '賈客', '賈客', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["大舟有深利，滄海無淺波。","利深波也深，君意竟如何。","鯨鯢齒上路，何如少經過。"]', '["大舟有深利，滄海無淺波。","利深波也深，君意竟如何。","鯨鯢齒上路，何如少經過。"]', '诗', 'shi', '', NULL, '賈客 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb6eb4a6-14bd-4b9e-8457-dea7db03fed3', '寄友人', '寄友人', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["君愛桃李花，桃李花易飄。","妾憐松柏色，松柏色難凋。","當年識君初，指期非一朝。","今辰見君意，日暮何蕭條。","入門有勢利，孰能無囂囂。"]', '["君愛桃李花，桃李花易飄。","妾怜松柏色，松柏色难凋。","當年識君初，指期非一朝。","今辰见君意，日暮何蕭條。","入门有勢利，孰能無囂囂。"]', '诗', 'shi', '', NULL, '寄友人 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aee0dd7-0ef1-49b9-a0e3-bb0de612f2e9', '落花', '落花', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["落花辭高樹，最是愁人處。","一一旋成泥，日暮有風雨。","不如沙上蓬，根斷隨長風。","飄然與道俱，無情任西東。"]', '["落花辞高樹，最是愁人处。","一一旋成泥，日暮有风雨。","不如沙上蓬，根斷隨长风。","飄然與道俱，無情任西东。"]', '诗', 'shi', '', NULL, '落花 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c18cf82b-636a-4891-83e5-369f0f6828e5', '寄徐正字夤', '寄徐正字夤', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["八月月如冰，登樓見姑射。","美人隔千里，相思無羽駕。","紅蘭裛露衰，誰以流光訝。","何當詩一句，同吟祝玄化。"]', '["八月月如冰，登楼见姑射。","美人隔千里，相思無羽駕。","紅蘭裛露衰，誰以流光訝。","何當诗一句，同吟祝玄化。"]', '诗', 'shi', '', NULL, '寄徐正字夤 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d041602-050f-46d6-a7aa-81848ed2b018', '秋夕貧居', '秋夕貧居', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["聽歌桂席闌，下馬槐煙裏。","豪門腐粱肉，窮巷思糠秕。","孤燈照獨吟，半壁秋花死。","遲明亦如晦，雞唱徒爲爾。"]', '["听歌桂席闌，下马槐煙裏。","豪门腐粱肉，窮巷思糠秕。","孤灯照独吟，半壁秋花死。","遲明亦如晦，雞唱徒爲爾。"]', '诗', 'shi', '', NULL, '秋夕貧居 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fef34aa-05e6-4c93-83dc-1de9c48d28df', '書懷寄友人', '书懷寄友人', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["此生如孤燈，素心挑易盡。","不及如頑石，非與磨礱近。","常思揚子雲，五藏曾離身。","寂寞一生中，千載空清芬。"]', '["此生如孤灯，素心挑易尽。","不及如頑石，非與磨礱近。","常思揚子云，五藏曾離身。","寂寞一生中，千載空清芬。"]', '诗', 'shi', '', NULL, '書懷寄友人 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a185f7e-a6a6-4d94-ab9e-40078ec107ef', '閨怨', '閨怨', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["妾家五嶺南，君戍三城北。","雁來雖有書，衡陽越不得。","別久情易料，豈在窺翰墨。","塞上無煙花，寧思妾顏色。"]', '["妾家五嶺南，君戍三城北。","雁来雖有书，衡陽越不得。","別久情易料，豈在窺翰墨。","塞上無煙花，寧思妾顏色。"]', '诗', 'shi', '', NULL, '閨怨 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6dcc6dc-5c43-41e1-baaa-57b4abd5b157', '喜翁文堯員外病起', '喜翁文堯員外病起', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["衛玠羊車懸，長卿駟馬姿。","天嫌太端正，神乃減風儀。","飲冰俾消渴，斷穀皆清羸。","越僧誇艾炷，秦女隔花枝。","自能論苦器，不假求良醫。","驚殺漳濱鬼，錯與劉生隨。","昨日已如虎，今朝謁荀池。","揚鞭入王門，四面人熙熙。","青桂任霜霰，尺璧無瑕疵。","迴塵却惆悵，歸闕難遲遲。"]', '["衛玠羊车懸，长卿駟马姿。","天嫌太端正，神乃減风儀。","饮冰俾消渴，斷穀皆清羸。","越僧誇艾炷，秦女隔花枝。","自能論苦器，不假求良醫。","驚殺漳濱鬼，錯與劉生隨。","昨日已如虎，今朝謁荀池。","揚鞭入王门，四面人熙熙。","青桂任霜霰，尺璧無瑕疵。","迴塵却惆悵，归闕难遲遲。"]', '诗', 'shi', '', NULL, '喜翁文堯員外病起 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9552aa0-460f-402b-9478-496784cccf05', '寄鄭縣李侍御', '寄鄭縣李侍御', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["古縣新煙火，東西入客詩。","靜長如假日，貧更甚閑時。","僧借松蘿住，人將雨雪期。","三年一官罷，嶽石看成碑。"]', '["古縣新煙火，东西入客诗。","静长如假日，貧更甚闲时。","僧借松蘿住，人將雨雪期。","三年一官罷，嶽石看成碑。"]', '诗', 'shi', '', NULL, '寄鄭縣李侍御 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df5bb60b-c2df-4352-b47a-91f129c7f45a', '上李補闕', '上李補闕', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["十洲非暫別，龍尾肯慵登。","諫草封山藥，朝衣施衲僧。","月留江客待，句歷釣船徵。","終恐林棲去，飡霞葉上昇。"]', '["十洲非暫別，龙尾肯慵登。","諫草封山藥，朝衣施衲僧。","月留江客待，句歷釣船徵。","終恐林棲去，飡霞葉上昇。"]', '诗', 'shi', '', NULL, '上李補闕 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c96262a0-1c55-425f-a44c-bb2ea789924c', '送李山人往湘中', '送李山人往湘中', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["漢渚往湘川，乘流入遠天。","新秋無岸水，明月有琴船。","露坐應通曉，萍居恐隔年。","嶽峰千萬仞，知上嘯猿巔。"]', '["漢渚往湘川，乘流入远天。","新秋無岸水，明月有琴船。","露坐應通晓，萍居恐隔年。","嶽峰千万仞，知上嘯猿巔。"]', '诗', 'shi', '', NULL, '送李山人往湘中 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a68c5026-aad1-4be5-857c-11b2c2e567df', '書崔少府居', '书崔少府居', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["魯史蜀琴旁，陶然舉一觴。","夕陽明島嶼，秋水淺池塘。","世亂憐官替，家貧值歲荒。","前峰亦曾宿，知有辟寒方。"]', '["魯史蜀琴旁，陶然舉一觴。","夕陽明島嶼，秋水淺池塘。","世亂怜官替，家貧值歲荒。","前峰亦曾宿，知有辟寒方。"]', '诗', 'shi', '', NULL, '書崔少府居 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('485cabe6-1709-438e-894c-7d994ca9d4a7', '敷水盧校書', '敷水盧校书', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["九霄無詔下，何事近清塵。","宅帶松蘿僻，日唯猿鳥親。","吟高僊掌月，期有洞庭人。","莫問煙霞句，懸知見嶽神。"]', '["九霄無詔下，何事近清塵。","宅带松蘿僻，日唯猿鸟親。","吟高僊掌月，期有洞庭人。","莫问煙霞句，懸知见嶽神。"]', '诗', 'shi', '', NULL, '敷水盧校書 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68697dad-9428-4dbb-87c9-4dcefd252287', '寄漢上友人', '寄漢上友人', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["襄漢多清景，東遊已不能。","蒹葭照流水，風雨撲孤燈。","獻賦聞新鴈，思山見去僧。","知君北來日，惆悵亦難勝。"]', '["襄漢多清景，东游已不能。","蒹葭照流水，风雨撲孤灯。","獻賦闻新鴈，思山见去僧。","知君北来日，惆悵亦难勝。"]', '诗', 'shi', '', NULL, '寄漢上友人 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10455ddd-4726-405e-8e76-c09f2d0b50d8', '貽林鐸', '貽林鐸', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["終被春闈屈，低回至白頭。","寄家僧許嶽，釣浦雨移洲。","戰士曾憐善，豪門不信愁。","王孫草還綠，何處擬羈遊。"]', '["終被春闈屈，低回至白头。","寄家僧許嶽，釣浦雨移洲。","戰士曾怜善，豪门不信愁。","王孫草還綠，何处擬羈游。"]', '诗', 'shi', '', NULL, '貽林鐸 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d2555a7-a672-4d0f-a20e-603a853b86f7', '書懷', '书懷', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["退耕逢歉歲，逐貢愧行朝。","道在愁雖淺，吟勞鬢欲凋。","破村虹入井，孤館客投魈。","誰怕秋風起，聽蟬度渭橋。"]', '["退耕逢歉歲，逐貢愧行朝。","道在愁雖淺，吟勞鬢欲凋。","破村虹入井，孤館客投魈。","誰怕秋风起，听蟬度渭橋。"]', '诗', 'shi', '', NULL, '書懷 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89147c08-d675-43b2-b51e-6fa3b331b736', '送陳明府歸衡陽', '送陳明府归衡陽', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["鶵鶴兼留下，單車出柳煙。","三年兩殊考，一日數離筵。","久別湖波綠，相思嶽月圓。","翠蘿曾隱處，定恐卻求仙。"]', '["鶵鹤兼留下，單车出柳煙。","三年兩殊考，一日數離筵。","久別湖波綠，相思嶽月圓。","翠蘿曾隐处，定恐卻求仙。"]', '诗', 'shi', '', NULL, '送陳明府歸衡陽 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c5d3de5-d043-4402-aa7c-c43cb484b5ac', '秋辭江南', '秋辞江南', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["灞陵橋上路，難負一年期。","積雨鴻來夜，重江客去時。","勞生多故疾，漸老少新知。","惆悵都堂內，無門雪滯遺。"]', '["灞陵橋上路，难負一年期。","積雨鴻来夜，重江客去时。","勞生多故疾，漸老少新知。","惆悵都堂內，無门雪滯遺。"]', '诗', 'shi', '', NULL, '秋辭江南 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f59119f6-d2db-4765-9b5c-b148d5888cc0', '入關旅次言懷', '入关旅次言懷', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["寸心唯自切，上國與誰期。","月晦時風雨，秋深日別離。","便休終未肯，已苦不能疑。","獨媿商山路，千年四皓祠。"]', '["寸心唯自切，上国與誰期。","月晦时风雨，秋深日別離。","便休終未肯，已苦不能疑。","独媿商山路，千年四皓祠。"]', '诗', 'shi', '', NULL, '入關旅次言懷 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7d00d66-b549-4f27-8cc4-cabc9f0025a8', '貽李山人', '貽李山人', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["野步愛江濱，江僧得見頻。","新文無古集，往事有清塵。","松竹寒時雨，池塘勝處春。","定應雲雨內，陶謝是前身。"]', '["野步愛江濱，江僧得见頻。","新文無古集，往事有清塵。","松竹寒时雨，池塘勝处春。","定應云雨內，陶謝是前身。"]', '诗', 'shi', '', NULL, '貽李山人 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02e74cea-0e1c-49cf-890d-be40de69a59f', '寄邊上從事', '寄邊上從事', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["斜日下孤城，長吟出點兵。","羽書和客卷，邊思雜詩情。","朔雪定鴻翼，西風嚴角聲。","吟餘多獨坐，沙月對樓生。"]', '["斜日下孤城，长吟出点兵。","羽书和客卷，邊思杂诗情。","朔雪定鴻翼，西风嚴角声。","吟餘多独坐，沙月对楼生。"]', '诗', 'shi', '', NULL, '寄邊上從事 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd5435fc-4df6-4485-ac5a-6b34bf5d3653', '題東林寺元祐上人院', '題东林寺元祐上人院', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["廬阜東林寺，良遊耻未曾。","半生隨計吏，一日對禪僧。","泉遠攜茶看，峰高結伴登。","迷津出門是，子細問三乘。"]', '["廬阜东林寺，良游耻未曾。","半生隨計吏，一日对禪僧。","泉远携茶看，峰高結伴登。","迷津出门是，子細问三乘。"]', '诗', 'shi', '', NULL, '題東林寺元祐上人院 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96c57b5b-6810-4365-a2d9-cdddb2e76b42', '送陳樵下第東歸', '送陳樵下第东归', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["青山烹茗石，滄海寄家船。","雖得重吟歷，終難任意眠。","碪疎連寺柳，風爽徹城泉。","送目紅蕉外，來期已杳然。"]', '["青山烹茗石，滄海寄家船。","雖得重吟歷，終难任意眠。","碪疎連寺柳，风爽徹城泉。","送目紅蕉外，来期已杳然。"]', '诗', 'shi', '', NULL, '送陳樵下第東歸 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ef03442-7fe5-4217-b866-1d9c0b9ec0c0', '寄陳磻隱居', '寄陳磻隐居', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["道經前輩許，名拔後時喧。","虛左中興榜，無先北海尊。","新文漢氏史，別墅謝公村。","須到三徵處，堂堂謁帝閽。"]', '["道經前輩許，名拔後时喧。","虛左中兴榜，無先北海尊。","新文漢氏史，別墅謝公村。","須到三徵处，堂堂謁帝閽。"]', '诗', 'shi', '', NULL, '寄陳磻隱居 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa8a28c1-b331-448b-9c08-d9467413fb3a', '寄林寬', '寄林寬', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["相知四十年，故國與長安。","俱喜今辰在，休論往歲難。","海鳴秋日黑，山直夏風寒。","終始前儒道，昇沈盡一般。"]', '["相知四十年，故国與长安。","俱喜今辰在，休論往歲难。","海鳴秋日黑，山直夏风寒。","終始前儒道，昇沈尽一般。"]', '诗', 'shi', '', NULL, '寄林寬 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25017fba-f180-4dc1-9968-7fd0362eedf3', '退居', '退居', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["老歸江上村，孤寂欲何言。","世亂時人物，家貧後子孫。","青山寒帶雨，古木夜啼猿。","惆悵西川舉，戎裝度劍門。"]', '["老归江上村，孤寂欲何言。","世亂时人物，家貧後子孫。","青山寒带雨，古木夜啼猿。","惆悵西川舉，戎裝度劍门。"]', '诗', 'shi', '', NULL, '退居 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb6893c6-25b1-49e7-8cc1-f67b172beaba', '送友人邊遊', '送友人邊游', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["銜杯國門外，分手見殘陽。","何日還南越，今朝往北荒。","砂城經雨壞，虜騎入秋狂。","親詠關山月，歸吟鬢的霜。"]', '["銜杯国门外，分手见殘陽。","何日還南越，今朝往北荒。","砂城經雨壞，虜騎入秋狂。","親詠关山月，归吟鬢的霜。"]', '诗', 'shi', '', NULL, '送友人邊遊 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b3f7bc9-3d23-4756-89b2-0a40ee1f18da', '下第出京', '下第出京', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["還失禮官求，花時出雍州。","一生爲遠客，幾處未曾遊。","故疾江南雨，單衣薊北秋。","茫茫數年事，今日淚俱流。"]', '["還失禮官求，花时出雍州。","一生爲远客，幾处未曾游。","故疾江南雨，單衣薊北秋。","茫茫數年事，今日泪俱流。"]', '诗', 'shi', '', NULL, '下第出京 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41b69f07-c4a0-4f82-ae2a-b339e3ebcef9', '遊東林寺', '游东林寺', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["平生愛山水，下馬虎溪時。","已到終嫌晚，重遊預作期。","寺寒三伏雨，松偃數朝枝。","翻譯如曾見，白蓮開舊池。"]', '["平生愛山水，下马虎溪时。","已到終嫌晚，重游預作期。","寺寒三伏雨，松偃數朝枝。","翻譯如曾见，白蓮开旧池。"]', '诗', 'shi', '', NULL, '遊東林寺 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('121b0bb9-666a-4f13-80da-999fa8b1f8d9', '贈懷光上人', '贈懷光上人', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["謝城還擁入，師以接人勞。","過午休齋慣，離經吐論高。","頂寒拳素髮，珠銳走紅絛。","終憶泉山寺，聽猨看海濤。"]', '["謝城還擁入，師以接人勞。","過午休斋慣，離經吐論高。","頂寒拳素髮，珠銳走紅絛。","終憶泉山寺，听猨看海濤。"]', '诗', 'shi', '', NULL, '贈懷光上人 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e8e5400-a783-425d-97c6-55e05cdfa277', '憶廬山舊遊', '憶廬山旧游', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["前年入廬嶽，數宿在靈溪。","殘燭松堂掩，孤峰月狖啼。","平生爲客老，勝境失雲棲。","縱有重遊日，煙霞會恐迷。"]', '["前年入廬嶽，數宿在靈溪。","殘燭松堂掩，孤峰月狖啼。","平生爲客老，勝境失云棲。","縱有重游日，煙霞會恐迷。"]', '诗', 'shi', '', NULL, '憶廬山舊遊 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab9040ce-f02e-4d91-8126-ca43a6fd7a69', '別友人', '別友人', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["莫恨東牆下，頻傷命不通。","苦心如有感，他日自推公。","雨夜扁舟發，花時別酒空。","越山煙翠在，終媿臥雲翁。"]', '["莫恨东牆下，頻傷命不通。","苦心如有感，他日自推公。","雨夜扁舟發，花时別酒空。","越山煙翠在，終媿臥云翁。"]', '诗', 'shi', '', NULL, '別友人 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4be06e0a-3786-4101-98f9-3da9642d2bc7', '陳侍御新居', '陳侍御新居', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["幕客開新第，詞人遍有詩。","山憐九仙近，石買太湖奇。","樹勢想高日，地形誇得時。","自然成避俗，休與白雲期。"]', '["幕客开新第，词人遍有诗。","山怜九仙近，石買太湖奇。","樹勢想高日，地形誇得时。","自然成避俗，休與白云期。"]', '诗', 'shi', '', NULL, '陳侍御新居 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e31e280-07e7-498f-9362-3cd49c0d0ae0', '寄從兄璞', '寄從兄璞', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["縱徴終不起，相與避煙塵。","待到中興日，同看上國春。","新詩說人盡，舊宅落花頻。","移覓深山住，啼猿作四鄰。"]', '["縱徴終不起，相與避煙塵。","待到中兴日，同看上国春。","新诗说人尽，旧宅落花頻。","移覓深山住，啼猿作四鄰。"]', '诗', 'shi', '', NULL, '寄從兄璞 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b3ca44-8ea0-4043-8e37-ad204a981360', '寄李校書遊簡寂觀', '寄李校书游簡寂观', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["古觀雲溪上，孤懷永夜中。","梧桐四更雨，山水一庭風。","詩得如何句，仙遊最勝宮。","卻愁逢羽客，相與入煙空。"]', '["古观云溪上，孤懷永夜中。","梧桐四更雨，山水一庭风。","诗得如何句，仙游最勝宮。","卻愁逢羽客，相與入煙空。"]', '诗', 'shi', '', NULL, '寄李校書遊簡寂觀 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c42b5436-3ab8-4263-ae8d-dc27bae4ca06', '寄友人山居', '寄友人山居', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["斷嶠滄江上，相思恨阻尋。","高齋秋不掩，幾夜月當吟。","落石有泉滴，盈庭無樹陰。","茫茫名利內，何以拂塵襟。"]', '["斷嶠滄江上，相思恨阻尋。","高斋秋不掩，幾夜月當吟。","落石有泉滴，盈庭無樹陰。","茫茫名利內，何以拂塵襟。"]', '诗', 'shi', '', NULL, '寄友人山居 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9628c479-0f1a-42ea-ac9b-b27498bd59af', '上刑部盧員外', '上刑部盧員外', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["誰識在官意，開門樹色間。","尋幽頻宿寺，乞假擬歸山。","半白侵吟鬢，微紅見藥顏。","不知琴月夜，幾客得同閑。"]', '["誰識在官意，开门樹色间。","尋幽頻宿寺，乞假擬归山。","半白侵吟鬢，微紅见藥顏。","不知琴月夜，幾客得同闲。"]', '诗', 'shi', '', NULL, '上刑部盧員外 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe957acd-1c58-4298-bd08-43ce2abadc03', '送友人遊邊', '送友人游邊', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["虜酒不能濃，縱傾愁亦重。","關河初落日，霜雪下窮冬。","野燒枯蓬旋，沙風匹馬衝。","薊門無易過，千里斷人蹤。"]', '["虜酒不能濃，縱傾愁亦重。","关河初落日，霜雪下窮冬。","野燒枯蓬旋，沙风匹马衝。","薊门無易過，千里斷人蹤。"]', '诗', 'shi', '', NULL, '送友人遊邊 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6902a217-01c8-4538-9f3e-d042e7570143', '和友人酬寄', '和友人酬寄', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["新發煙霞詠，高人得以傳。","吟銷松際雨，冷咽石間泉。","大國兵戈日，故鄉饑饉年。","相逢江海上，寧免一潸然。"]', '["新發煙霞詠，高人得以傳。","吟銷松際雨，冷咽石间泉。","大国兵戈日，故乡饑饉年。","相逢江海上，寧免一潸然。"]', '诗', 'shi', '', NULL, '和友人酬寄 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4e29f63-a381-4b4c-b888-fc9f293b748e', '下第', '下第', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["昨夜孤燈下，闌干泣數行。","辭家從早歲，落第在初場。","青草湖田改，單車客路忙。","何人立功業，新命到封王。"]', '["昨夜孤灯下，闌干泣數行。","辞家從早歲，落第在初場。","青草湖田改，單车客路忙。","何人立功業，新命到封王。"]', '诗', 'shi', '', NULL, '下第 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c929dac-3b44-4ce4-9f77-a9b26b1cb3aa', '過商山', '過商山', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["燕鴈一來後，人人盡到關。","如何衝臘雪，獨自過商山。","羸馬高坡下，哀猿絕壁間。","此心無處說，鬢向少年斑。"]', '["燕鴈一来後，人人尽到关。","如何衝臘雪，独自過商山。","羸马高坡下，哀猿絕壁间。","此心無处说，鬢向少年斑。"]', '诗', 'shi', '', NULL, '過商山 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d6ba67f-a834-47b8-a75a-550689740918', '旅懷', '旅懷', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["蕭颯聞風葉，驚時不自堪。","宦名中夜切，人事長年諳。","古畫僧留與，新知客遇談。","鄉心隨去鴈，一一到江南。"]', '["蕭颯闻风葉，驚时不自堪。","宦名中夜切，人事长年諳。","古畫僧留與，新知客遇談。","乡心隨去鴈，一一到江南。"]', '诗', 'shi', '', NULL, '旅懷 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('084b1d08-48d1-453c-842e-4f75dfd18f1a', '冬暮山舍喜標上人見訪', '冬暮山舍喜標上人见訪', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["寂寞三冬杪，深居業盡拋。","逕松開雪後，砌竹忽僧敲。","茗汲冰銷溜，鑪燒鵲去巢。","共談慵僻意，微日下林梢。"]', '["寂寞三冬杪，深居業尽拋。","逕松开雪後，砌竹忽僧敲。","茗汲冰銷溜，鑪燒鵲去巢。","共談慵僻意，微日下林梢。"]', '诗', 'shi', '', NULL, '冬暮山舍喜標上人見訪 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80ed0287-9ffd-4d97-a7d8-f39d6a7320d3', '關中言懷', '关中言懷', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["三秦五嶺意，不得不依然。","跡寓枯槐曲，業蕪芳草川。","花當落第眼，雨暗出城天。","層閣浮雲外，何人動管絃。"]', '["三秦五嶺意，不得不依然。","跡寓枯槐曲，業蕪芳草川。","花當落第眼，雨暗出城天。","層閣浮云外，何人动管絃。"]', '诗', 'shi', '', NULL, '關中言懷 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4a31726-f501-4c68-8e80-aca598d1cb30', '題友人山居', '題友人山居', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["到君棲跡所，竹逕與衡門。","亦在乾坤內，獨無塵俗喧。","新泉浮石蘚，崩壁露松根。","更說尋僧處，孤峰上嘯猿。"]', '["到君棲跡所，竹逕與衡门。","亦在乾坤內，独無塵俗喧。","新泉浮石蘚，崩壁露松根。","更说尋僧处，孤峰上嘯猿。"]', '诗', 'shi', '', NULL, '題友人山居 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fdeca5f-5bbe-4236-9ae6-acb7781bff92', '寄敷水盧校書', '寄敷水盧校书', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["諫省垂清論，仙曹豈久臨。","雖專良史業，未畏直臣心。","路入丹霄近，家藏華嶽深。","還如韓吏部，誰不望知音。"]', '["諫省垂清論，仙曹豈久臨。","雖專良史業，未畏直臣心。","路入丹霄近，家藏华嶽深。","還如韓吏部，誰不望知音。"]', '诗', 'shi', '', NULL, '寄敷水盧校書 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('567751ef-9c7d-48c8-8429-548cda0cc1d2', '贈明州霍員外', '贈明州霍員外', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["惠化如施雨，鄰州亦可依。","正衙無吏近，高會覺人稀。","海日旗邊出，沙禽角外歸。","四明多隱客，閑約到巖扉。"]', '["惠化如施雨，鄰州亦可依。","正衙無吏近，高會覺人稀。","海日旗邊出，沙禽角外归。","四明多隐客，闲約到巖扉。"]', '诗', 'shi', '', NULL, '贈明州霍員外 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b32a6b4f-1cc0-4728-8b6c-55ddfcfbfb40', '題友人山齋', '題友人山斋', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["疎竹漏斜暉，庭間陰復遺。","句成苔石茗，吟弄雪窗碁。","沙草泉經澀，林齋客集遲。","西風虛見逼，未擬問京師。"]', '["疎竹漏斜暉，庭间陰复遺。","句成苔石茗，吟弄雪窗碁。","沙草泉經澀，林斋客集遲。","西风虛见逼，未擬问京師。"]', '诗', 'shi', '', NULL, '題友人山齋 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e8b795-051f-4dc6-8715-81c42a313e89', '書事', '书事', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["望歲心空切，耕夫盡把弓。","千家數人在，一稅十年空。","沒陣風沙黑，燒城水陸紅。","飛章奏西蜀，明詔與殊功。"]', '["望歲心空切，耕夫尽把弓。","千家數人在，一稅十年空。","沒陣风沙黑，燒城水陸紅。","飞章奏西蜀，明詔與殊功。"]', '诗', 'shi', '', NULL, '書事 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f93bf510-a18b-4c66-9e7c-791db5882812', '題山居逸人', '題山居逸人', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["十畝餘蘆葦，新秋看雪霜。","世人誰到此，塵念自應忘。","斜日風收釣，深秋雨信梁。","不知雙闕下，何以謂軒裳。"]', '["十畝餘蘆葦，新秋看雪霜。","世人誰到此，塵念自應忘。","斜日风收釣，深秋雨信梁。","不知雙闕下，何以謂軒裳。"]', '诗', 'shi', '', NULL, '題山居逸人 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b85072e7-c23d-46ae-83fc-a2fb2a1473a1', '題鄭山人居', '題鄭山人居', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["履迹遍莓苔，幽枝間藥裁。","枯杉[擎]雪朵，破牖觸風開。","泉自孤峰落，人從諸洞來。","終期宿清夜，斟茗說天台。"]', '["履迹遍莓苔，幽枝间藥裁。","枯杉[擎]雪朵，破牖觸风开。","泉自孤峰落，人從諸洞来。","終期宿清夜，斟茗说天台。"]', '诗', 'shi', '', NULL, '題鄭山人居 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa3901b0-d064-470a-bd8b-d67643063189', '秋晚山居', '秋晚山居', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["爽氣遍搜空，難堪倚望中。","孤煙愁落日，高木病西風。","山寂樵聲出，露涼蟬思窮。","此時塵外事，幽默幾人同。"]', '["爽氣遍搜空，难堪倚望中。","孤煙愁落日，高木病西风。","山寂樵声出，露涼蟬思窮。","此时塵外事，幽默幾人同。"]', '诗', 'shi', '', NULL, '秋晚山居 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5bec5cf-a489-46cc-9cc3-f6e77ba5f3bc', '遊山', '游山', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["洞門穿瀑布，塵世豈能通。","曾有遊山客，來逢採藥翁。","異花尋復失，幽逕躡還窮。","擬作經宵計，風雷立滿空。"]', '["洞门穿瀑布，塵世豈能通。","曾有游山客，来逢採藥翁。","異花尋复失，幽逕躡還窮。","擬作經宵計，风雷立满空。"]', '诗', 'shi', '', NULL, '遊山 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e81d753-2d77-4349-b463-135f61da74d7', '題王侍御宅內亭子', '題王侍御宅內亭子', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["俗間塵外境，郭內宅中亭。","或有人家創，還無蓮幕馨。","石曾湖岸見，琴誤嶽樓聽。","來客頻頻說，終須作畫屏。"]', '["俗间塵外境，郭內宅中亭。","或有人家創，還無蓮幕馨。","石曾湖岸见，琴誤嶽楼听。","来客頻頻说，終須作畫屏。"]', '诗', 'shi', '', NULL, '題王侍御宅內亭子 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36907cec-059f-4a2f-8a33-8fe0dac48a73', '題道成上人院', '題道成上人院', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["花宮城郭內，師住亦清涼。","何必天台寺，幽蟬瀑布房。","簟舒湘竹滑，茗煮蜀芽香。","更看道高處，居侯題翠梁。"]', '["花宮城郭內，師住亦清涼。","何必天台寺，幽蟬瀑布房。","簟舒湘竹滑，茗煮蜀芽香。","更看道高处，居侯題翠梁。"]', '诗', 'shi', '', NULL, '題道成上人院 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('febf4670-d876-4013-a10c-58a5f21a9b2e', '貧居冬杪', '貧居冬杪', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["數塞未求通，吾非學養蒙。","窮居歲杪雨，孤坐夜深風。","年長慙昭代，才微辱至公。","還愁把春酒，雙淚汚杯中。"]', '["數塞未求通，吾非学養蒙。","窮居歲杪雨，孤坐夜深风。","年长慙昭代，才微辱至公。","還愁把春酒，雙泪汚杯中。"]', '诗', 'shi', '', NULL, '貧居冬杪 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d899491-16ef-47e3-a9eb-bf531fca1183', '貽張蠙', '貽張蠙', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["夢思非一日，攜手却淒涼。","詩見江南雹，遊經塞北霜。","驅車先五漏，把菊後重陽。","惆悵天邊桂，誰教歲歲香。"]', '["梦思非一日，携手却淒涼。","诗见江南雹，游經塞北霜。","驱车先五漏，把菊後重陽。","惆悵天邊桂，誰教歲歲香。"]', '诗', 'shi', '', NULL, '貽張蠙 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd3aecd2-6f77-4b14-a732-3786f0173b0d', '晚春關中', '晚春关中', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["忍歷通莊出，東風舞酒旗。","百花無看處，三月到殘時。","遊塞聞兵起，還吳值歲饑。","定唯荒寺裏，坐與噪蟬期。"]', '["忍歷通莊出，东风舞酒旗。","百花無看处，三月到殘时。","游塞闻兵起，還吳值歲饑。","定唯荒寺裏，坐與噪蟬期。"]', '诗', 'shi', '', NULL, '晚春關中 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adc79a5d-51fb-4330-bd4d-8d8442ab782f', '河梁', '河梁', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["五原人走馬，昨夜到京師。","繡戶新夫婦，河梁生別離。","隴花開不豔，羌笛靜猶悲。","惆悵良哉輔，鏗鏘立鳳池。"]', '["五原人走马，昨夜到京師。","繡戶新夫婦，河梁生別離。","隴花开不豔，羌笛静猶悲。","惆悵良哉輔，鏗鏘立鳳池。"]', '诗', 'shi', '', NULL, '河梁 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ddf7d55-5f6b-46f3-8f58-43f472de0512', '送翁拾遺', '送翁拾遺', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["還家俄赴闕，別思肯淒淒。","山坐軺車看，詩持諫筆題。","天開中國大，地設四維低。","拜舞吾君後，青雲更有梯。"]', '["還家俄赴闕，別思肯淒淒。","山坐軺车看，诗持諫笔題。","天开中国大，地設四維低。","拜舞吾君後，青云更有梯。"]', '诗', 'shi', '', NULL, '送翁拾遺 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e16df445-7b88-48d7-aae9-3c1ef334b813', '逢友人', '逢友人', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["彼此若飄蓬，二年何所從。","帝都秋未入，江館夜相逢。","瘴嶺行衝夏，邊沙住隔冬。","旅愁論未盡，古寺扣晨鍾。"]', '["彼此若飄蓬，二年何所從。","帝都秋未入，江館夜相逢。","瘴嶺行衝夏，邊沙住隔冬。","旅愁論未尽，古寺扣晨鍾。"]', '诗', 'shi', '', NULL, '逢友人 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b3db2f7-da36-49ef-b64a-38040045c9d8', '寄湘中鄭明府', '寄湘中鄭明府', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["縣與白雲連，滄洲況縣前。","嶽僧同夜坐，江月看秋圓。","琴拂莎庭石，茶擔乳洞泉。","莫耽雲水興，疲俗待君痊。"]', '["縣與白云連，滄洲況縣前。","嶽僧同夜坐，江月看秋圓。","琴拂莎庭石，茶擔乳洞泉。","莫耽云水兴，疲俗待君痊。"]', '诗', 'shi', '', NULL, '寄湘中鄭明府 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56735a45-59c6-4268-87c0-a4ae83058bdc', '寄少常盧同年', '寄少常盧同年', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["官拜少常休，青緺換鹿裘。","狂歌離樂府，醉夢到瀛洲。","古器巖耕得，神方客謎留。","清溪莫沈釣，王者或畋遊。"]', '["官拜少常休，青緺換鹿裘。","狂歌離乐府，醉梦到瀛洲。","古器巖耕得，神方客謎留。","清溪莫沈釣，王者或畋游。"]', '诗', 'shi', '', NULL, '寄少常盧同年 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab523f2-027c-4478-90b8-7411413ecdd7', '傷翁外甥', '傷翁外甥', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["江頭去時路，歸客幾紛紛。","獨在異鄉歿，若爲慈母聞。","青春成大夜，新雨壞孤墳。","應作芝蘭出，泉臺月桂分。"]', '["江头去时路，归客幾紛紛。","独在異乡歿，若爲慈母闻。","青春成大夜，新雨壞孤墳。","應作芝蘭出，泉台月桂分。"]', '诗', 'shi', '', NULL, '傷翁外甥 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0335c1ce-cafe-4663-9ec2-85f03688537a', '東山之遊未遂漸逼行期作四十字奉寄翁文堯員外', '东山之游未遂漸逼行期作四十字奉寄翁文堯員外', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["軺車難久駐，須到別離時。","北闕定歸去，東山空作期。","綠苔勞掃徑，丹鳳欲銜詞。","楊柳開帆岸，今朝淚已垂。"]', '["軺车难久駐，須到別離时。","北闕定归去，东山空作期。","綠苔勞掃徑，丹鳳欲銜词。","楊柳开帆岸，今朝泪已垂。"]', '诗', 'shi', '', NULL, '東山之遊未遂漸逼行期作四十字奉寄翁文堯員外 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('704fce76-2a06-4c39-9b5b-eda2bf50325b', '送林寬下第東歸', '送林寬下第东归', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["爲君惆悵惜離京，年少無人有屈名。","積雪未開移發日，鳴蟬初急說來程。","楚天去路過飛鴈，灞岸歸塵觸鎖城。","又得新詩幾章別，煙村竹逕海濤聲。"]', '["爲君惆悵惜離京，年少無人有屈名。","積雪未开移發日，鳴蟬初急说来程。","楚天去路過飞鴈，灞岸归塵觸鎖城。","又得新诗幾章別，煙村竹逕海濤声。"]', '诗', 'shi', '', NULL, '送林寬下第東歸 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c580cad-ce6b-4637-b1e3-90ac518cd0a7', '商山贈隱者', '商山贈隐者', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["誰不相逢話息機，九重城裏自依依。","蓬萊水淺有人說，商洛山高無客歸。","數隻珍禽寒月在，千株古木熱時稀。","西窓昨夜鳴蛩盡，知夢芝翁起扣扉。"]', '["誰不相逢話息機，九重城裏自依依。","蓬萊水淺有人说，商洛山高無客归。","數隻珍禽寒月在，千株古木熱时稀。","西窓昨夜鳴蛩尽，知梦芝翁起扣扉。"]', '诗', 'shi', '', NULL, '商山贈隱者 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6353732-05f3-4cfd-931c-7b544b81cb7c', '送二友遊湘中', '送二友游湘中', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["千里楚江新雨晴，同征肯恨迹如萍。","孤舟泊處聯詩句，八月中旬宿洞庭。","爲客早悲煙草綠，移家晚失嶽峯青。","今來無計相從去，歸日汀洲乞畫屏。"]', '["千里楚江新雨晴，同征肯恨迹如萍。","孤舟泊处聯诗句，八月中旬宿洞庭。","爲客早悲煙草綠，移家晚失嶽峯青。","今来無計相從去，归日汀洲乞畫屏。"]', '诗', 'shi', '', NULL, '送二友遊湘中 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab535a2-e9ba-4df6-b85b-3f3352a6de24', '塞下', '塞下', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["匹馬蕭蕭去不前，平蕪千里見窮邊。","關山色死秋深日，鼓角聲沈霜重天。","荒骨或銜殘鐵露，驚風時掠暮沙旋。","隴頭冤氣無歸處，化作陰雲飛杳然。"]', '["匹马蕭蕭去不前，平蕪千里见窮邊。","关山色死秋深日，鼓角声沈霜重天。","荒骨或銜殘鐵露，驚风时掠暮沙旋。","隴头冤氣無归处，化作陰云飞杳然。"]', '诗', 'shi', '', NULL, '塞下 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21ac8527-c22c-4cab-9702-2e7745b52c4d', '下第東歸留辭刑部鄭郎中諴', '下第东归留辞刑部鄭郎中諴', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["去違知己住違親，欲發羸蹄進退頻。","萬里家山歸養志，數年門館受恩身。","鶯聲歷歷秦城曉，柳色依依灞水春。","明日藍田關外路，連天風雨一行人。"]', '["去違知己住違親，欲發羸蹄進退頻。","万里家山归養志，數年门館受恩身。","鶯声歷歷秦城晓，柳色依依灞水春。","明日藍田关外路，連天风雨一行人。"]', '诗', 'shi', '', NULL, '下第東歸留辭刑部鄭郎中諴 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('435a69ed-3f9f-48e7-b980-17878737d255', '寄懷南北故人', '寄懷南北故人', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["秋風昨夜落芙蕖，一片離心到外區。","南海浪高書墮水，北州城破客降胡。","玉窗挑鳳佳人老，綺陌啼鶯碧樹枯。","嶺上青風隴頭月，時通魂夢出來無。"]', '["秋风昨夜落芙蕖，一片離心到外區。","南海浪高书墮水，北州城破客降胡。","玉窗挑鳳佳人老，綺陌啼鶯碧樹枯。","嶺上青风隴头月，时通魂梦出来無。"]', '诗', 'shi', '', NULL, '寄懷南北故人 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73d80199-550f-4669-86ba-99930e2b3650', '關中言懷', '关中言懷', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["事事朝朝委一尊，自知無復解趨奔。","試期交後猶爲客，公道開時敢說冤。","窮巷住來經積雨，故山歸去見荒村。","舉頭盡到斷腸處，何必秋風江上猿。"]', '["事事朝朝委一尊，自知無复解趨奔。","試期交後猶爲客，公道开时敢说冤。","窮巷住来經積雨，故山归去见荒村。","舉头尽到斷腸处，何必秋风江上猿。"]', '诗', 'shi', '', NULL, '關中言懷 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25211bfb-1557-4b5a-9de6-03e56fea8577', '閨怨', '閨怨', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["寸心杳與馬蹄隨，如蛻形容在錦帷。","江上月明船發後，花間日暮信迴時。","五陵夜作酬恩計，四塞秋爲破虜期。","待到乘軺入門處，淚珠流盡玉顏衰。"]', '["寸心杳與马蹄隨，如蛻形容在錦帷。","江上月明船發後，花间日暮信迴时。","五陵夜作酬恩計，四塞秋爲破虜期。","待到乘軺入门处，泪珠流尽玉顏衰。"]', '诗', 'shi', '', NULL, '閨怨 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dccd2ff5-3019-49c7-939f-29c1d419bd7a', '旅懷', '旅懷', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["未喫金丹看十洲，乃將身世作仇讎。","羈遊數地值兵亂，宿在孤城聞雨秋。","東越雲山卻思隱，西秦霜霰苦頻留。","他人折盡月中桂，惆悵當年江上鷗。"]', '["未喫金丹看十洲，乃將身世作仇讎。","羈游數地值兵亂，宿在孤城闻雨秋。","东越云山卻思隐，西秦霜霰苦頻留。","他人折尽月中桂，惆悵當年江上鷗。"]', '诗', 'shi', '', NULL, '旅懷 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c6e19dd-95cd-4885-90b0-afca61f6bbec', '別友人', '別友人', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["已喜相逢又怨嗟，十年飄泊在京華。","大朝多事還停舉，故國經荒未有家。","鳥帶夕陽投遠樹，人衝臘雪往邊沙。","夢魂空繫瀟湘岸，煙水茫茫蘆葦花。"]', '["已喜相逢又怨嗟，十年飄泊在京华。","大朝多事還停舉，故国經荒未有家。","鸟带夕陽投远樹，人衝臘雪往邊沙。","梦魂空繫瀟湘岸，煙水茫茫蘆葦花。"]', '诗', 'shi', '', NULL, '別友人 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8c11cc7-cb92-40d5-8924-9f6cac2d697d', '寄羅浮山道者二首 一', '寄羅浮山道者二首 一', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["天際雙山壓海濆，天漫絕頂海漫根。","時聞雷雨驚樵客，長有龍蛇護洞門。","泉石暮含朱槿書，煙霞冬閉木綿溫。","林間學道如容我，今便辭他寵辱喧。"]', '["天際雙山壓海濆，天漫絕頂海漫根。","时闻雷雨驚樵客，长有龙蛇護洞门。","泉石暮含朱槿书，煙霞冬閉木綿溫。","林间学道如容我，今便辞他寵辱喧。"]', '诗', 'shi', '', NULL, '寄羅浮山道者二首 一 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c8d4916-c8ad-46a9-bfcc-778f2b56a17a', '寄羅浮山道者二首 二', '寄羅浮山道者二首 二', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["有人曾見洞中仙，纔到人間便越年。","金鼎藥成龍入海，玉函書發鶴歸天。","樓開石脉千尋直，山拆鼇鱗一半膻。","誰到月明朝禮處，翠巖深鎖荔枝煙。"]', '["有人曾见洞中仙，纔到人间便越年。","金鼎藥成龙入海，玉函书發鹤归天。","楼开石脉千尋直，山拆鼇鱗一半膻。","誰到月明朝禮处，翠巖深鎖荔枝煙。"]', '诗', 'shi', '', NULL, '寄羅浮山道者二首 二 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bd8e1b2-29a4-4ea1-b42b-3d81ab4a2fd3', '喜侯舍人蜀中新命三首 一', '喜侯舍人蜀中新命三首 一', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["八都詞客漫喧然，誰解飛揚誥誓間。","五色綵毫裁鳳詔，九重天子豁龍顏。","巴山月在趨朝去，錦水煙生入閤還。","謀及中興多少事，莫愁明月不收關。"]', '["八都词客漫喧然，誰解飞揚誥誓间。","五色綵毫裁鳳詔，九重天子豁龙顏。","巴山月在趨朝去，錦水煙生入閤還。","謀及中兴多少事，莫愁明月不收关。"]', '诗', 'shi', '', NULL, '喜侯舍人蜀中新命三首 一 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1cf1bba-7961-47bd-b372-2fa416236748', '喜侯舍人蜀中新命三首 二', '喜侯舍人蜀中新命三首 二', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["却搜文學起吾唐，暫失都城亦未妨。","錦里幸爲丹鳳闕，幕賓徴出紫微郎。","來時走馬隨中使，到日援毫定外方。","若以掌言看諫獵，相如從此病輝光。"]', '["却搜文学起吾唐，暫失都城亦未妨。","錦里幸爲丹鳳闕，幕賓徴出紫微郎。","来时走马隨中使，到日援毫定外方。","若以掌言看諫獵，相如從此病輝光。"]', '诗', 'shi', '', NULL, '喜侯舍人蜀中新命三首 二 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fe14d7e-13e9-4c74-a6c1-1f3d1eae81f5', '喜侯舍人蜀中新命三首 三', '喜侯舍人蜀中新命三首 三', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["賈誼纔承宣室召，左思唯預秘書流。","賦家達者無過此，翰苑今朝是獨遊。","立被御爐煙氣逼，吟經棧閣雨聲秋。","內人未識江淹筆，竟問當時不早求。"]', '["賈誼纔承宣室召，左思唯預秘书流。","賦家達者無過此，翰苑今朝是独游。","立被御爐煙氣逼，吟經棧閣雨声秋。","內人未識江淹笔，竟问當时不早求。"]', '诗', 'shi', '', NULL, '喜侯舍人蜀中新命三首 三 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2383203-7f9a-4be1-943f-470e77a2df3c', '經安州感故鄭郎中二首 一', '經安州感故鄭郎中二首 一', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["雲夢江頭見故城，人間四十載垂名。","馬蹄踐處東風急，雞舌銷時北闕驚。","嶽客出來尋古劍，野猨相聚呌孤塋。","騰身飛上鳳凰閣，惆悵終乖吾黨情。"]', '["云梦江头见故城，人间四十載垂名。","马蹄踐处东风急，雞舌銷时北闕驚。","嶽客出来尋古劍，野猨相聚呌孤塋。","腾身飞上鳳凰閣，惆悵終乖吾黨情。"]', '诗', 'shi', '', NULL, '經安州感故鄭郎中二首 一 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd74769a-356b-4c8d-b60d-539f57e6d5da', '經安州感故鄭郎中二首 二', '經安州感故鄭郎中二首 二', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["錦帳先生作牧州，干戈缺後見荒丘。","兼無姓賈兒童在，空有還珠煙水流。","江句行人吟刻石，月腸是處象登樓。","旅魂頻此歸來否，千載雲山屬一遊。"]', '["錦帳先生作牧州，干戈缺後见荒丘。","兼無姓賈兒童在，空有還珠煙水流。","江句行人吟刻石，月腸是处象登楼。","旅魂頻此归来否，千載云山屬一游。"]', '诗', 'shi', '', NULL, '經安州感故鄭郎中二首 二 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d7ada33-0e7c-4eb0-ba44-cdc2f184a807', '出京別崔學士', '出京別崔学士', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["一從門館遍投文，旋忝恩知驟出羣。","不道鶴雞殊羽翼，許依龍虎借風雲。","命奇未便乘東律，言重終期雪北軍。","欲逐飄蓬向岐路，數宵垂淚戀清芬。"]', '["一從门館遍投文，旋忝恩知驟出羣。","不道鹤雞殊羽翼，許依龙虎借风云。","命奇未便乘东律，言重終期雪北軍。","欲逐飄蓬向岐路，數宵垂泪戀清芬。"]', '诗', 'shi', '', NULL, '出京別崔學士 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('685148ce-e01b-47cc-baea-6739abf73ddd', '鴈', '鴈', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["楚岸花晴塞柳衰，年年南北去來期。","江城日暮見飛處，旅館月明聞過時。","萬里風霜休更恨，滿川煙草且須疑。","洞庭雲水瀟湘雨，好把寒更一一知。"]', '["楚岸花晴塞柳衰，年年南北去来期。","江城日暮见飞处，旅館月明闻過时。","万里风霜休更恨，满川煙草且須疑。","洞庭云水瀟湘雨，好把寒更一一知。"]', '诗', 'shi', '', NULL, '鴈 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a8d61ae-cf5d-418b-86a5-d48214085f99', '寄越從事林嵩侍御', '寄越從事林嵩侍御', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["子虛詞賦動君王，誰不期君入對敭。","莫戀兔園留看雪，已乘驄馬合凌霜。","路歸天上行方別，道在人間久便香。","應念都城舊吟客，十年蹤跡委滄浪。"]', '["子虛词賦动君王，誰不期君入对敭。","莫戀兔园留看雪，已乘驄马合凌霜。","路归天上行方別，道在人间久便香。","應念都城旧吟客，十年蹤跡委滄浪。"]', '诗', 'shi', '', NULL, '寄越從事林嵩侍御 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf4c380-5e9a-485b-a947-b51ff2006b38', '長安書事', '长安书事', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["一年年課數千言，口祝心祠挈出門。","孤進難時誰肯薦，主司通處不須論。","頻秋入自邊城雪，昨日聽來嶺樹猨。","若有水田過十畝，早應歸去狄江村。"]', '["一年年課數千言，口祝心祠挈出门。","孤進难时誰肯薦，主司通处不須論。","頻秋入自邊城雪，昨日听来嶺樹猨。","若有水田過十畝，早應归去狄江村。"]', '诗', 'shi', '', NULL, '長安書事 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('663ead91-8308-46a4-a57b-2ae7c39b05df', '旅懷寄友人', '旅懷寄友人', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["重疊愁腸只自知，苦於吞蘖亂於絲。","一船風雨分襟處，千里煙波迴首時。","故國田園經戰後，窮荒日月逼秋期。","鳴蟬似會悠揚意，陌上聲聲怨柳衰。"]', '["重叠愁腸只自知，苦於吞蘖亂於絲。","一船风雨分襟处，千里煙波迴首时。","故国田园經戰後，窮荒日月逼秋期。","鳴蟬似會悠揚意，陌上声声怨柳衰。"]', '诗', 'shi', '', NULL, '旅懷寄友人 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e18d109-7be2-4bd7-b2a1-fb39ae9c50cd', '寄蔣先輩', '寄蔣先輩', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["夫差宮苑悉蒼苔，攜客朝遊夜未回。","塚上題詩蘇小見，江頭酹酒伍員來。","秋風急處煙花落，明月中時水寺開。","千載三吳有高跡，虎丘山翠益崔嵬。"]', '["夫差宮苑悉蒼苔，携客朝游夜未回。","塚上題诗蘇小见，江头酹酒伍員来。","秋风急处煙花落，明月中时水寺开。","千載三吳有高跡，虎丘山翠益崔嵬。"]', '诗', 'shi', '', NULL, '寄蔣先輩 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17e4c958-635b-44d8-8be9-2d772d75f693', '旅懷', '旅懷', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["雪貌潛凋雪髮生，故園魂斷弟兼兄。","十年除夜在孤館，萬里一身求大名。","空有新詩高華嶽，已無丹懇出秦城。","侯門莫問曾遊處，槐柳影中肝膽傾。"]', '["雪貌潛凋雪髮生，故园魂斷弟兼兄。","十年除夜在孤館，万里一身求大名。","空有新诗高华嶽，已無丹懇出秦城。","侯门莫问曾游处，槐柳影中肝膽傾。"]', '诗', 'shi', '', NULL, '旅懷 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cf4dd03-6197-40cb-b295-d1bb7cf4a6d0', '放榜日', '放榜日', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["吾唐取士最堪誇，仙榜標名出曙霞。","白馬嘶風三十轡，朱門秉燭一千家。","郄詵聯臂昇天路，宣聖飛章奏日華。","歲歲人人來不得，曲江煙水杏園花。"]', '["吾唐取士最堪誇，仙榜標名出曙霞。","白马嘶风三十轡，朱门秉燭一千家。","郄詵聯臂昇天路，宣聖飞章奏日华。","歲歲人人来不得，曲江煙水杏园花。"]', '诗', 'shi', '', NULL, '放榜日 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('819b396b-71f5-4e41-937d-cf1d64c89c33', '二月二日宴中貽同年封先輩渭', '二月二日宴中貽同年封先輩渭', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["帝堯城裏日銜杯，每倚嵇康到玉頹。","桂苑五更聽榜後，蓬山二月看花開。","垂名入甲成龍去，列姓如丁作鶴來。","同戴大恩何處報，永言交道契陳雷。"]', '["帝堯城裏日銜杯，每倚嵇康到玉頹。","桂苑五更听榜後，蓬山二月看花开。","垂名入甲成龙去，列姓如丁作鹤来。","同戴大恩何处報，永言交道契陳雷。"]', '诗', 'shi', '', NULL, '二月二日宴中貽同年封先輩渭 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f15a46a9-3e02-43fa-a7e7-3d3f6cd711e0', '新野道中', '新野道中', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["野堂如雪草如茵，光武城邊一水濱。","越客歸遙春有雨，杜鵑啼苦夜無人。","東堂歲去銜杯嬾，南浦期來落淚頻。","莫道還家不惆悵，蘇秦羈旅長卿貧。"]', '["野堂如雪草如茵，光武城邊一水濱。","越客归遙春有雨，杜鵑啼苦夜無人。","东堂歲去銜杯嬾，南浦期来落泪頻。","莫道還家不惆悵，蘇秦羈旅长卿貧。"]', '诗', 'shi', '', NULL, '新野道中 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95769f6e-18f0-47cd-9c11-ccbfa7cf7ce4', '酬俞鈞', '酬俞鈞', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["鄉書一忝薦延恩，二紀三朝泣省門。","雖忝立名經聖鑒，敢期興詠疊嘉言。","莫論蟾月無梯接，大底龍津有浪翻。","今日朝廷推草澤，佇君承詔出雲根。"]', '["乡书一忝薦延恩，二紀三朝泣省门。","雖忝立名經聖鑒，敢期兴詠叠嘉言。","莫論蟾月無梯接，大底龙津有浪翻。","今日朝廷推草澤，佇君承詔出云根。"]', '诗', 'shi', '', NULL, '酬俞鈞 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50dfc0f1-d8d1-43de-b7c8-b077c3dc449f', '寄同年崔學士', '寄同年崔学士', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["半因同醉杏花園，塵忝鴻鑪與鑄顏。","已脫素衣酬素髮，敢持青桂愛青山。","雖知珠樹懸天上，終賴銀河接世間。","畢使海涯能拔宅，三秦二十四畿寰。"]', '["半因同醉杏花园，塵忝鴻鑪與鑄顏。","已脫素衣酬素髮，敢持青桂愛青山。","雖知珠樹懸天上，終賴銀河接世间。","畢使海涯能拔宅，三秦二十四畿寰。"]', '诗', 'shi', '', NULL, '寄同年崔學士 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22bc27f4-9c98-43d1-849d-25377a97e9d7', '御試二首 一', '御試二首 一', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["已表隋珠各自攜，更從瓊殿立丹梯。","九華燈作三條燭，萬乘君懸四首題。","靈鳳敢期翻雪羽，洞簫應或諷金閨。","明朝莫惜場場醉，青桂新香有紫泥。"]', '["已表隋珠各自携，更從瓊殿立丹梯。","九华灯作三條燭，万乘君懸四首題。","靈鳳敢期翻雪羽，洞簫應或諷金閨。","明朝莫惜場場醉，青桂新香有紫泥。"]', '诗', 'shi', '', NULL, '御試二首 一 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2021be1c-b9f4-45a7-bea9-673c4b6f2a85', '御試二首 二', '御試二首 二', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["六曹三省列簪裾，丹詔宣來試士初。","不是玉皇疑羽客，要教金榜帶天書。","詞臣假寐題黃絹，宮女敲銅奏子虛。","御目四篇酬九百，敢從燈下畧躊躇。"]', '["六曹三省列簪裾，丹詔宣来試士初。","不是玉皇疑羽客，要教金榜带天书。","词臣假寐題黄絹，宮女敲銅奏子虛。","御目四篇酬九百，敢從灯下畧躊躇。"]', '诗', 'shi', '', NULL, '御試二首 二 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('371eaae7-d6a0-47ae-8092-93f1badb330b', '寄陳侍御', '寄陳侍御', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["千年二相未全誇，猶闕閩城賀降麻。","何必錦衣須太守，別無蓮幕勝王家。","醴泉湧處休論水，黃菊開時獨是花。","九級燕金滿尊酒，卻愁隨詔謁承華。"]', '["千年二相未全誇，猶闕閩城賀降麻。","何必錦衣須太守，別無蓮幕勝王家。","醴泉湧处休論水，黄菊开时独是花。","九級燕金满尊酒，卻愁隨詔謁承华。"]', '诗', 'shi', '', NULL, '寄陳侍御 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68ab63c2-34af-464b-974b-b82adc3b2464', '酬徐正字夤', '酬徐正字夤', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["已免蹉跎負歲華，敢辭霜鬢雪呈花。","名從兩榜考昇第，官自三台追起家。","疋馬有期歸輦轂，故山無計戀桑麻。","莫言蓬閣從容久，披處終知金在砂。"]', '["已免蹉跎負歲华，敢辞霜鬢雪呈花。","名從兩榜考昇第，官自三台追起家。","疋马有期归輦轂，故山無計戀桑麻。","莫言蓬閣從容久，披处終知金在砂。"]', '诗', 'shi', '', NULL, '酬徐正字夤 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47531e5a-70a7-4419-9f91-90ce7221d62d', '辭相府', '辞相府', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["從漢至唐分五州，誰爲將相作諸侯。","閩江似鏡正堪戀，秦客如蓬難久留。","匹馬忍辭藩屏去，小才寧副廟堂求。","今朝拜別幡幢下，雙淚如珠滴不休。"]', '["從漢至唐分五州，誰爲將相作諸侯。","閩江似镜正堪戀，秦客如蓬难久留。","匹马忍辞藩屏去，小才寧副廟堂求。","今朝拜別幡幢下，雙泪如珠滴不休。"]', '诗', 'shi', '', NULL, '辭相府 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('776a5065-9c8f-4c93-bfb5-96e98bc27836', '寄羅郎中隱', '寄羅郎中隐', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["休向中興雪至冤，錢塘江上看濤翻。","三徵不起時賢議，九轉終成道者言。","綠酒千杯腸已爛，新詩數首骨猶存。","瑤蟾若使知人事，仙桂應遭蠹卻根。"]', '["休向中兴雪至冤，錢塘江上看濤翻。","三徵不起时賢議，九轉終成道者言。","綠酒千杯腸已爛，新诗數首骨猶存。","瑤蟾若使知人事，仙桂應遭蠹卻根。"]', '诗', 'shi', '', NULL, '寄羅郎中隱 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ed3198c-f68a-45c9-9280-d90b3f8a1547', '江行遇王侍御', '江行遇王侍御', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["數年分散秦吳隔，暫泊官船浦柳中。","新草軍書名更重，久辭山逕業應空。","渡頭潮落將行客，天際風高未宿鴻。","此日相逢魂合斷，賴君身事漸飛沖。"]', '["數年分散秦吳隔，暫泊官船浦柳中。","新草軍书名更重，久辞山逕業應空。","渡头潮落將行客，天際风高未宿鴻。","此日相逢魂合斷，賴君身事漸飞沖。"]', '诗', 'shi', '', NULL, '江行遇王侍御 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b7bd93c-fa2e-4ce8-b239-62334fa1f94e', '客舍秋晚夜懷故山', '客舍秋晚夜懷故山', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["寥寥深巷客中居，況值窮秋百事疎。","孤枕憶山千里外，破窗聞雨五更初。","經年荒草侵幽逕，幾樹西風鎖弊廬。","長繫寸心歸未得，起挑殘燭獨躊躇。"]', '["寥寥深巷客中居，況值窮秋百事疎。","孤枕憶山千里外，破窗闻雨五更初。","經年荒草侵幽逕，幾樹西风鎖弊廬。","长繫寸心归未得，起挑殘燭独躊躇。"]', '诗', 'shi', '', NULL, '客舍秋晚夜懷故山 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0013fc1f-5718-4f3f-878a-1e546d4bb5cd', '絳州鄭尚書', '絳州鄭尚书', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["旌旗日日展東風，雲稼連山雪刃空。","剖竹已知垂鳳食，摘珠何必到龍宮。","諫垣虛位期飛步，翰苑含毫待紀公。","誰謂唐城諸父老，今時得見蜀文翁。"]', '["旌旗日日展东风，云稼連山雪刃空。","剖竹已知垂鳳食，摘珠何必到龙宮。","諫垣虛位期飞步，翰苑含毫待紀公。","誰謂唐城諸父老，今时得见蜀文翁。"]', '诗', 'shi', '', NULL, '絳州鄭尚書 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94b0139a-d220-421e-b1e0-98a545a24300', '喜陳先輩及第', '喜陳先輩及第', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["今年春已到京華，天與吾曹雪怨嗟。","甲乙中時公道復，朝廷看處主司誇。","飛離海浪從燒尾，嚥卻金丹定易牙。","不是駕前偏落羽，錦城爭得杏園花。"]', '["今年春已到京华，天與吾曹雪怨嗟。","甲乙中时公道复，朝廷看处主司誇。","飞離海浪從燒尾，嚥卻金丹定易牙。","不是駕前偏落羽，錦城爭得杏园花。"]', '诗', 'shi', '', NULL, '喜陳先輩及第 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46361e22-f75b-401f-bfda-576592bb2243', '延福里居和林寬何紹餘醻寄', '延福里居和林寬何紹餘醻寄', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["長說愁吟逆旅中，一庭深雪一窗風。","眼前道路無心覓，象外煙霞有句通。","幾度相留侵鼓散，頻聞會宿著僧同。","高情未以干時廢，屬和因知興不窮。"]', '["长说愁吟逆旅中，一庭深雪一窗风。","眼前道路無心覓，象外煙霞有句通。","幾度相留侵鼓散，頻闻會宿著僧同。","高情未以干时廢，屬和因知兴不窮。"]', '诗', 'shi', '', NULL, '延福里居和林寬何紹餘醻寄 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81ae0bf3-eaaa-4700-9ff6-342e2945aafe', '贈宿松楊明府', '贈宿松楊明府', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["溪上家家禮樂新，始知爲政異常倫。","若非似水清無底，爭得如冰凜拂人。","月狖聲和琴調咽，煙村景接柳條春。","宦遊兼得逍遙趣，休憶三吳舊釣津。"]', '["溪上家家禮乐新，始知爲政異常倫。","若非似水清無底，爭得如冰凜拂人。","月狖声和琴調咽，煙村景接柳條春。","宦游兼得逍遙趣，休憶三吳旧釣津。"]', '诗', 'shi', '', NULL, '贈宿松楊明府 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22180198-25bc-42e9-ab4c-f47e1b81395e', '送僧', '送僧', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["纔年七歲便從師，猶說辭家學佛遲。","新斸松蘿還不住，愛尋雲水擬何之。","孤溪雪滿維舟夜，疊嶂猿啼過寺時。","鳥道瀧湫悉行後，豈將翻譯負心期。"]', '["纔年七歲便從師，猶说辞家学佛遲。","新斸松蘿還不住，愛尋云水擬何之。","孤溪雪满維舟夜，叠嶂猿啼過寺时。","鸟道瀧湫悉行後，豈將翻譯負心期。"]', '诗', 'shi', '', NULL, '送僧 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('007ab3b6-4a50-4b26-ab43-b68900d1c257', '贈鄭明府', '贈鄭明府', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["庭羅衙吏眼看山，真恐風流是謫仙。","垂柳五株春婭姹，鳴琴一弄水潺湲。","援毫斷獄登殊考，駐樂題詩得出聯。","莫起陶潛折腰歎，才高位下始稱賢。"]', '["庭羅衙吏眼看山，真恐风流是謫仙。","垂柳五株春婭姹，鳴琴一弄水潺湲。","援毫斷獄登殊考，駐乐題诗得出聯。","莫起陶潛折腰歎，才高位下始稱賢。"]', '诗', 'shi', '', NULL, '贈鄭明府 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fabed83-de6a-401f-b4b4-f8e31678edd6', '江州夜宴獻陳員外', '江州夜宴獻陳員外', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["多少歡娛簇眼前，潯陽江上夜開筵。","數枝紅蠟啼香淚，兩面青娥拆瑞蓮。","清管徹時斟玉醑，碧籌回處擲金船。","因知往歲樓中月，占得風流是偶然。"]', '["多少歡娛簇眼前，潯陽江上夜开筵。","數枝紅蠟啼香泪，兩面青娥拆瑞蓮。","清管徹时斟玉醑，碧籌回处擲金船。","因知往歲楼中月，占得风流是偶然。"]', '诗', 'shi', '', NULL, '江州夜宴獻陳員外 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('421a8c1a-1f29-4d01-a168-f38f6ab08fec', '湘中贈張逸人', '湘中贈張逸人', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["羽衣零落帽欹斜，不自孤峰即海沙。","曾爲蜀山成寓跡，又因湘水擬營家。","鳴琴坐見燕鴻沒，曳履吟忘野逕賒。","更愛扁舟宿寒夜，獨聽風雨過蘆花。"]', '["羽衣零落帽欹斜，不自孤峰即海沙。","曾爲蜀山成寓跡，又因湘水擬營家。","鳴琴坐见燕鴻沒，曳履吟忘野逕賒。","更愛扁舟宿寒夜，独听风雨過蘆花。"]', '诗', 'shi', '', NULL, '湘中贈張逸人 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e59fc046-6c99-4eb3-9d59-0fd11ecb1de2', '寓題', '寓題', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["紛紛墨勅除官日，處處紅旗打賊時。","竿底得璜猶未用，夢中吞鳥擬何爲。","損生莫若攀丹桂，免俗無過詠紫芝。","兩岸蘆花一江水，依前且把釣魚絲。"]', '["紛紛墨勅除官日，处处紅旗打賊时。","竿底得璜猶未用，梦中吞鸟擬何爲。","損生莫若攀丹桂，免俗無過詠紫芝。","兩岸蘆花一江水，依前且把釣鱼絲。"]', '诗', 'shi', '', NULL, '寓題 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41b94021-003f-453e-b880-dba94e60c8e0', '題陳山人居', '題陳山人居', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["猶自莓苔馬跡重，石嵌泉冷嬾移峰。","空垂鳳食簷前竹，漫拔龍形澗底松。","隔岸青山秋見寺，半牀明月夜聞鐘。","誰能惆悵磻溪事，今古悠悠不再逢。"]', '["猶自莓苔马跡重，石嵌泉冷嬾移峰。","空垂鳳食簷前竹，漫拔龙形澗底松。","隔岸青山秋见寺，半牀明月夜闻鐘。","誰能惆悵磻溪事，今古悠悠不再逢。"]', '诗', 'shi', '', NULL, '題陳山人居 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3bf4e58-b63f-4c00-821c-5b1579f27ec6', '宿李少府園林', '宿李少府园林', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["一壺濁酒百家詩，住此園林守選期。","深院月涼留客夜，古杉風細似泉時。","嘗頻異茗塵心淨，議罷名山竹影移。","明日綠苔渾掃後，石庭吟坐復容誰。"]', '["一壺濁酒百家诗，住此园林守選期。","深院月涼留客夜，古杉风細似泉时。","嘗頻異茗塵心淨，議罷名山竹影移。","明日綠苔渾掃後，石庭吟坐复容誰。"]', '诗', 'shi', '', NULL, '宿李少府園林 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a759d88-0634-4508-abd5-4a144555c8b3', '送人明經及第東歸', '送人明經及第东归', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["十問九通離義牀，今時登第信非常。","亦從南院看新榜，旋束春關歸故鄉。","水到吳門方見海，樹侵閩嶺漸無霜。","知君已塞平生願，日與交親醉幾場。"]', '["十问九通離義牀，今时登第信非常。","亦從南院看新榜，旋束春关归故乡。","水到吳门方见海，樹侵閩嶺漸無霜。","知君已塞平生願，日與交親醉幾場。"]', '诗', 'shi', '', NULL, '送人明經及第東歸 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a9553f1-b52b-4aff-ac5c-c9dc947e34af', '斷酒', '斷酒', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["未老先爲百病仍，醉杯無計接賓朋。","免遭拽盞郎君謔，還被簪花錄事憎。","絲管合時思索馬，池塘晴後獨留僧。","何因澆得離腸爛，南浦東門恨不勝。"]', '["未老先爲百病仍，醉杯無計接賓朋。","免遭拽盞郎君謔，還被簪花錄事憎。","絲管合时思索马，池塘晴後独留僧。","何因澆得離腸爛，南浦东门恨不勝。"]', '诗', 'shi', '', NULL, '斷酒 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acab9730-0561-4e06-96cc-a1cabb73c276', '南海幕和段先輩送韋侍御赴闕', '南海幕和段先輩送韋侍御赴闕', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["樹色川光入暮秋，使車西發不勝愁。","璧連標格驚分散，雪課篇章互唱酬。","魏闕別當飛羽翼，燕臺獨且占風流。","滿園歌管涼宵月，此後相思幾上樓。"]', '["樹色川光入暮秋，使车西發不勝愁。","璧連標格驚分散，雪課篇章互唱酬。","魏闕別當飞羽翼，燕台独且占风流。","满园歌管涼宵月，此後相思幾上楼。"]', '诗', 'shi', '', NULL, '南海幕和段先輩送韋侍御赴闕 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92d8de82-efd5-44ad-a856-93d23f0662f9', '寄南海黃尚書', '寄南海黄尚书', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["五羊城下駐行車，此事如今八載餘。","燕頷已知飛食肉，龍門猶自退爲魚。","紅樓入夜笙歌合，白社驚秋草木疎。","西望清光寄消息，萬重煙水一封書。"]', '["五羊城下駐行车，此事如今八載餘。","燕頷已知飞食肉，龙门猶自退爲鱼。","紅楼入夜笙歌合，白社驚秋草木疎。","西望清光寄消息，万重煙水一封书。"]', '诗', 'shi', '', NULL, '寄南海黃尚書 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fa550fd-b249-4a17-9a45-4a31d59b985f', '送人往蘇州覲其兄', '送人往蘇州覲其兄', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["闔閭城外越江頭，兩地煙濤一葉舟。","到日荆枝應便茂，別時珠淚不須流。","迎歡酒醒山當枕，詠古詩成月在樓。","明日尊前若相問，爲言今訪赤松遊。"]', '["闔閭城外越江头，兩地煙濤一葉舟。","到日荆枝應便茂，別时珠泪不須流。","迎歡酒醒山當枕，詠古诗成月在楼。","明日尊前若相问，爲言今訪赤松游。"]', '诗', 'shi', '', NULL, '送人往蘇州覲其兄 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('304cd810-4a92-474c-a7ef-a5936d5b9139', '遊東林寺', '游东林寺', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["長生猶自重無生，言讓仙祠佛寺成。","碑折誰忘康樂制，山靈表得遠公名。","松形入漢藤蘿短，僧語離經耳目清。","莫怪遲遲不歸去，童年已夢遶林行。"]', '["长生猶自重無生，言讓仙祠佛寺成。","碑折誰忘康乐制，山靈表得远公名。","松形入漢藤蘿短，僧語離經耳目清。","莫怪遲遲不归去，童年已梦遶林行。"]', '诗', 'shi', '', NULL, '遊東林寺 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6304dafe-be48-4504-9531-b9cf52f4a407', '贈旌德呂明府', '贈旌德呂明府', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["渥洼步數太阿姿，爭遣王侯不奉知。","花作城池入官處，錦隨刀尺少年時。","兩衙斷獄兼留客，三考論功合樹碑。","須信隔簾看刺史，錦章朱紱已葳蕤。"]', '["渥洼步數太阿姿，爭遣王侯不奉知。","花作城池入官处，錦隨刀尺少年时。","兩衙斷獄兼留客，三考論功合樹碑。","須信隔簾看刺史，錦章朱紱已葳蕤。"]', '诗', 'shi', '', NULL, '贈旌德呂明府 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d594626e-7d4b-4201-9496-c18168b38c70', '賀清源僕射新命', '賀清源僕射新命', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["雖言嵩嶽秀崔嵬，少降連枝命世才。","南史兩榮唯百揆，東閩雙拜有三台。","二天在頂家家詠，丹鳳銜書歲歲來。","虛說古賢龍虎盛，誰攀荆樹上金臺。"]', '["雖言嵩嶽秀崔嵬，少降連枝命世才。","南史兩榮唯百揆，东閩雙拜有三台。","二天在頂家家詠，丹鳳銜书歲歲来。","虛说古賢龙虎盛，誰攀荆樹上金台。"]', '诗', 'shi', '', NULL, '賀清源僕射新命 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e615c593-e133-40e0-9949-2cf21e813969', '浙幕李端公泛建溪', '浙幕李端公泛建溪', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["越城吳國結良姻，交發芙蓉幕內賓。","自顧幽沈槐省跡，得陪清顯諫垣臣。","分題曉並蘭舟遠，對坐宵聽月狖頻。","更愛延平津上過，一雙神劍是龍鱗。"]', '["越城吳国結良姻，交發芙蓉幕內賓。","自顧幽沈槐省跡，得陪清显諫垣臣。","分題晓並蘭舟远，对坐宵听月狖頻。","更愛延平津上過，一雙神劍是龙鱗。"]', '诗', 'shi', '', NULL, '浙幕李端公泛建溪 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb4aa559-11aa-4791-b9c6-70ecf024cd94', '貽宋評事', '貽宋評事', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["河陽城裏謝城中，入曳長裾出佩銅。","燕國金臺無別客，陶家柳下有清風。","數蹤篆隸書新得，一竈屯蒙火細紅。","時說三吳欲歸處，綠波洲渚紫蒲藂。"]', '["河陽城裏謝城中，入曳长裾出佩銅。","燕国金台無別客，陶家柳下有清风。","數蹤篆隸书新得，一竈屯蒙火細紅。","时说三吳欲归处，綠波洲渚紫蒲藂。"]', '诗', 'shi', '', NULL, '貽宋評事 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c61710d0-63cb-4937-a252-f652bb25f5ff', '催妝', '催妝', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["北府迎塵南郡來，莫將芳意更遲回。","雖言天上光陰別，且被人間更漏催。","煙樹逈垂連蔕杏，綵童交捧合歡杯。","吹簫不是神仙曲，爭引秦娥下鳳臺。"]', '["北府迎塵南郡来，莫將芳意更遲回。","雖言天上光陰別，且被人间更漏催。","煙樹逈垂連蔕杏，綵童交捧合歡杯。","吹簫不是神仙曲，爭引秦娥下鳳台。"]', '诗', 'shi', '', NULL, '催妝 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6ec652e-f1ad-4207-8697-c4c6e8f88a46', '寓題', '寓題', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["每憶家山即涕零，定須歸老舊雲扃。","銀河水到人間濁，丹桂枝垂月裏馨。","霜雪不飛無翠竹，鯨鯢猶在有青萍。","三千九萬平生事，却恨南華說北溟。"]', '["每憶家山即涕零，定須归老旧云扃。","銀河水到人间濁，丹桂枝垂月裏馨。","霜雪不飞無翠竹，鯨鯢猶在有青萍。","三千九万平生事，却恨南华说北溟。"]', '诗', 'shi', '', NULL, '寓題 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fba308a7-14a9-40fd-92ef-59803455389d', '傷蔣校書德山', '傷蔣校书德山', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["誰到雙溪溪岸傍，與招魂魄上蒼蒼。","世間無樹勝青桂，隴上有花唯白楊。","秦苑火然新賦在，越城山秀故居荒。","如何萬古雕龍手，獨是相如識漢皇。"]', '["誰到雙溪溪岸傍，與招魂魄上蒼蒼。","世间無樹勝青桂，隴上有花唯白楊。","秦苑火然新賦在，越城山秀故居荒。","如何万古雕龙手，独是相如識漢皇。"]', '诗', 'shi', '', NULL, '傷蔣校書德山 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de8792ad-a4ff-4afe-b1e2-338b59f753d8', '寄楊贊圖學士', '寄楊贊圖学士', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["東堂第一領春風，時怪關西小驥慵。","華表柱頭還有鶴，華歆名下別無龍。","君恩鳳閣含毫數，詩景珠宮列肆供。","今日江南駐舟處，莫言歸計爲雲峰。"]', '["东堂第一領春风，时怪关西小驥慵。","华表柱头還有鹤，华歆名下別無龙。","君恩鳳閣含毫數，诗景珠宮列肆供。","今日江南駐舟处，莫言归計爲云峰。"]', '诗', 'shi', '', NULL, '寄楊贊圖學士 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46e099a3-0004-4a44-ab01-8305c866c0a7', '酬楊學士', '酬楊学士', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["神仙簿上愧非夫，詔作疑丹兩入爐。","詩裏幾曾吟芍藥，花中方得見菖蒲。","陽春唱後應無曲，明月圓來別是珠。","莫下蓬山不迴首，東風猶待重摶扶。"]', '["神仙簿上愧非夫，詔作疑丹兩入爐。","诗裏幾曾吟芍藥，花中方得见菖蒲。","陽春唱後應無曲，明月圓来別是珠。","莫下蓬山不迴首，东风猶待重摶扶。"]', '诗', 'shi', '', NULL, '酬楊學士 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ae1ab35-d55a-4db6-b9c7-6128c0ff3d60', '寄同年李侍郎龜正', '寄同年李侍郎龟正', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["石門南面淚浪浪，自此東西失帝鄉。","崑璞要疑方卓絕，大鵬須息始開張。","已歸天上趨雙闕，忽喜人間捧八行。","莫道秋霜不滋物，菊花還借後時黃。"]', '["石门南面泪浪浪，自此东西失帝乡。","崑璞要疑方卓絕，大鵬須息始开張。","已归天上趨雙闕，忽喜人间捧八行。","莫道秋霜不滋物，菊花還借後时黄。"]', '诗', 'shi', '', NULL, '寄同年李侍郎龜正 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e8174f4-cc1b-4bf7-9450-616bd15c16cf', '鍾陵故人', '鍾陵故人', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["滕王閣下昔相逢，此地今難訪所從。","唯愛金籠貯鸚鵡，誰論鐵柱鎖蛟龍。","荆榛翠是錢神染，河嶽期須國士鍾。","一筯鱸魚千古美，後人終少繼前蹤。"]', '["滕王閣下昔相逢，此地今难訪所從。","唯愛金籠貯鸚鵡，誰論鐵柱鎖蛟龙。","荆榛翠是錢神染，河嶽期須国士鍾。","一筯鱸鱼千古美，後人終少繼前蹤。"]', '诗', 'shi', '', NULL, '鍾陵故人 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f608ec6-e1d1-4c3b-bba0-a14dfc377557', '故山', '故山', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["支頤默省舊林泉，石徑茅堂到目前。","衰碧鳴蛩莎有露，濃陰歇鹿竹無煙。","水從井底通滄海，山在窗中倚遠天。","何事蒼髯不歸去，燕昭臺上一年年。"]', '["支頤默省旧林泉，石徑茅堂到目前。","衰碧鳴蛩莎有露，濃陰歇鹿竹無煙。","水從井底通滄海，山在窗中倚远天。","何事蒼髯不归去，燕昭台上一年年。"]', '诗', 'shi', '', NULL, '故山 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43b51b3c-6d58-41b3-ac59-9f404b0f6716', '塞上', '塞上', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["塞門關外日光微，角怨單于鴈駐飛。","衝水路從冰解斷，踰城人到月明歸。","燕山臘雪銷金甲，秦苑秋風脆錦衣。","欲弔昭君倍惆悵，漢家甥舅竟相違。"]', '["塞门关外日光微，角怨單于鴈駐飞。","衝水路從冰解斷，踰城人到月明归。","燕山臘雪銷金甲，秦苑秋风脆錦衣。","欲弔昭君倍惆悵，漢家甥舅竟相違。"]', '诗', 'shi', '', NULL, '塞上 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03b47d5b-3877-460f-85e0-4ed2c7939b95', '烏石村', '烏石村', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["往日江村今物華，一迴登覽一悲嗟。","故人歿後城頭月，新鳥啼來壠上花。","賣劍錢銷知絕俗，聞蟬詩苦即思家。","謝公古郡青山在，三尺孤墳撲海沙。"]', '["往日江村今物华，一迴登覽一悲嗟。","故人歿後城头月，新鸟啼来壠上花。","賣劍錢銷知絕俗，闻蟬诗苦即思家。","謝公古郡青山在，三尺孤墳撲海沙。"]', '诗', 'shi', '', NULL, '烏石村 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0fdb3de-cfe3-42eb-b364-59bec4fc9d6c', '寄同年盧員外', '寄同年盧員外', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["聽盡鸎聲出雍州，秦吳煙月十經秋。","龍門在地從人上，郎省連天須鶴遊。","休戀一臺惟妙絕，已經三字入精求。","當年甲乙皆華顯，應念槐宮今雪頭。"]', '["听尽鸎声出雍州，秦吳煙月十經秋。","龙门在地從人上，郎省連天須鹤游。","休戀一台惟妙絕，已經三字入精求。","當年甲乙皆华显，應念槐宮今雪头。"]', '诗', 'shi', '', NULL, '寄同年盧員外 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4160046d-4114-4fb5-8535-fa73fa904ba3', '寄同年封舍人渭', '寄同年封舍人渭', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["唐城接軫赴秦川，憂合懽離驟十年。","龍頷摘珠同泳海，鳳銜輝翰別升天。","八行真跡雖收拾，四戶高扃奈隔懸。","能使丘門終始雪，莫教華髮獨潸然。"]', '["唐城接軫赴秦川，憂合懽離驟十年。","龙頷摘珠同泳海，鳳銜輝翰別升天。","八行真跡雖收拾，四戶高扃奈隔懸。","能使丘门終始雪，莫教华髮独潸然。"]', '诗', 'shi', '', NULL, '寄同年封舍人渭 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a672f30-15f4-461f-ba73-189d9e8b502f', '遇羅員外衮', '遇羅員外衮', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["灞陵橋外駐征轅，此一分飛十六年。","豸角戴時垂素髮，雞香含處隔青天。","綺園難貯林棲意，班馬須持筆削權。","可忘自初相識地，秋風明月客鄜延。"]', '["灞陵橋外駐征轅，此一分飞十六年。","豸角戴时垂素髮，雞香含处隔青天。","綺园难貯林棲意，班马須持笔削權。","可忘自初相識地，秋风明月客鄜延。"]', '诗', 'shi', '', NULL, '遇羅員外衮 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bff86ef4-2f6f-4d2a-b0f5-814f9b9d525f', '送翁員外承贊', '送翁員外承贊', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["誰言吾黨命多奇，榮美如君歷數稀。","衣錦還鄉翻是客，迴車謁帝卻爲歸。","鳳旋北闕虛丹穴，星復南宮逼紫微。","已分十旬無急詔，天涯相送只沾衣。"]', '["誰言吾黨命多奇，榮美如君歷數稀。","衣錦還乡翻是客，迴车謁帝卻爲归。","鳳旋北闕虛丹穴，星复南宮逼紫微。","已分十旬無急詔，天涯相送只沾衣。"]', '诗', 'shi', '', NULL, '送翁員外承贊 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4df8dcfa-24b4-4039-b96f-99d9b1ab0725', '奉和翁文堯十九員外中謝日蒙恩賜金紫之什', '奉和翁文堯十九員外中謝日蒙恩賜金紫之什', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["面蒙君賜自龍墀，誰是還鄉一襲衣。","三品易懸鱗鬣赫，八絲展起綵章飛。","敻爲勝事垂千古，題作新詩啓七微。","嚴助買臣精魄在，定應羞著昔年歸。"]', '["面蒙君賜自龙墀，誰是還乡一襲衣。","三品易懸鱗鬣赫，八絲展起綵章飞。","敻爲勝事垂千古，題作新诗啓七微。","嚴助買臣精魄在，定應羞著昔年归。"]', '诗', 'shi', '', NULL, '奉和翁文堯十九員外中謝日蒙恩賜金紫之什 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5101916b-b9f5-49d6-bb3c-6af71f4e13a9', '翁文堯員外捧金紫還鄉之命雅發篇章將原交情遠爲嘉貺洎燕鴻陸犬楚水荆山又吐瓊瑤逮之幽鄙雖湧泉思觸逸興皆虛而強韻押難非才頗媿輙茲酬和以質獎私', '翁文堯員外捧金紫還乡之命雅發篇章將原交情远爲嘉貺洎燕鴻陸犬楚水荆山又吐瓊瑤逮之幽鄙雖湧泉思觸逸兴皆虛而強韻押难非才頗媿輙茲酬和以質獎私', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["摶將盛事更無餘，還向橋邊看舊書。","東越獨推生竹箭，北溟喜足貯鯤魚。","兩迴誰解歸華表，午夜兼能薦子虛。","須把頭冠彈盡日，憐君不與故人疎。"]', '["摶將盛事更無餘，還向橋邊看旧书。","东越独推生竹箭，北溟喜足貯鯤鱼。","兩迴誰解归华表，午夜兼能薦子虛。","須把头冠彈尽日，怜君不與故人疎。"]', '诗', 'shi', '', NULL, '翁文堯員外捧金紫還鄉之命雅發篇章將原交情遠爲嘉貺洎燕鴻陸犬楚水荆山又吐瓊瑤逮之幽鄙雖湧泉思觸逸興皆虛而強韻押難非才頗媿輙茲酬和以質獎私 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45b55b1b-a486-4544-8154-d8a0f83177dd', '奉和翁文堯員外經過七林書堂見寄之什', '奉和翁文堯員外經過七林书堂见寄之什', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["朱旗引入昔茆堂，半日從容盡日忙。","駟馬寶車行錫禮，金章紫綬帶天香。","山從南國添煙翠，龍起東溟認夜光。","定恐故園留不住，竹風松韻漫淒鏘。"]', '["朱旗引入昔茆堂，半日從容尽日忙。","駟马寶车行錫禮，金章紫綬带天香。","山從南国添煙翠，龙起东溟認夜光。","定恐故园留不住，竹风松韻漫淒鏘。"]', '诗', 'shi', '', NULL, '奉和翁文堯員外經過七林書堂見寄之什 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8df3295-5c4f-4ede-ab72-a1f8ee778c81', '奉酬翁文堯員外駐南臺見寄之什', '奉酬翁文堯員外駐南台见寄之什', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["人指南臺山與川，大驚喜氣異當年。","花迎金冊非時拆，月對瓊杯此夜圓。","我愛藏冰從夏結，君憐修竹到冬鮮。","殷勤更抱鳴琴撫，爲憶秦兒識斷絃。"]', '["人指南台山與川，大驚喜氣異當年。","花迎金冊非时拆，月对瓊杯此夜圓。","我愛藏冰從夏結，君怜修竹到冬鲜。","殷勤更抱鳴琴撫，爲憶秦兒識斷絃。"]', '诗', 'shi', '', NULL, '奉酬翁文堯員外駐南臺見寄之什 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7465150-72e9-4c61-ab8e-3037988e61be', '翁文堯員外擁冊禮之歸一路有詩名晝錦集先將寄示因書五十六字', '翁文堯員外擁冊禮之归一路有诗名晝錦集先將寄示因书五十六字', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["六窠只佩諸侯印，爭比從天擁冊歸。","一軸郢人歌處雪，兩重朱氏著來衣。","閩山秀已鍾君盡，洛水波應濺我稀。","明日陪塵迎駟馬，定淮齋沐看光輝。"]', '["六窠只佩諸侯印，爭比從天擁冊归。","一軸郢人歌处雪，兩重朱氏著来衣。","閩山秀已鍾君尽，洛水波應濺我稀。","明日陪塵迎駟马，定淮斋沐看光輝。"]', '诗', 'shi', '', NULL, '翁文堯員外擁冊禮之歸一路有詩名晝錦集先將寄示因書五十六字 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bef737d-93d9-43e8-bab0-346e9c91caea', '奉和翁文堯員外文秀光賢晝錦之什 一', '奉和翁文堯員外文秀光賢晝錦之什 一', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["鄉名里號一朝新，乃覺台恩重萬鈞。","建水閩山無故事，長卿嚴助是前身。","清泉引入旁添潤，嘉樹移來別帶春。","莫凭欄干剩留駐，內庭虛位待才臣。"]', '["乡名里號一朝新，乃覺台恩重万鈞。","建水閩山無故事，长卿嚴助是前身。","清泉引入旁添潤，嘉樹移来別带春。","莫凭欄干剩留駐，內庭虛位待才臣。"]', '诗', 'shi', '', NULL, '奉和翁文堯員外文秀光賢晝錦之什 一 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6708b552-6e95-4eb1-a1e7-803fb1c3dc36', '奉和翁文堯員外文秀光賢晝錦之什 二', '奉和翁文堯員外文秀光賢晝錦之什 二', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["雖言閩越繫生賢，誰是還家寵自天。","山簡媿兼諸郡命，鄭玄慙秉六經權。","鳥行去沒孤烟樹，漁唱還從碧島川。","休說遲迴未能去，夜來新夢禁中泉。"]', '["雖言閩越繫生賢，誰是還家寵自天。","山簡媿兼諸郡命，鄭玄慙秉六經權。","鸟行去沒孤烟樹，漁唱還從碧島川。","休说遲迴未能去，夜来新梦禁中泉。"]', '诗', 'shi', '', NULL, '奉和翁文堯員外文秀光賢晝錦之什 二 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe5d999a-7c2d-4ea8-a3c0-c50d489b88c5', '奉和翁文堯員外文秀光賢晝錦之什 三', '奉和翁文堯員外文秀光賢晝錦之什 三', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["君王面賜紫還鄉，金紫中推是甲裳。","華構便將垂美號，故山重更發清光。","水澄此日蘭宮鏡，樹憶當年栢署霜。","珍重朱欄兼翠拱，來來皆自讀書堂。"]', '["君王面賜紫還乡，金紫中推是甲裳。","华構便將垂美號，故山重更發清光。","水澄此日蘭宮镜，樹憶當年栢署霜。","珍重朱欄兼翠拱，来来皆自读书堂。"]', '诗', 'shi', '', NULL, '奉和翁文堯員外文秀光賢晝錦之什 三 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c2a496b-9ec1-42fb-8fbe-238588569a8a', '奉酬翁文堯員外神泉之遊見寄嘉什', '奉酬翁文堯員外神泉之游见寄嘉什', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["含雞假豸喜同遊，野外嘶風並紫騮。","松竹迴尋青障寺，姓名題向白雲樓。","泉源出石清消暑，僧語離經妙破愁。","爭奈愛山尤戀闕，古來能有幾人休。"]', '["含雞假豸喜同游，野外嘶风並紫騮。","松竹迴尋青障寺，姓名題向白云楼。","泉源出石清消暑，僧語離經妙破愁。","爭奈愛山尤戀闕，古来能有幾人休。"]', '诗', 'shi', '', NULL, '奉酬翁文堯員外神泉之遊見寄嘉什 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f1fcf73-d850-479f-8246-ce2c21555825', '輙吟七言四韻攀寄翁文堯拾遺', '輙吟七言四韻攀寄翁文堯拾遺', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["唐設高科表用文，吾曹誰作諫垣臣。","甄山秀氣曠千古，鳳闕華恩鍾二人。","起草便論天上事，如君不是世間身。","龍頭龍尾前年夢，今日須憐應若神。"]', '["唐設高科表用文，吾曹誰作諫垣臣。","甄山秀氣曠千古，鳳闕华恩鍾二人。","起草便論天上事，如君不是世间身。","龙头龙尾前年梦，今日須怜應若神。"]', '诗', 'shi', '', NULL, '輙吟七言四韻攀寄翁文堯拾遺 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca4fafcf-8795-4a0a-bcab-986830d9baf4', '塞上', '塞上', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["掘地破重城，燒山搜伏兵。","金徽互嗚咽，玉笛自淒清。","使發西都聳，塵空北嶽橫。","長河涉有路，曠野宿無程。","沙雨黃鶯囀，轅門青草生。","馬歸秦苑牧，人在虜雲耕。","落日牛羊聚，秋風鼓角鳴。","如何漢天子，青塚杳含情。"]', '["掘地破重城，燒山搜伏兵。","金徽互嗚咽，玉笛自淒清。","使發西都聳，塵空北嶽橫。","长河涉有路，曠野宿無程。","沙雨黄鶯囀，轅门青草生。","马归秦苑牧，人在虜云耕。","落日牛羊聚，秋风鼓角鳴。","如何漢天子，青塚杳含情。"]', '诗', 'shi', '', NULL, '塞上 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('effaec2f-64f7-4a94-ab76-93c5a7a10cb0', '寄獻梓橦山侯侍御', '寄獻梓橦山侯侍御', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["漢宮行廟略，簪笏落民間。","直道三湘水，高情四皓山。","賜衣僧脫去，奏表主批還。","地得松蘿塢，泉通雨雪灣。","東門添故事，南省缺新班。","片石秋從露，幽窗夜不關。","夢餘蟾隱映，吟次鳥綿蠻。","可惜相如作，當時事悉閑。"]', '["漢宮行廟略，簪笏落民间。","直道三湘水，高情四皓山。","賜衣僧脫去，奏表主批還。","地得松蘿塢，泉通雨雪灣。","东门添故事，南省缺新班。","片石秋從露，幽窗夜不关。","梦餘蟾隐映，吟次鸟綿蠻。","可惜相如作，當时事悉闲。"]', '诗', 'shi', '', NULL, '寄獻梓橦山侯侍御 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0b6548b-55ed-4c8d-a4cf-b638beca33ad', '壬癸歲書情', '壬癸歲书情', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["故園招隱客，應便笑無成。","謁帝逢移國，投文值用兵。","孤松憐鶴在，疎柳惡蟬鳴。","匹馬迷歸處，青雲失曩情。","江頭寒夜宿，壠上歉年耕。","冠蓋新人物，漁樵舊弟兄。","易生唯白髮，難立是浮名。","惆悵灞橋路，秋風誰入行。"]', '["故园招隐客，應便笑無成。","謁帝逢移国，投文值用兵。","孤松怜鹤在，疎柳惡蟬鳴。","匹马迷归处，青云失曩情。","江头寒夜宿，壠上歉年耕。","冠蓋新人物，漁樵旧弟兄。","易生唯白髮，难立是浮名。","惆悵灞橋路，秋风誰入行。"]', '诗', 'shi', '', NULL, '壬癸歲書情 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4507a4a0-d0c8-4fb0-b441-30329859def0', '河南府試秋夕聞新鴈', '河南府試秋夕闻新鴈', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["湘南飛去日，薊北乍驚秋。","呌出隴雲夜，聞爲客子愁。","一聲初觸夢，半白已侵頭。","旅館移欹枕，江城起倚樓。","餘燈依古壁，片月下滄洲。","寂聽良宵徹，躊躇感歲流。"]', '["湘南飞去日，薊北乍驚秋。","呌出隴云夜，闻爲客子愁。","一声初觸梦，半白已侵头。","旅館移欹枕，江城起倚楼。","餘灯依古壁，片月下滄洲。","寂听良宵徹，躊躇感歲流。"]', '诗', 'shi', '', NULL, '河南府試秋夕聞新鴈 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50a7259d-a675-4bbf-8b57-520ecf1a7817', '省試奉詔漲曲江池', '省試奉詔漲曲江池', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["地脉寒來淺，恩波住後新。","引將諸派水，別貯大都春。","幽咽疏通處，清泠迸入辰。","漸平連杏岸，旋闊映樓津。","沙沒迷行徑，洲寬恣躍鱗。","願當舟檝便，一附濟川人。"]', '["地脉寒来淺，恩波住後新。","引將諸派水，別貯大都春。","幽咽疏通处，清泠迸入辰。","漸平連杏岸，旋闊映楼津。","沙沒迷行徑，洲寬恣躍鱗。","願當舟檝便，一附濟川人。"]', '诗', 'shi', '', NULL, '省試奉詔漲曲江池 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e27f7ea-4335-4cca-8fcd-5fa0a41a3437', '題宣一僧正院', '題宣一僧正院', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["五級凌虛塔，三生落髮師。","都僧須有託，孤嶠遂無期。","井邑焚香待，君侯減俸資。","山衣隨疊破，萊骨逐年羸。","茶取寒泉試，松於遠澗移。","吾曹來頂手，不合不題詩。"]', '["五級凌虛塔，三生落髮師。","都僧須有託，孤嶠遂無期。","井邑焚香待，君侯減俸資。","山衣隨叠破，萊骨逐年羸。","茶取寒泉試，松於远澗移。","吾曹来頂手，不合不題诗。"]', '诗', 'shi', '', NULL, '題宣一僧正院 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01f557f6-4b73-4436-a644-417b41340edc', '和吳學士對春雪獻韋令公次韻', '和吳学士对春雪獻韋令公次韻', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["春雪下盈空，翻疑臘未窮。","連天寧認月，墮地屢兼風。","忽誤邊沙上，應平火嶺中。","林間妨走獸，雲際落飛鴻。","梁苑還吟客，齊都省創宮。","掩扉皆墐北，移律愧居東。","書幌飄全濕，茶鐺入旋融。","奔川半留滯，疊樹互玲瓏。","出戶行瑤砌，開園見粉叢。","高才興詠處，真宰荅殊功。"]', '["春雪下盈空，翻疑臘未窮。","連天寧認月，墮地屢兼风。","忽誤邊沙上，應平火嶺中。","林间妨走獸，云際落飞鴻。","梁苑還吟客，齊都省創宮。","掩扉皆墐北，移律愧居东。","书幌飄全濕，茶鐺入旋融。","奔川半留滯，叠樹互玲瓏。","出戶行瑤砌，开园见粉叢。","高才兴詠处，真宰荅殊功。"]', '诗', 'shi', '', NULL, '和吳學士對春雪獻韋令公次韻 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eabe9e6-e14f-49f4-8cf2-9cd6849e9bf4', '省試一一吹竽', '省試一一吹竽', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["齊竽今歷試，真僞不難知。","欲使聲聲別，須令箇箇吹。","後先無錯雜，能否立參差。","次第教單進，宮商乃異宜。","凡音皆竄跡，至藝始呈奇。","以此論文學，終憑一一窺。"]', '["齊竽今歷試，真僞不难知。","欲使声声別，須令箇箇吹。","後先無錯杂，能否立參差。","次第教單進，宮商乃異宜。","凡音皆竄跡，至藝始呈奇。","以此論文学，終憑一一窺。"]', '诗', 'shi', '', NULL, '省試一一吹竽 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a876008-b9cc-4a28-aa23-541a02123c8c', '明月照高樓', '明月照高楼', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["月滿長空朗，樓侵碧落橫。","波文流藻井，桂魄拂雕楹。","深鑒羅紈薄，寒搜戶牖清。","冰鋪梁燕噤，霜覆瓦松傾。","卓午收全影，斜懸轉半明。","佳人當此夕，多少別離情。"]', '["月满长空朗，楼侵碧落橫。","波文流藻井，桂魄拂雕楹。","深鑒羅紈薄，寒搜戶牖清。","冰鋪梁燕噤，霜覆瓦松傾。","卓午收全影，斜懸轉半明。","佳人當此夕，多少別離情。"]', '诗', 'shi', '', NULL, '明月照高樓 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b03d532-6d60-4673-80f2-42792605f728', '廣州試越臺懷古', '廣州試越台懷古', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["南越千年事，興懷一旦來。","歌鐘非舊俗，煙月有層臺。","北望人何在，東流水不回。","吹窗風雜瘴，沾檻雨經梅。","壯氣曾難揖，空名信可哀。","不堪登覽處，花落與花開。"]', '["南越千年事，兴懷一旦来。","歌鐘非旧俗，煙月有層台。","北望人何在，东流水不回。","吹窗风杂瘴，沾檻雨經梅。","壯氣曾难揖，空名信可哀。","不堪登覽处，花落與花开。"]', '诗', 'shi', '', NULL, '廣州試越臺懷古 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a03797f-a3e4-482b-bc3d-b3f093a8448e', '襄州試白雲歸帝鄉', '襄州試白云归帝乡', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["杳杳復霏霏，應緣有所依。","不言天路遠，終望帝鄉歸。","高嶽和霜過，遙關帶月飛。","漸憐雙闕近，寧恨衆山違。","陣觸銀河亂，光連粉署微。","旅人隨計日，自笑比麻衣。"]', '["杳杳复霏霏，應緣有所依。","不言天路远，終望帝乡归。","高嶽和霜過，遙关带月飞。","漸怜雙闕近，寧恨衆山違。","陣觸銀河亂，光連粉署微。","旅人隨計日，自笑比麻衣。"]', '诗', 'shi', '', NULL, '襄州試白雲歸帝鄉 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('250a1b8b-6774-42a8-9e6e-65f50581d234', '省試內出白鹿宣示百官', '省試內出白鹿宣示百官', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["上瑞何曾乏，毛羣表色難。","推於五靈少，宣示百寮觀。","形奪場駒潔，光交月兔寒。","已馴瑤草別，孤立雪花團。","戴豸慙端士，抽毫躍史官。","貴臣歌詠日，皆作白麟看。"]', '["上瑞何曾乏，毛羣表色难。","推於五靈少，宣示百寮观。","形奪場駒潔，光交月兔寒。","已馴瑤草別，孤立雪花團。","戴豸慙端士，抽毫躍史官。","貴臣歌詠日，皆作白麟看。"]', '诗', 'shi', '', NULL, '省試內出白鹿宣示百官 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2948c89-e662-4211-9aab-5fe4beb8536e', '出關言懷', '出关言懷', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["又乞書題出，關西謁列侯。","寄家僧許嶽，釣浦雨移洲。","賣馬登長陸，沾衣逐勝遊。","菜腸終日餒，霜鬢度年秋。","詩苦無人愛，言公是世仇。","却憐庭際草，中有號忘憂。"]', '["又乞书題出，关西謁列侯。","寄家僧許嶽，釣浦雨移洲。","賣马登长陸，沾衣逐勝游。","菜腸終日餒，霜鬢度年秋。","诗苦無人愛，言公是世仇。","却怜庭際草，中有號忘憂。"]', '诗', 'shi', '', NULL, '出關言懷 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b85b90b-76ed-4597-962e-ed27beff2387', '壺公山', '壺公山', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["八面峰巒秀，孤高可偶然。","數人遊頂上，滄海見東邊。","不信無靈洞，相傳有古仙。","橘如珠夏在，池象月垂穿。","髣髴嘗聞樂，岧嶤半插天。","山寒徹三伏，松偃出千年。","樵牧時迷所，倉箱歲疊川。","嚴祠風雨管，怪木薜蘿纏。","青草方中藥，蒼苔石裏錢。","瓊津流乳竇，春色駐芝田。","烏兔中時近，龍蛇蟄處膻。","嘉名光列土，秀氣產羣賢。","瀑鎖瑤臺路，溪昇釣浦船。","鼇頭擎恐沒，地軸壓應旋。","蠲疾寒甘露，藏珍起瑞煙。","畫工飛夢寐，詩客寄林泉。","掘地多雲母，緣霜欠木綿。","井通鰌吐脉，僧隔虎棲禪。","危磴千尋拔，奇花四季鮮。","鶴歸懸圃少，鳳下碧梧偏。","桃易炎涼熟，茶推醉醒煎。","邨家蒙棗栗，俗骨爽猨蟬。","谷語昇喬鳥，陂開共蔕蓮。","落楓丹葉舞，新蕨紫芽拳。","翠竹雕羌笛，懸藤煮蜀牋。","白雲長掩映，流水別潺湲。","作賦前儒闕，沖虛南國先。","省郎求牧看，野老葺齋眠。","寺立興衰創，碑須一二鐫。","清吟思却隱，簪紱奈縈牽。"]', '["八面峰巒秀，孤高可偶然。","數人游頂上，滄海见东邊。","不信無靈洞，相傳有古仙。","橘如珠夏在，池象月垂穿。","髣髴嘗闻乐，岧嶤半插天。","山寒徹三伏，松偃出千年。","樵牧时迷所，倉箱歲叠川。","嚴祠风雨管，怪木薜蘿纏。","青草方中藥，蒼苔石裏錢。","瓊津流乳竇，春色駐芝田。","烏兔中时近，龙蛇蟄处膻。","嘉名光列土，秀氣產羣賢。","瀑鎖瑤台路，溪昇釣浦船。","鼇头擎恐沒，地軸壓應旋。","蠲疾寒甘露，藏珍起瑞煙。","畫工飞梦寐，诗客寄林泉。","掘地多云母，緣霜欠木綿。","井通鰌吐脉，僧隔虎棲禪。","危磴千尋拔，奇花四季鲜。","鹤归懸圃少，鳳下碧梧偏。","桃易炎涼熟，茶推醉醒煎。","邨家蒙棗栗，俗骨爽猨蟬。","谷語昇喬鸟，陂开共蔕蓮。","落楓丹葉舞，新蕨紫芽拳。","翠竹雕羌笛，懸藤煮蜀牋。","白云长掩映，流水別潺湲。","作賦前儒闕，沖虛南国先。","省郎求牧看，野老葺斋眠。","寺立兴衰創，碑須一二鐫。","清吟思却隐，簪紱奈縈牽。"]', '诗', 'shi', '', NULL, '壺公山 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1557b323-6fab-4f8e-9a96-e15c6c03f469', '和王舍人崔補闕題天王寺', '和王舍人崔補闕題天王寺', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["郭內青山寺，難論此崛奇。","白雲生院落，流水下城池。","石像雷霆啓，江沙鼎鼐期。","嶽僧來坐夏，秦客會題詩。","岡轉泉根滑，門升蘚級危。","紫微今日句，黃絹昔年碑。","歇鶴松低閣，鳴蛩徑出籬。","粉垣千堵束，金塔九層支。","啼鳥笙簧韻，開花錦繡姿。","清齋奔井邑，玄髮剃熊羆。","極浦征帆小，平蕪落日遲。","風篁清却暑，煙草綠無時。","信士三公作，靈蹤四絕推。","良遊如不宿，明月擬何之。"]', '["郭內青山寺，难論此崛奇。","白云生院落，流水下城池。","石像雷霆啓，江沙鼎鼐期。","嶽僧来坐夏，秦客會題诗。","岡轉泉根滑，门升蘚級危。","紫微今日句，黄絹昔年碑。","歇鹤松低閣，鳴蛩徑出籬。","粉垣千堵束，金塔九層支。","啼鸟笙簧韻，开花錦繡姿。","清斋奔井邑，玄髮剃熊羆。","極浦征帆小，平蕪落日遲。","风篁清却暑，煙草綠無时。","信士三公作，靈蹤四絕推。","良游如不宿，明月擬何之。"]', '诗', 'shi', '', NULL, '和王舍人崔補闕題天王寺 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf6e3d4-8d7f-4d59-9c18-3b55bb7302fb', '投翰長趙侍郎', '投翰长趙侍郎', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["禹門西面逐飄蓬，忽喜仙都得入蹤。","賈氏許頻趨季虎，荀家因敢謁頭龍。","手扶日月重輪起，數是乾坤正氣鍾。","五色筆驅神出沒，八花塼接帝從容。","詩酬御製風騷古，論似人情鼎鼐濃。","豈有地能先鳳掖，別無山更勝鼇峰。","攀鴻日淺魂飛越，爲鯉年深勢噞喁。","澤國雨荒三徑草，秦關雪折一枝筇。","吹成暖景猶葭律，引上纖蘿在嶽松。","願向明朝薦幽滯，免教號泣觸登庸。"]', '["禹门西面逐飄蓬，忽喜仙都得入蹤。","賈氏許頻趨季虎，荀家因敢謁头龙。","手扶日月重輪起，數是乾坤正氣鍾。","五色笔驱神出沒，八花塼接帝從容。","诗酬御製风騷古，論似人情鼎鼐濃。","豈有地能先鳳掖，別無山更勝鼇峰。","攀鴻日淺魂飞越，爲鯉年深勢噞喁。","澤国雨荒三徑草，秦关雪折一枝筇。","吹成暖景猶葭律，引上纖蘿在嶽松。","願向明朝薦幽滯，免教號泣觸登庸。"]', '诗', 'shi', '', NULL, '投翰長趙侍郎 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbb9c4d2-5932-4ec4-864c-aaaa230845b9', '鄜畤李相公', '鄜畤李相公', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["秦城擇日發征轅，齋戒來投節制尊。","分虎名高初命相，攀龍迹下愧登門。","夜聽謳詠銷塵夢，曉拜旌幢戰旅魂。","華舍未開寧有礙，綵毫雖乏敢無言。","生兼文武爲人傑，出應乾坤靜帝閽。","計吐六奇誰敢敵，學窮三略不須論。","功高馬卸黃金甲，臺逈賓懽白玉樽。","九穗嘉禾垂綺陌，四時甘雨帶雕軒。","推恩每覺東溟淺，吹律能令北陸暄。","青草連沙無血濺，黃榆鏁塞有鶯翻。","笙歌合沓春風郭，雞犬連延碧岫邨。","遊子不緣貪獻賦，永依棠樹託蓬根。"]', '["秦城擇日發征轅，斋戒来投節制尊。","分虎名高初命相，攀龙迹下愧登门。","夜听謳詠銷塵梦，晓拜旌幢戰旅魂。","华舍未开寧有礙，綵毫雖乏敢無言。","生兼文武爲人傑，出應乾坤静帝閽。","計吐六奇誰敢敵，学窮三略不須論。","功高马卸黄金甲，台逈賓懽白玉樽。","九穗嘉禾垂綺陌，四时甘雨带雕軒。","推恩每覺东溟淺，吹律能令北陸暄。","青草連沙無血濺，黄榆鏁塞有鶯翻。","笙歌合沓春风郭，雞犬連延碧岫邨。","游子不緣貪獻賦，永依棠樹託蓬根。"]', '诗', 'shi', '', NULL, '鄜畤李相公 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37a2093c-0f6c-4b56-9c89-e11e5200956e', '成名後呈同年', '成名後呈同年', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["業詩攻賦薦鄉書，二紀如鴻歷九衢。","待得至公搜草澤，如從平陸到蓬壺。","雖慙錦鯉成穿額，忝獲驪龍不寐珠。","蒙楚數疑休下泣，師劉大喝已爲盧。","人間灰管供紅杏，天上煙花應白榆。","一字連鑣巡甲族，千般唱罰賞皇都。","名推顏柳題金塔，飲自燕秦索玉姝。","退媿單寒終預此，敢將恩嶽怠斯須。"]', '["業诗攻賦薦乡书，二紀如鴻歷九衢。","待得至公搜草澤，如從平陸到蓬壺。","雖慙錦鯉成穿額，忝獲驪龙不寐珠。","蒙楚數疑休下泣，師劉大喝已爲盧。","人间灰管供紅杏，天上煙花應白榆。","一字連鑣巡甲族，千般唱罰賞皇都。","名推顏柳題金塔，饮自燕秦索玉姝。","退媿單寒終預此，敢將恩嶽怠斯須。"]', '诗', 'shi', '', NULL, '成名後呈同年 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c7d8911-9366-4f89-bfe2-bbae17236609', '投刑部裴郎中', '投刑部裴郎中', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["兩牓驅牽別海涔，佗門不合覓知音。","瞻恩雖隔雲雷賜，向主終知犬馬心。","禮闈後人窺作鏡，廟堂前席待爲霖。","已齊日月懸千古，肯誤風塵使陸沉。","拜首敢將誠吐血，蛻形唯待諾如金。","愁聞南院看期到，恐被東墻舊恨侵。","緇化衣空難抵雪，黑銷頭盡不勝簪。","數行淚裏依投志，直比滄溟未是深。"]', '["兩牓驱牽別海涔，佗门不合覓知音。","瞻恩雖隔云雷賜，向主終知犬马心。","禮闈後人窺作镜，廟堂前席待爲霖。","已齊日月懸千古，肯誤风塵使陸沉。","拜首敢將誠吐血，蛻形唯待諾如金。","愁闻南院看期到，恐被东墻旧恨侵。","緇化衣空难抵雪，黑銷头尽不勝簪。","數行泪裏依投志，直比滄溟未是深。"]', '诗', 'shi', '', NULL, '投刑部裴郎中 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3b94c0e-0549-42cb-b0c2-1ef22f213a6f', '輦下寓題', '輦下寓題', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["對酒何曾醉，尋僧未覺閑。","無人不惆悵，終日見南山。"]', '["对酒何曾醉，尋僧未覺闲。","無人不惆悵，終日见南山。"]', '诗', 'shi', '', NULL, '輦下寓題 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02fca0ec-0521-4e48-88c3-ce888a2dc502', '寄題崔校書郊舍', '寄題崔校书郊舍', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["一片寒塘水，尋常立鷺鷥。","主人貧愛客，沽酒往吟詩。"]', '["一片寒塘水，尋常立鷺鷥。","主人貧愛客，沽酒往吟诗。"]', '诗', 'shi', '', NULL, '寄題崔校書郊舍 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c70a56f2-cebf-4a23-8702-9a3288c657c4', '秋思', '秋思', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["碧嶂猿啼夜，新秋雨霽天。","誰人愛明月，露坐洞庭船。"]', '["碧嶂猿啼夜，新秋雨霽天。","誰人愛明月，露坐洞庭船。"]', '诗', 'shi', '', NULL, '秋思 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79988dd5-abfb-4ee1-b7b5-9ebe0b697ae4', '芳草', '芳草', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["澤國多芳草，年年長自春。","應從屈平後，更苦不歸人。"]', '["澤国多芳草，年年长自春。","應從屈平後，更苦不归人。"]', '诗', 'shi', '', NULL, '芳草 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb44459f-f6b8-4d0e-bc36-ce44898355c1', '輦下書事', '輦下书事', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["北闕新王業，東城入羽書。","秋風滿林起，誰道有鱸魚。"]', '["北闕新王業，东城入羽书。","秋风满林起，誰道有鱸鱼。"]', '诗', 'shi', '', NULL, '輦下書事 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7318c1d9-d6f0-4098-8ee0-28feed5593f5', '入關言懷', '入关言懷', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["背將蹤跡向京師，出在先春入後時。","落日灞橋飛雪裏，已聞南院有看期。"]', '["背將蹤跡向京師，出在先春入後时。","落日灞橋飞雪裏，已闻南院有看期。"]', '诗', 'shi', '', NULL, '入關言懷 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aac6e654-45f5-4f27-b743-4a8845724d10', '過長江', '過长江', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["曾搜景象恐通神，地下還應有主人。","若把長江比湘浦，離騷不合自靈均。"]', '["曾搜景象恐通神，地下還應有主人。","若把长江比湘浦，離騷不合自靈均。"]', '诗', 'shi', '', NULL, '過長江 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0ddb989-ea95-4f9c-a703-f8610cc8bd47', '題靈峰僧院', '題靈峰僧院', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["繫馬松間不忍歸，數巡香茗一枰棋。","擬登絕頂留人宿，猶待滄溟月滿時。"]', '["繫马松间不忍归，數巡香茗一枰棋。","擬登絕頂留人宿，猶待滄溟月满时。"]', '诗', 'shi', '', NULL, '題靈峰僧院 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('653dcbf4-e3ce-4ec8-8351-892bd365233c', '司馬長卿', '司马长卿', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["一自梁園失意回，無人知有掞天才。","漢宮不鏁陳皇后，誰肯量金買賦來。"]', '["一自梁园失意回，無人知有掞天才。","漢宮不鏁陳皇后，誰肯量金買賦来。"]', '诗', 'shi', '', NULL, '司馬長卿 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72b77112-aca9-4789-9779-0580b5f4cd26', '歸思', '归思', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["薊北風煙空漢月，湘南雲水半蠻邊。","寒爲旅鴈暖還去，秦越離家可十年。"]', '["薊北风煙空漢月，湘南云水半蠻邊。","寒爲旅鴈暖還去，秦越離家可十年。"]', '诗', 'shi', '', NULL, '歸思 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd2e154b-d3d1-4f68-9575-625bbe03c014', '東林寺貫休上人篆隸題詩', '东林寺貫休上人篆隸題诗', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["師名自越徹秦中，秦越難尋師所從。","墨跡兩般詩一首，香爐峰下似相逢。"]', '["師名自越徹秦中，秦越难尋師所從。","墨跡兩般诗一首，香爐峰下似相逢。"]', '诗', 'shi', '', NULL, '東林寺貫休上人篆隸題詩 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d726737e-ebce-45bb-81f1-5b24f1928bf5', '寓江州李使君', '寓江州李使君', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["使君曾被蟬聲苦，每見詞文即爲愁。","況是楚江鴻到後，可堪西望發孤舟。"]', '["使君曾被蟬声苦，每见词文即爲愁。","況是楚江鴻到後，可堪西望發孤舟。"]', '诗', 'shi', '', NULL, '寓江州李使君 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67f842f0-287e-4d31-a84f-77984c8eabbb', '遊南寓題', '游南寓題', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["江山節被雪霜遺，毒草過秋未擬衰。","天不當時命鄒衍，亦將寒律入南吹。"]', '["江山節被雪霜遺，毒草過秋未擬衰。","天不當时命鄒衍，亦將寒律入南吹。"]', '诗', 'shi', '', NULL, '遊南寓題 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f7aa957-4d8c-437e-a72b-3418f666177f', '和同年趙先輩觀文', '和同年趙先輩观文', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["玉兔輪中方是樹，金鼇頂上別無山。","雖然迴首見煙水，事主酬恩難便閑。"]', '["玉兔輪中方是樹，金鼇頂上別無山。","雖然迴首见煙水，事主酬恩难便闲。"]', '诗', 'shi', '', NULL, '和同年趙先輩觀文 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ebee9ba-e492-45b3-a893-e4d62c9bcd22', '出京別同年', '出京別同年', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["一枝仙桂已攀援，歸去煙濤浦口邨。","雖恨別離還有意，槐花黃日出青門。"]', '["一枝仙桂已攀援，归去煙濤浦口邨。","雖恨別離還有意，槐花黄日出青门。"]', '诗', 'shi', '', NULL, '出京別同年 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f390124-8cb4-4b20-92b5-423821350439', '木芙蓉三首 一', '木芙蓉三首 一', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["黃鳥啼煙二月朝，若教開即牡丹饒。","天嫌青帝恩光盛，留與秋風雪寂寥。"]', '["黄鸟啼煙二月朝，若教开即牡丹饒。","天嫌青帝恩光盛，留與秋风雪寂寥。"]', '诗', 'shi', '', NULL, '木芙蓉三首 一 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eb5c29f-42ed-4ae7-a2f9-f549b331decc', '木芙蓉三首 二', '木芙蓉三首 二', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["卻假青腰女剪成，綠羅囊綻綵霞呈。","誰憐不及黃花菊，只遇陶潛便得名。"]', '["卻假青腰女剪成，綠羅囊綻綵霞呈。","誰怜不及黄花菊，只遇陶潛便得名。"]', '诗', 'shi', '', NULL, '木芙蓉三首 二 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b76cf1-43fb-43ea-8eab-0d94826a116e', '木芙蓉三首 三', '木芙蓉三首 三', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["須到露寒方有態，爲經霜裛稍無香。","移根若在秦宮裏，多少佳人泣曉妝。"]', '["須到露寒方有態，爲經霜裛稍無香。","移根若在秦宮裏，多少佳人泣晓妝。"]', '诗', 'shi', '', NULL, '木芙蓉三首 三 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef3f6c05-bd3b-4e31-a853-22352715d2e9', '九日', '九日', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["陽數重時陰數殘，露濃風硬欲成寒。","莫言黃菊花開晚，獨占樽前一日歡。"]', '["陽數重时陰數殘，露濃风硬欲成寒。","莫言黄菊花开晚，独占樽前一日歡。"]', '诗', 'shi', '', NULL, '九日 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0debd5ca-5faa-4195-ab3a-719760271552', '夏州道中', '夏州道中', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["隴鴈南飛河水流，秦城千里忍回頭。","征行渾與求名背，九月中旬往夏州。"]', '["隴鴈南飞河水流，秦城千里忍回头。","征行渾與求名背，九月中旬往夏州。"]', '诗', 'shi', '', NULL, '夏州道中 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('261454ae-a203-403a-83a6-ddcf9f24b88b', '經慈州感謝郎中', '經慈州感謝郎中', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["金聲乃是古詩流，況有池塘春草儔。","莫遣宣城獨垂號，雲山彼此謝公遊。"]', '["金声乃是古诗流，況有池塘春草儔。","莫遣宣城独垂號，云山彼此謝公游。"]', '诗', 'shi', '', NULL, '經慈州感謝郎中 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8e18a32-07cd-4bdf-bc22-fcb1ac29960e', '寓題', '寓題', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["吳中煙水越中山，莫把漁樵謾自寬。","歸泛扁舟可容易，五湖高士是拋官。"]', '["吳中煙水越中山，莫把漁樵謾自寬。","归泛扁舟可容易，五湖高士是拋官。"]', '诗', 'shi', '', NULL, '寓題 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dac0a65-b1a2-4904-a336-c0a32afd0517', '寄宋明府', '寄宋明府', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["北闕秋期南國身，重關煙月五溪雲。","風蟬已有數聲急，賴在陶家柳下聞。"]', '["北闕秋期南国身，重关煙月五溪云。","风蟬已有數声急，賴在陶家柳下闻。"]', '诗', 'shi', '', NULL, '寄宋明府 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9212cbec-f405-4f08-a5dd-ad3ad3a327af', '靈均', '靈均', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["莫問靈均昔日遊，江蘺春盡岸楓秋。","至今此事何人雪，月照楚山湘水流。"]', '["莫问靈均昔日游，江蘺春尽岸楓秋。","至今此事何人雪，月照楚山湘水流。"]', '诗', 'shi', '', NULL, '靈均 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('359257da-afcf-4b8c-aae5-fe5c8df3addd', '馬嵬', '马嵬', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["錦江晴碧劒鋒奇，合有千年降聖時。","天意從來知幸蜀，不關胎禍自蛾眉。"]', '["錦江晴碧劒鋒奇，合有千年降聖时。","天意從来知幸蜀，不关胎禍自蛾眉。"]', '诗', 'shi', '', NULL, '馬嵬 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0822e517-d03d-4dd7-94a7-2d60873ccc87', '和陳先輩陪陸舍人春日遊曲江', '和陳先輩陪陸舍人春日游曲江', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["劉超遊召郄詵陪，爲憶池亭舊賞來。","紅杏花旁見山色，詩成因觸鼓聲回。"]', '["劉超游召郄詵陪，爲憶池亭旧賞来。","紅杏花旁见山色，诗成因觸鼓声回。"]', '诗', 'shi', '', NULL, '和陳先輩陪陸舍人春日遊曲江 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('164f2527-1886-49a6-8a4a-a51f07181e93', '花', '花', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["莫道顏色如渥丹，莫道馨香過𦶜蘭。","東風吹綻還吹落，明日誰爲今日看。"]', '["莫道顏色如渥丹，莫道馨香過𦶜蘭。","东风吹綻還吹落，明日誰爲今日看。"]', '诗', 'shi', '', NULL, '花 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33b5a5a1-f03e-4d38-a188-3f17a8316fac', '卷簾', '卷簾', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["綠鬟侍女手纖纖，新捧嫦娥出素蟾。","衛玠官高難久立，莫辭雙卷水精簾。"]', '["綠鬟侍女手纖纖，新捧嫦娥出素蟾。","衛玠官高难久立，莫辞雙卷水精簾。"]', '诗', 'shi', '', NULL, '卷簾 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60dce9b6-5acf-4727-95ed-5b9d4cc195f8', '啓帳', '啓帳', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["得人憎定繡芙蓉，愛鏁嫦娥出月蹤。","侍女莫嫌擡素手，拔開珠翠待相逢。"]', '["得人憎定繡芙蓉，愛鏁嫦娥出月蹤。","侍女莫嫌擡素手，拔开珠翠待相逢。"]', '诗', 'shi', '', NULL, '啓帳 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('319de2e2-3f3b-43e2-b797-61042a2f6abc', '去扇', '去扇', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["城上風生蠟炬寒，錦帷開處露翔鸞。","已知秦女昇仙態，休把圓輕隔牡丹。"]', '["城上风生蠟炬寒，錦帷开处露翔鸾。","已知秦女昇仙態，休把圓轻隔牡丹。"]', '诗', 'shi', '', NULL, '去扇 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1024ff77-7ec5-4a36-9e61-eb353c11efaa', '別後', '別後', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["夢裏相逢無後期，煙中解珮杳何之。","虧蟾便是陳宮鏡，莫吐清光照別離。"]', '["梦裏相逢無後期，煙中解珮杳何之。","虧蟾便是陳宮镜，莫吐清光照別離。"]', '诗', 'shi', '', NULL, '別後 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf298977-be7e-473e-9c96-050816004072', '嚴陵釣臺', '嚴陵釣台', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["終向煙霞作野夫，一竿竹不換簪裾。","直鉤猶逐熊羆起，獨是先生真釣魚。"]', '["終向煙霞作野夫，一竿竹不換簪裾。","直鉤猶逐熊羆起，独是先生真釣鱼。"]', '诗', 'shi', '', NULL, '嚴陵釣臺 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d690803-c2cc-4711-93ed-a26a630b45ec', '馬嵬二首 一', '马嵬二首 一', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["鐵馬嘶風一渡河，淚珠零便作驚波。","鳴泉亦感上皇意，流下隴頭嗚咽多。"]', '["鐵马嘶风一渡河，泪珠零便作驚波。","鳴泉亦感上皇意，流下隴头嗚咽多。"]', '诗', 'shi', '', NULL, '馬嵬二首 一 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4daaafd-e10c-4869-a7c8-8ceeb7be5558', '馬嵬二首 二', '马嵬二首 二', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["龍腦移香鳳輦留，可能千古永悠悠。","夜臺若使香魂在，應作煙花出隴頭。"]', '["龙腦移香鳳輦留，可能千古永悠悠。","夜台若使香魂在，應作煙花出隴头。"]', '诗', 'shi', '', NULL, '馬嵬二首 二 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c65b301-22b2-4ee7-b590-f81cd50c3184', '閏八月', '閏八月', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["無人不愛今年閏，月看中秋兩度圓。","唯恐雨師風伯意，至時還奪上樓天。"]', '["無人不愛今年閏，月看中秋兩度圓。","唯恐雨師风伯意，至时還奪上楼天。"]', '诗', 'shi', '', NULL, '閏八月 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce8a79d8-8673-472d-a803-c49a73831b1d', '奉和翁文堯戲寄', '奉和翁文堯戲寄', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["掘蘭宮裏數名郎，好是乘軺出帝鄉。","兩度還家還未有，別論光彩向冠裳。"]', '["掘蘭宮裏數名郎，好是乘軺出帝乡。","兩度還家還未有，別論光彩向冠裳。"]', '诗', 'shi', '', NULL, '奉和翁文堯戲寄 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e996c456-84b3-43a2-a846-5ef5d5310e5c', '奉和文堯對庭前千葉石榴', '奉和文堯对庭前千葉石榴', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["一朵千英綻曉枝，綵霞堪與別爲期。","移根若在芙蓉苑，豈向當年有醒時。"]', '["一朵千英綻晓枝，綵霞堪與別爲期。","移根若在芙蓉苑，豈向當年有醒时。"]', '诗', 'shi', '', NULL, '奉和文堯對庭前千葉石榴 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1425c663-94eb-45cd-a3cf-d2bf7ce869f4', '翁文堯以美疹暫滯令公大王益得異禮觀今日寵待之盛輙成一章', '翁文堯以美疹暫滯令公大王益得異禮观今日寵待之盛輙成一章', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["滋賦諴文侯李盛，終求一襲錦衣難。","如何兩度還州里，兼借鄉人更剩觀。"]', '["滋賦諴文侯李盛，終求一襲錦衣难。","如何兩度還州里，兼借乡人更剩观。"]', '诗', 'shi', '', NULL, '翁文堯以美疹暫滯令公大王益得異禮觀今日寵待之盛輙成一章 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a65d2b0d-7f27-4f8a-bc9f-6d7dab32b38a', '贈友人', '贈友人', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["超達陶子性，留琴不設弦。","覓句朝忘食，傾杯夜廢眠。","愛月影爲伴，吟風聲自連。","聽此鶯飛谷，心懷迷遠川。"]', '["超達陶子性，留琴不設弦。","覓句朝忘食，傾杯夜廢眠。","愛月影爲伴，吟风声自連。","听此鶯飞谷，心懷迷远川。"]', '诗', 'shi', '', NULL, '贈友人 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be18e8c2-3439-4545-a001-412dd1fe9fcd', '八月十五夜', '八月十五夜', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["萬里無雲鏡九州，最團圓夜是中秋。","滿衣冰彩拂不落，遍地水光凝欲流。","華嶽影寒清露掌，海門風急白潮頭。","因君照我丹心事，減得愁人一夕愁。"]', '["万里無云镜九州，最團圓夜是中秋。","满衣冰彩拂不落，遍地水光凝欲流。","华嶽影寒清露掌，海门风急白潮头。","因君照我丹心事，減得愁人一夕愁。"]', '诗', 'shi', '', NULL, '八月十五夜 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4828c852-5e8d-46da-882a-979fad7607eb', '省試夜投獻座主', '省試夜投獻座主', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["闢開公道選時英，神鏡高懸鑒百靈。","混沌分來融間氣，欃槍滅處炫文星。","燭然蘭省三條白，山束龍門萬仞青。","聖教中興周禮在，不勞干羽舞明庭。"]', '["闢开公道選时英，神镜高懸鑒百靈。","混沌分来融间氣，欃槍滅处炫文星。","燭然蘭省三條白，山束龙门万仞青。","聖教中兴周禮在，不勞干羽舞明庭。"]', '诗', 'shi', '', NULL, '省試夜投獻座主 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('959dc756-157a-43be-bc74-0e6894a574e3', '觀賀皇太子冊命', '观賀皇太子冊命', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["嗣冊儲皇帝命行，萬方臣妾躍歡聲。","鸞旃再立星辰正，雉扇雙開日月明。","自有漢元爭翊戴，不勞商皓定欹傾。","春宮保傅皆周召，致主何憂不太平。"]', '["嗣冊儲皇帝命行，万方臣妾躍歡声。","鸾旃再立星辰正，雉扇雙开日月明。","自有漢元爭翊戴，不勞商皓定欹傾。","春宮保傅皆周召，致主何憂不太平。"]', '诗', 'shi', '', NULL, '觀賀皇太子冊命 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64411680-cdf3-4f5a-aaa6-1e9c4e3d6e56', '行朝早春侍師門宴西溪席上作', '行朝早春侍師门宴西溪席上作', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["西溪水色淨於苔，畫鷁橫風絳帳開。","弦管旋飄蓬島去，公卿皆是蘂宮來。","金鱗擲浪錢翻荇，玉爵黏香雪泛梅。","三榜生徒逾七十，豈期龍坂納非才。"]', '["西溪水色淨於苔，畫鷁橫风絳帳开。","弦管旋飄蓬島去，公卿皆是蘂宮来。","金鱗擲浪錢翻荇，玉爵黏香雪泛梅。","三榜生徒逾七十，豈期龙坂納非才。"]', '诗', 'shi', '', NULL, '行朝早春侍師門宴西溪席上作 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('048f2dc1-4cd8-4fb6-bfc5-ce107fc6773c', '賀同年第三人劉先輩鹹辟命', '賀同年第三人劉先輩鹹辟命', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["甲門才子鼎科人，拂地藍衫榜下新。","脫俗文章笑鸚鵡，凌雲頭角壓麒麟。","金壺藉草溪亭晚，玉勒穿花野寺春。","多媿受恩同闕里，不嫌師僻與顏貧。"]', '["甲门才子鼎科人，拂地藍衫榜下新。","脫俗文章笑鸚鵡，凌云头角壓麒麟。","金壺藉草溪亭晚，玉勒穿花野寺春。","多媿受恩同闕里，不嫌師僻與顏貧。"]', '诗', 'shi', '', NULL, '賀同年第三人劉先輩鹹辟命 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d33f925-f3fd-4871-9bc8-5c9315f7312c', '寄廣南劉僕射', '寄廣南劉僕射', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["戰國從今却尚文，品流才子作將軍。","畫船清宴蠻溪雨，粉閣閑吟瘴嶠雲。","暴客卸戈歸惠政，史官調筆待儒勳。","漢儀一化南人後，牧馬無因更夜聞。"]', '["戰国從今却尚文，品流才子作將軍。","畫船清宴蠻溪雨，粉閣闲吟瘴嶠云。","暴客卸戈归惠政，史官調笔待儒勳。","漢儀一化南人後，牧马無因更夜闻。"]', '诗', 'shi', '', NULL, '寄廣南劉僕射 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef81769f-400d-48b5-99b1-7a66b4185f66', '題吳中陸龜蒙山齋', '題吳中陸龟蒙山斋', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["萬卷圖書千戶貴，十洲煙景四時和。","花心露洗猩猩血，水面風披瑟瑟羅。","莊叟靜眠清夢永，客兒芳意小詩多。","天麟不觸人間網，擬把公卿換得麽。"]', '["万卷圖书千戶貴，十洲煙景四时和。","花心露洗猩猩血，水面风披瑟瑟羅。","莊叟静眠清梦永，客兒芳意小诗多。","天麟不觸人间網，擬把公卿換得麽。"]', '诗', 'shi', '', NULL, '題吳中陸龜蒙山齋 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2051671a-5e25-4f77-9949-acfc38fbf8ef', '經李翰林墓', '經李翰林墓', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["詩中日月酒中仙，平地雄飛上九天。","身謫蓬萊金籍外，寶裝方丈玉堂前。","虎靴醉索將軍脫，鴻筆悲無令子傳。","十字遺碑三尺墓，只應吟客弔秋煙。"]', '["诗中日月酒中仙，平地雄飞上九天。","身謫蓬萊金籍外，寶裝方丈玉堂前。","虎靴醉索將軍脫，鴻笔悲無令子傳。","十字遺碑三尺墓，只應吟客弔秋煙。"]', '诗', 'shi', '', NULL, '經李翰林墓 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5b7e409-6604-4c9a-a0c4-d39550e78923', '鸚鵡', '鸚鵡', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["丹觜如簧翠羽輕，隨人呼物旋知名。","金籠夜黯山西夢，玉枕曉憎簾外聲。","才子愛奇吟不足，美人憐爾繡初成。","應緣是我邯鄲客，相顧咬咬別有情。"]', '["丹觜如簧翠羽轻，隨人呼物旋知名。","金籠夜黯山西梦，玉枕晓憎簾外声。","才子愛奇吟不足，美人怜爾繡初成。","應緣是我邯鄲客，相顧咬咬別有情。"]', '诗', 'shi', '', NULL, '鸚鵡 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3904587-9b0d-4237-a4a2-8834978e9d44', '邊將別', '邊將別', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["地角天涯倍苦辛，十年鉛槧未酬身。","朱門泣別同鮫客，紫塞旅游隨鴈臣。","漢將出師衝曉雪，胡兒奔馬撲征塵。","行行獨止干戈域，毳帳望誰爲主人。"]', '["地角天涯倍苦辛，十年鉛槧未酬身。","朱门泣別同鮫客，紫塞旅游隨鴈臣。","漢將出師衝晓雪，胡兒奔马撲征塵。","行行独止干戈域，毳帳望誰爲主人。"]', '诗', 'shi', '', NULL, '邊將別 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc384618-e5d9-45da-89ba-4e1165ae78a7', '江南秋日', '江南秋日', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["水國由來稱道情，野人經此頓神清。","一篷秋雨睡初起，半硯冷雲吟未成。","青笠漁兒筒釣沒，蒨衣菱女畫橈輕。","冰綃寫上江南景，寄與金鑾馬長卿。"]', '["水国由来稱道情，野人經此頓神清。","一篷秋雨睡初起，半硯冷云吟未成。","青笠漁兒筒釣沒，蒨衣菱女畫橈轻。","冰綃寫上江南景，寄與金鑾马长卿。"]', '诗', 'shi', '', NULL, '江南秋日 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9e3801b-4982-4eaa-bd9c-e62b9cb7647e', '題友人庭竹', '題友人庭竹', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["叢篁蕭瑟拂清陰，貴地栽成碧玉林。","盡待花開添鳳食，可憐風擊狀龍吟。","鈿竿離立霜文靜，錦籜飄零粉節深。","何事子猷偏寄賞，此君心似古人心。"]', '["叢篁蕭瑟拂清陰，貴地栽成碧玉林。","尽待花开添鳳食，可怜风擊狀龙吟。","鈿竿離立霜文静，錦籜飄零粉節深。","何事子猷偏寄賞，此君心似古人心。"]', '诗', 'shi', '', NULL, '題友人庭竹 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33f9a100-e59f-4074-a35d-4ec1320029da', '覽陸龜蒙舊集', '覽陸龟蒙旧集', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["先生文價沸三吳，白雪千編酒一壺。","吟去星辰筆下動，醉來嵩華眼中無。","峭如謝檜虬蟠活，清似緱山鳳路孤。","身後獨遺封禪草，何人尋得佐鴻圖。"]', '["先生文價沸三吳，白雪千編酒一壺。","吟去星辰笔下动，醉来嵩华眼中無。","峭如謝檜虬蟠活，清似緱山鳳路孤。","身後独遺封禪草，何人尋得佐鴻圖。"]', '诗', 'shi', '', NULL, '覽陸龜蒙舊集 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c2885f8-4869-42a3-8694-121f6726cc68', '玉仙道中', '玉仙道中', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["蓴鱸方美別吳江，筆陣詩魔兩未降。","山勢北蟠龍偃蹇，泉聲東漱玉琤瑽。","古陂狐兔穿蠻塚，破寺荆榛擁佛幢。","信馬冷吟迷路處，隔溪煙雨吠村厖。"]', '["蓴鱸方美別吳江，笔陣诗魔兩未降。","山勢北蟠龙偃蹇，泉声东漱玉琤瑽。","古陂狐兔穿蠻塚，破寺荆榛擁佛幢。","信马冷吟迷路处，隔溪煙雨吠村厖。"]', '诗', 'shi', '', NULL, '玉仙道中 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cf65f7b-80ef-442c-a6ce-202ec1898b2e', '趙侍郎看紅白牡丹因寄楊狀頭贊圖', '趙侍郎看紅白牡丹因寄楊狀头贊圖', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["遲開都爲讓羣芳，貴地栽成對玉堂。","紅豔褭煙疑欲語，素華映月只聞香。","翦裁偏得東風意，淡薄似矜西子粧。","雅稱花中爲首冠，年年長占斷春光。"]', '["遲开都爲讓羣芳，貴地栽成对玉堂。","紅豔褭煙疑欲語，素华映月只闻香。","翦裁偏得东风意，淡薄似矜西子粧。","雅稱花中爲首冠，年年长占斷春光。"]', '诗', 'shi', '', NULL, '趙侍郎看紅白牡丹因寄楊狀頭贊圖 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb7e7cec-9087-4a62-a10a-7152f5952827', '題胡州太學丘光庭博士幽居', '題胡州太学丘光庭博士幽居', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["舜軌堯文混九垓，明堂宏構集良材。","江邊雲臥如龍穩，天外泥書遣鶴來。","五夜藥苗滋沆瀣，四時花影蔭莓苔。","草玄門似山中靜，不是公卿到不開。"]', '["舜軌堯文混九垓，明堂宏構集良材。","江邊云臥如龙穩，天外泥书遣鹤来。","五夜藥苗滋沆瀣，四时花影蔭莓苔。","草玄门似山中静，不是公卿到不开。"]', '诗', 'shi', '', NULL, '題胡州太學丘光庭博士幽居 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d642f6a-bf3f-4d38-8b29-c82e3dbd357a', '初秋留別越中幕客', '初秋留別越中幕客', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["魂夢飄零落葉洲，北轅南柁幾時休。","月中青桂漸看老，星畔白榆還報秋。","鶴禁有知須強進，稽峰無事莫相留。","吳花越柳饒君醉，直待功成始舉頭。"]', '["魂梦飄零落葉洲，北轅南柁幾时休。","月中青桂漸看老，星畔白榆還報秋。","鹤禁有知須強進，稽峰無事莫相留。","吳花越柳饒君醉，直待功成始舉头。"]', '诗', 'shi', '', NULL, '初秋留別越中幕客 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bcee197-0482-4fa9-816a-ae5dfecd785e', '送道者朝見後歸山', '送道者朝见後归山', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["暫隨蒲帛謁金鑾，蕭灑風儀傲漢官。","天馬難將朱索絆，海鼇寧覺碧濤寬。","松壇月作尊前伴，竹篋書爲教外歡。","神鼎已乾龍虎伏，一條真氣出雲端。"]', '["暫隨蒲帛謁金鑾，蕭灑风儀傲漢官。","天马难將朱索絆，海鼇寧覺碧濤寬。","松壇月作尊前伴，竹篋书爲教外歡。","神鼎已乾龙虎伏，一條真氣出云端。"]', '诗', 'shi', '', NULL, '送道者朝見後歸山 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78181ffb-edb3-4526-86b1-a8717931a6b3', '贈戰將', '贈戰將', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["綠沈槍利雪峰尖，犀甲軍裝稱紫髯。","威懾萬人長凜凜，禮延羣客每謙謙。","陣前戰馬黃金勒，架上兵書白玉籤。","不爲已爲儒弟子，好依門下學韜鈐。"]', '["綠沈槍利雪峰尖，犀甲軍裝稱紫髯。","威懾万人长凜凜，禮延羣客每謙謙。","陣前戰马黄金勒，架上兵书白玉籤。","不爲已爲儒弟子，好依门下学韜鈐。"]', '诗', 'shi', '', NULL, '贈戰將 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3899229a-f54d-4dd5-beb7-ff87fad2f79e', '九華賀雨吟', '九华賀雨吟', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["陶公焦思念生靈，變旱爲豐合杳冥。","雷劈老松疑虎怒，雨衝陰洞覺龍腥。","萬畦香稻蓬葱綠，九朵奇峰撲亞青。","吟賀西成饒旅興，散絲飛灑滿長亭。"]', '["陶公焦思念生靈，变旱爲豐合杳冥。","雷劈老松疑虎怒，雨衝陰洞覺龙腥。","万畦香稻蓬葱綠，九朵奇峰撲亞青。","吟賀西成饒旅兴，散絲飞灑满长亭。"]', '诗', 'shi', '', NULL, '九華賀雨吟 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('174936ab-68e3-4c07-9d17-ce9f47869b60', '贈池州張太守', '贈池州張太守', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["神珠無纇玉無瑕，七葉簪貂漢相家。","陣面奔星破犀象，筆頭飛電躍龍蛇。","絳幃夜坐窮三史，紅斾春行到九華。","只怕池人留不住，別遷征鎮擁高牙。"]', '["神珠無纇玉無瑕，七葉簪貂漢相家。","陣面奔星破犀象，笔头飞電躍龙蛇。","絳幃夜坐窮三史，紅斾春行到九华。","只怕池人留不住，別遷征鎮擁高牙。"]', '诗', 'shi', '', NULL, '贈池州張太守 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acffe249-58f6-4689-94b7-3a06a4b5f412', '中秋自宛陵寄池陽太守', '中秋自宛陵寄池陽太守', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["出山三見月如眉，蝶夢終宵遶戟枝。","旅客思歸鴻去日，賢侯行化子來時。","郡樓遐想劉琨嘯，相閤方窺謝傅棊。","按部況聞秋稼熟，馬前迎拜羨幷兒。"]', '["出山三见月如眉，蝶梦終宵遶戟枝。","旅客思归鴻去日，賢侯行化子来时。","郡楼遐想劉琨嘯，相閤方窺謝傅棊。","按部況闻秋稼熟，马前迎拜羨幷兒。"]', '诗', 'shi', '', NULL, '中秋自宛陵寄池陽太守 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('822e27e9-1b17-44c8-bd94-3718a5519061', '次韻九華杜先輩重陽寄投宛陵丞相', '次韻九华杜先輩重陽寄投宛陵丞相', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["日下飛聲徹不毛，酒醒時得廣離騷。","先生鬢爲吟詩白，上相心因治國勞。","千乘信迴魚榼重，九華秋逈鳳巢高。","強酬小謝重陽句，沙恨無金盡日淘。"]', '["日下飞声徹不毛，酒醒时得廣離騷。","先生鬢爲吟诗白，上相心因治国勞。","千乘信迴鱼榼重，九华秋逈鳳巢高。","強酬小謝重陽句，沙恨無金尽日淘。"]', '诗', 'shi', '', NULL, '次韻九華杜先輩重陽寄投宛陵丞相 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('457546e8-e8ef-460f-8487-a578ce833f51', '寄賀杜荀鶴及第', '寄賀杜荀鹤及第', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["一戰平疇五字勞，晝歸鄉去錦爲袍。","大鵬出海翎猶濕，駿馬辭天氣正豪。","九子舊山增秀絕，二南新格變風騷。","由來稽古符公道，平地丹梯甲乙高。"]', '["一戰平疇五字勞，晝归乡去錦爲袍。","大鵬出海翎猶濕，駿马辞天氣正豪。","九子旧山增秀絕，二南新格变风騷。","由来稽古符公道，平地丹梯甲乙高。"]', '诗', 'shi', '', NULL, '寄賀杜荀鶴及第 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb0d9309-0baf-4a4a-8321-dd443dd5e45d', '春草碧色', '春草碧色', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["細草含愁碧，芊綿南浦濱。","萋萋如恨別，苒苒共傷春。","疎雨煙華潤，斜陽細彩勻。","花黏繁鬬錦，人藉軟勝茵。","淺映宮池水，輕遮輦路塵。","杜回如可結，誓作報恩身。"]', '["細草含愁碧，芊綿南浦濱。","萋萋如恨別，苒苒共傷春。","疎雨煙华潤，斜陽細彩勻。","花黏繁鬬錦，人藉軟勝茵。","淺映宮池水，轻遮輦路塵。","杜回如可結，誓作報恩身。"]', '诗', 'shi', '', NULL, '春草碧色 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e95f1266-9a74-4f8b-9a9e-b42439d7d779', '和友人送衡尚書赴池陽副車', '和友人送衡尚书赴池陽副车', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["淮王上將例分憂，玉帳參承半列侯。","次第選材如創廈，別離排宴向藏舟。","鵾鵬變化知難測，龍蠖升沈各有由。","躞蹀行牽金鋄重，嬋娟立唱翠娥愁。","築頭勳業諧三陣，滿腹詩書究九流。","金海珠韜乘月讀，肉芝牙茗撥雲收。","赤鱗斾卷鷗汀晚，青雀船橫雁陣秋。","十字細波澄鏡面，九華殘雪露峰頭。","醉沈北海千尊酒，吟上南荆百尺樓。","況是昭明食魚郡，不妨閑擲釣璜鉤。"]', '["淮王上將例分憂，玉帳參承半列侯。","次第選材如創廈，別離排宴向藏舟。","鵾鵬变化知难測，龙蠖升沈各有由。","躞蹀行牽金鋄重，嬋娟立唱翠娥愁。","築头勳業諧三陣，满腹诗书究九流。","金海珠韜乘月读，肉芝牙茗撥云收。","赤鱗斾卷鷗汀晚，青雀船橫雁陣秋。","十字細波澄镜面，九华殘雪露峰头。","醉沈北海千尊酒，吟上南荆百尺楼。","況是昭明食鱼郡，不妨闲擲釣璜鉤。"]', '诗', 'shi', '', NULL, '和友人送衡尚書赴池陽副車 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0d02af5-49b2-4789-9060-d34beaeae368', '貽李南平', '貽李南平', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["紫殿西頭月欲斜，曾草臨淮上相麻。","潤筆已曾經奏謝，更飛章句問張華。"]', '["紫殿西头月欲斜，曾草臨淮上相麻。","潤笔已曾經奏謝，更飞章句问張华。"]', '诗', 'shi', '', NULL, '貽李南平 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cad9759d-76f9-445c-bff4-55d6c7585aa7', '句', '句', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["龍舒太守人中傑，風韻堂中心似月。","衆口聲光誇漢將，築頭勳業佐淮王。"]', '["龙舒太守人中傑，风韻堂中心似月。","衆口声光誇漢將，築头勳業佐淮王。"]', '诗', 'shi', '', NULL, '句 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a818ec31-bce5-4670-b777-ed0179e358f0', '釣臺', '釣台', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["金門誰奉詔，碧岸獨垂鉤。","舊友秪樵叟，新交惟野鷗。","嘉名懸日月，深谷化陵丘。","便可招巢父，長川好飲牛。"]', '["金门誰奉詔，碧岸独垂鉤。","旧友秪樵叟，新交惟野鷗。","嘉名懸日月，深谷化陵丘。","便可招巢父，长川好饮牛。"]', '诗', 'shi', '', NULL, '釣臺 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45d68ebb-a650-436d-991d-ca1dab63416f', '旅次寓題', '旅次寓題', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["胡爲名利役，來往老關河。","白髮隨梳少，青山入夢多。","途窮憐抱疾，世亂恥登科。","却起漁舟念，春風釣綠波。"]', '["胡爲名利役，来往老关河。","白髮隨梳少，青山入梦多。","途窮怜抱疾，世亂恥登科。","却起漁舟念，春风釣綠波。"]', '诗', 'shi', '', NULL, '旅次寓題 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b4f29af-952b-48d1-a246-feec0db8fdfb', '贈嚴司直', '贈嚴司直', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["承家居闕下，避世出關東。","有酒劉伶醉，無兒伯道窮。","新詩吟閣賞，舊業釣臺空。","雨雪還相訪，心懷與我同。"]', '["承家居闕下，避世出关东。","有酒劉伶醉，無兒伯道窮。","新诗吟閣賞，旧業釣台空。","雨雪還相訪，心懷與我同。"]', '诗', 'shi', '', NULL, '贈嚴司直 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f436348-55cb-404f-bcce-e1bf8f36fa03', '贈東方道士', '贈东方道士', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["葫蘆窗畔挂，是物在其間。","雪色老人鬢，桃花童子顏。","祭星秋卜日，採藥曉登山。","舊放長生鹿，時銜瑞草還。"]', '["葫蘆窗畔挂，是物在其间。","雪色老人鬢，桃花童子顏。","祭星秋卜日，採藥晓登山。","旧放长生鹿，时銜瑞草還。"]', '诗', 'shi', '', NULL, '贈東方道士 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d62a8d55-1bec-4ef5-a341-4c566105583f', '題僧壁', '題僧壁', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["香廚流瀑布，獨院鎖孤峯。","紺髮青螺長，文茵紫豹重。","卵枯皆化燕，蜜老却成蜂。","明月留人宿，秋聲夜著松。"]', '["香廚流瀑布，独院鎖孤峯。","紺髮青螺长，文茵紫豹重。","卵枯皆化燕，蜜老却成蜂。","明月留人宿，秋声夜著松。"]', '诗', 'shi', '', NULL, '題僧壁 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e788296a-618f-4de8-866f-9c93943a9592', '和人經隋唐間戰處', '和人經隋唐间戰处', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["孤軍前度戰，一敗一成功。","卷斾早歸國，臥屍猶臂弓。","草間腥半在，沙上血殘紅。","傷魄何爲者，五湖垂釣翁。"]', '["孤軍前度戰，一敗一成功。","卷斾早归国，臥屍猶臂弓。","草间腥半在，沙上血殘紅。","傷魄何爲者，五湖垂釣翁。"]', '诗', 'shi', '', NULL, '和人經隋唐間戰處 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5acb904b-327c-47fd-a213-11883d78ef9e', '追和常建嘆王昭君', '追和常建嘆王昭君', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["紅顏如朔雪，日爍忽成空。","淚盡黃雲雨，塵消白草風。","君心爭不悔，恨思竟何窮。","願化南飛燕，年年入漢宮。"]', '["紅顏如朔雪，日爍忽成空。","泪尽黄云雨，塵消白草风。","君心爭不悔，恨思竟何窮。","願化南飞燕，年年入漢宮。"]', '诗', 'shi', '', NULL, '追和常建嘆王昭君 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7cc5a70-0618-4815-b708-42dc8c95d9eb', '贈董先生', '贈董先生', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["壽歲過於百，時閑到上京。","餐松雙鬢嫩，絕粒四支輕。","雨雪思中嶽，雲霞夢赤城。"]', '["壽歲過於百，时闲到上京。","餐松雙鬢嫩，絕粒四支轻。","雨雪思中嶽，云霞梦赤城。"]', '诗', 'shi', '', NULL, '贈董先生 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a461b94-a0f1-411e-b70b-8809b679e8d6', '河流', '河流', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["洪流盤砥柱，淮濟不同波。","莫訝清時少，都緣曲處多。","遠能通玉塞，高復接銀河。","大禹成門嶮，爲龍始得過。"]', '["洪流盤砥柱，淮濟不同波。","莫訝清时少，都緣曲处多。","远能通玉塞，高复接銀河。","大禹成门嶮，爲龙始得過。"]', '诗', 'shi', '', NULL, '河流 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79f0a17f-b45d-4489-8cdf-eb5f2b61d584', '題南寺', '題南寺', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["久別猨啼寺，流年刦逝波。","舊僧歸塔盡，古瓦長松多。","壁蘚昏題記，窗螢散薜蘿。","平生英壯節，何故旋消磨。"]', '["久別猨啼寺，流年刦逝波。","旧僧归塔尽，古瓦长松多。","壁蘚昏題記，窗螢散薜蘿。","平生英壯節，何故旋消磨。"]', '诗', 'shi', '', NULL, '題南寺 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('430a8367-6d33-4bf0-8eea-c5af9dd9cdfe', '北山秋晚', '北山秋晚', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["十載衣裘盡，臨寒隱薜蘿。","心閑緣事少，身老愛山多。","玉露催收菊，金風促翦禾。","燕秦正戎馬，林下好婆娑。"]', '["十載衣裘尽，臨寒隐薜蘿。","心闲緣事少，身老愛山多。","玉露催收菊，金风促翦禾。","燕秦正戎马，林下好婆娑。"]', '诗', 'shi', '', NULL, '北山秋晚 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63bd98e1-2a01-4500-8d77-326af085e05b', '昔遊', '昔游', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["昔遊紅杏苑，今隱刺桐村。","歲計懸僧債，科名負國恩。","不書胝漸穩，頻鑷鬢無根。","惟有經邦事，年年志尚存。"]', '["昔游紅杏苑，今隐刺桐村。","歲計懸僧債，科名負国恩。","不书胝漸穩，頻鑷鬢無根。","惟有經邦事，年年志尚存。"]', '诗', 'shi', '', NULL, '昔遊 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef5ca4bd-7ef3-437f-97c4-c306cc9d95e9', '酒胡子', '酒胡子', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["紅筵絲竹合，用爾作歡娛。","直指寧偏黨，無私絕覬覦。","當歌誰擐袖，應節漸輕軀。","恰與真相似，氈裘滿頷鬚。"]', '["紅筵絲竹合，用爾作歡娛。","直指寧偏黨，無私絕覬覦。","當歌誰擐袖，應節漸轻軀。","恰與真相似，氈裘满頷鬚。"]', '诗', 'shi', '', NULL, '酒胡子 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fec543b2-3d60-4320-8d03-77de98b03e2d', '弔崔補闕', '弔崔補闕', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["近來吾道少，慟哭博陵君。","直節岩前竹，孤魂嶺上雲。","縉紳傳確論，丞相取遺文。","廢却中興策，何由免用軍。"]', '["近来吾道少，慟哭博陵君。","直節岩前竹，孤魂嶺上云。","縉紳傳確論，丞相取遺文。","廢却中兴策，何由免用軍。"]', '诗', 'shi', '', NULL, '弔崔補闕 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41dd5cd0-5d24-41ab-ab52-2347d83815de', '弔赤水李先生', '弔赤水李先生', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["三年悲過隙，一室類銷冰。","妻病入仙觀，子窮隨嶽僧。","荒丘寒有雨，古屋夜無燈。","往日清猷著，金門幾欲徴。"]', '["三年悲過隙，一室類銷冰。","妻病入仙观，子窮隨嶽僧。","荒丘寒有雨，古屋夜無灯。","往日清猷著，金门幾欲徴。"]', '诗', 'shi', '', NULL, '弔赤水李先生 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b9e31e1-ffdf-4d1f-a224-7dade1853269', '香鴨', '香鴨', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["不假陶鎔妙，誰教羽翼全。","五金池畔質，百和口中煙。","觜鈍魚難啄，心空火自燃。","御爐如有闕，須進聖君前。"]', '["不假陶鎔妙，誰教羽翼全。","五金池畔質，百和口中煙。","觜鈍鱼难啄，心空火自燃。","御爐如有闕，須進聖君前。"]', '诗', 'shi', '', NULL, '香鴨 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62757e20-77f4-45aa-a9cf-064fd4d74d12', '雞', '雞', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["名參十二屬，花入羽毛深。","守信催朝日，能鳴送曉陰。","峨冠裝瑞璧，利爪削黃金。","徒有稻粱感，何由報德音。"]', '["名參十二屬，花入羽毛深。","守信催朝日，能鳴送晓陰。","峨冠裝瑞璧，利爪削黄金。","徒有稻粱感，何由報德音。"]', '诗', 'shi', '', NULL, '雞 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ef5c26c-117a-46be-8d8b-2dc0c5301f23', '白鴿', '白鴿', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["舉翼凌空碧，依人到大邦。","粉翎棲畫閣，雪影拂瓊窗。","振鷺堪爲侶，鳴鳩好作雙。","狎鷗歸未得，覩爾憶晴江。"]', '["舉翼凌空碧，依人到大邦。","粉翎棲畫閣，雪影拂瓊窗。","振鷺堪爲侶，鳴鳩好作雙。","狎鷗归未得，覩爾憶晴江。"]', '诗', 'shi', '', NULL, '白鴿 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ecf2229-6fdb-4cea-b397-a7bd615c54f3', '龜', '龟', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["行止竟何從，深溪與古峰。","青荷巢瑞質，綠水返靈蹤。","鑽骨神明應，酬恩感激重。","仙翁求一卦，何日脫龍鍾。"]', '["行止竟何從，深溪與古峰。","青荷巢瑞質，綠水返靈蹤。","鑽骨神明應，酬恩感激重。","仙翁求一卦，何日脫龙鍾。"]', '诗', 'shi', '', NULL, '龜 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a054c031-bdb2-4549-86b0-c4375eafb881', '銀結條冠子', '銀結條冠子', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["日下徴良匠，宮中贈阿嬌。","瑞蓮開二孕，瓊縷織千條。","蟬翼輕輕結，花紋細細挑。","舞時紅袖舉，纖影透龍綃。"]', '["日下徴良匠，宮中贈阿嬌。","瑞蓮开二孕，瓊縷织千條。","蟬翼轻轻結，花紋細細挑。","舞时紅袖舉，纖影透龙綃。"]', '诗', 'shi', '', NULL, '銀結條冠子 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b13e5a3-6261-40fe-8fff-50764879e239', '蜀葵', '蜀葵', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["劍門南面樹，移向會仙亭。","錦水饒花豔，岷山帶葉青。","文君慚婉娩，神女讓娉婷。","爛熳紅兼紫，飄香入繡扃。"]', '["劍门南面樹，移向會仙亭。","錦水饒花豔，岷山带葉青。","文君慚婉娩，神女讓娉婷。","爛熳紅兼紫，飄香入繡扃。"]', '诗', 'shi', '', NULL, '蜀葵 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98104dd7-8787-45c8-a4ca-88656ef9830e', '華清宮', '华清宮', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["十二瓊樓鏁翠微，暮霞遺却六銖衣。","桐枯丹穴鳳何去，天在鼎湖龍不歸。","簾影罷添新翡翠，露華猶濕舊珠璣。","君王魂斷驪山路，且向蓬瀛伴貴妃。"]', '["十二瓊楼鏁翠微，暮霞遺却六銖衣。","桐枯丹穴鳳何去，天在鼎湖龙不归。","簾影罷添新翡翠，露华猶濕旧珠璣。","君王魂斷驪山路，且向蓬瀛伴貴妃。"]', '诗', 'shi', '', NULL, '華清宮 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05031d69-94f5-45f2-84f4-980631175f14', '再幸華清宮', '再幸华清宮', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["腸斷將軍改葬歸，錦囊香在憶當時。","年來却恨相思樹，春至不生連理枝。","雪女塚頭瑤草合，貴妃池裏玉蓮衰。","霓裳舊曲飛霜殿，夢破魂驚絕後期。"]', '["腸斷將軍改葬归，錦囊香在憶當时。","年来却恨相思樹，春至不生連理枝。","雪女塚头瑤草合，貴妃池裏玉蓮衰。","霓裳旧曲飞霜殿，梦破魂驚絕後期。"]', '诗', 'shi', '', NULL, '再幸華清宮 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8242bb00-b796-4c7c-b315-3d45d09f693e', '喜雨上主人尚書', '喜雨上主人尚书', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["天皇攘袂勅神龍，雨我公田兆歲豐。","幾日淋漓侵暮角，數宵滂沛徹晨鐘。","細如春霧籠平野，猛似秋風擊古松。","門下十年耕稼者，坐來偏憶翠微峰。"]', '["天皇攘袂勅神龙，雨我公田兆歲豐。","幾日淋漓侵暮角，數宵滂沛徹晨鐘。","細如春霧籠平野，猛似秋风擊古松。","门下十年耕稼者，坐来偏憶翠微峰。"]', '诗', 'shi', '', NULL, '喜雨上主人尚書 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f2f7caf-a80a-4c0b-ab39-2868e1588744', '迴文詩二首 一', '迴文诗二首 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["飛書一幅錦文迴，恨寫深情寄雁來。","機上月殘香閣掩，樹梢煙澹綠窗開。","霏霏雨罷歌終曲，漠漠雲深酒滿杯。","歸日幾人行問卜，徽音想望倚高臺。"]', '["飞书一幅錦文迴，恨寫深情寄雁来。","機上月殘香閣掩，樹梢煙澹綠窗开。","霏霏雨罷歌終曲，漠漠云深酒满杯。","归日幾人行问卜，徽音想望倚高台。"]', '诗', 'shi', '', NULL, '迴文詩二首 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4af306ac-3e8d-41cc-9330-bddb0014b037', '迴文詩二首 二', '迴文诗二首 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["輕帆數點千峰碧，水接雲山四望遙。","晴日海霞紅靄靄，曉天江樹綠迢迢。","清波石眼泉當檻，小逕松門寺對橋。","明月釣舟漁浦遠，傾山雪浪暗隨潮。"]', '["轻帆數点千峰碧，水接云山四望遙。","晴日海霞紅靄靄，晓天江樹綠迢迢。","清波石眼泉當檻，小逕松门寺对橋。","明月釣舟漁浦远，傾山雪浪暗隨潮。"]', '诗', 'shi', '', NULL, '迴文詩二首 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45973894-37c7-482d-bd77-fe0d6acbcc8b', '不把漁竿', '不把漁竿', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["不把漁竿不灌園，策筇吟遶綠蕪村。","得爭野老眠雲樂，倍感閩王與善恩。","鳥趂竹風穿靜戶，魚吹煙浪噴晴軒。","何人買我安貧趣，百萬黃金未可論。"]', '["不把漁竿不灌园，策筇吟遶綠蕪村。","得爭野老眠云乐，倍感閩王與善恩。","鸟趂竹风穿静戶，鱼吹煙浪噴晴軒。","何人買我安貧趣，百万黄金未可論。"]', '诗', 'shi', '', NULL, '不把漁竿 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('644d737d-d86a-4910-82ed-711ac4e320fa', '古往今來', '古往今来', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["古往今來恨莫窮，不如沈醉臥春風。","雀兒無角長穿屋，鸚鵡能言却入籠。","柳惠豈嫌居下位，朱雲直去指三公。","閑思郭令長安宅，草沒匡墻舊事空。"]', '["古往今来恨莫窮，不如沈醉臥春风。","雀兒無角长穿屋，鸚鵡能言却入籠。","柳惠豈嫌居下位，朱云直去指三公。","闲思郭令长安宅，草沒匡墻旧事空。"]', '诗', 'shi', '', NULL, '古往今來 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6287161e-894e-467e-8c05-f10638015b63', '十里煙籠', '十里煙籠', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["十里煙籠一徑分，故人迢遰久離羣。","白雲明月皆由我，碧水青山忽贈君。","浮世宦名渾似夢，半生勤苦謾爲文。","北邙坡上青松下，盡是鏘金佩玉墳。"]', '["十里煙籠一徑分，故人迢遰久離羣。","白云明月皆由我，碧水青山忽贈君。","浮世宦名渾似梦，半生勤苦謾爲文。","北邙坡上青松下，尽是鏘金佩玉墳。"]', '诗', 'shi', '', NULL, '十里煙籠 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d44504aa-9b95-47ab-abd7-4e34bcfdb960', '偶書', '偶书', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["巧者多爲拙者資，良籌第一在乘時。","市門逐利終身飽，谷口躬耕盡日飢。","瓊玖鬻來燕石貴，蓬蒿芳處楚蘭衰。","高皇冷笑重瞳客，蓋世拔山何所爲。"]', '["巧者多爲拙者資，良籌第一在乘时。","市门逐利終身飽，谷口躬耕尽日飢。","瓊玖鬻来燕石貴，蓬蒿芳处楚蘭衰。","高皇冷笑重瞳客，蓋世拔山何所爲。"]', '诗', 'shi', '', NULL, '偶書 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b18cc864-0b55-4667-b561-4b3562848a2b', '潤屋', '潤屋', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["潤屋豐家莫妄求，眼看多是與身讐。","百禽羅得皆黃口，四皓山居始白頭。","玉爍火光爭肯變，草芳崎岸不曾秋。","朱門粉署何由到，空寄新詩謝列侯。"]', '["潤屋豐家莫妄求，眼看多是與身讐。","百禽羅得皆黄口，四皓山居始白头。","玉爍火光爭肯变，草芳崎岸不曾秋。","朱门粉署何由到，空寄新诗謝列侯。"]', '诗', 'shi', '', NULL, '潤屋 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee8e72dd-8806-430e-a6e2-9719df03b6e3', '退居', '退居', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["鶴性松心合在山，五侯門館怯趨攀。","三年臥病不能免，一日受恩方得還。","明月送人沿驛路，白雲隨馬入柴關。","笑他范蠡貪惏甚，相罷金多始退閑。"]', '["鹤性松心合在山，五侯门館怯趨攀。","三年臥病不能免，一日受恩方得還。","明月送人沿驛路，白云隨马入柴关。","笑他范蠡貪惏甚，相罷金多始退闲。"]', '诗', 'shi', '', NULL, '退居 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54f76d2e-8f87-4269-92cb-f11508cc5997', '閉門', '閉门', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["閉却閑門臥小窗，更何人與療膏肓。","一生有酒唯知醉，四大無根可預量。","骨冷欲針先覺痛，肉頑頻炙不成瘡。","漳濱伏枕文園渴，盜跖縱橫似虎狼。"]', '["閉却闲门臥小窗，更何人與療膏肓。","一生有酒唯知醉，四大無根可預量。","骨冷欲針先覺痛，肉頑頻炙不成瘡。","漳濱伏枕文园渴，盜跖縱橫似虎狼。"]', '诗', 'shi', '', NULL, '閉門 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63502b6a-b135-4110-a8fb-e67fd2356f40', '開窗', '开窗', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["閉戶開窗寢又興，三更時節也如冰。","長閑便是忘機者，不出真如過夏僧。","環堵豈慚蝸作舍，布衣寧假鶴爲翎。","薔薇花盡薰風起，綠葉空隨滿架藤。"]', '["閉戶开窗寢又兴，三更时節也如冰。","长闲便是忘機者，不出真如過夏僧。","环堵豈慚蝸作舍，布衣寧假鹤爲翎。","薔薇花尽薰风起，綠葉空隨满架藤。"]', '诗', 'shi', '', NULL, '開窗 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c78d94c-bc77-4be5-8970-3e18623e4606', '燈花', '灯花', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["點蠟燒銀却勝栽，九華紅豔吐玫瑰。","獨含冬夜寒光拆，不傍春風暖處開。","難見只因能送喜，莫挑唯恐墮成灰。","貪膏附熱多相誤，爲報飛蛾罷拂來。"]', '["点蠟燒銀却勝栽，九华紅豔吐玫瑰。","独含冬夜寒光拆，不傍春风暖处开。","难见只因能送喜，莫挑唯恐墮成灰。","貪膏附熱多相誤，爲報飞蛾罷拂来。"]', '诗', 'shi', '', NULL, '燈花 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22a67fd5-f3b8-4f85-a762-bad65224ec45', '東歸出城留別知己', '东归出城留別知己', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["韋蒙屈指許非才，三載長安共酒桮。","欲別未攀楊柳贈，相留擬待牡丹開。","寒隨御水波光散，暖逐衡陽雁影來。","他日因書問衰颯，東溪須訪子陵臺。"]', '["韋蒙屈指許非才，三載长安共酒桮。","欲別未攀楊柳贈，相留擬待牡丹开。","寒隨御水波光散，暖逐衡陽雁影来。","他日因书问衰颯，东溪須訪子陵台。"]', '诗', 'shi', '', NULL, '東歸出城留別知己 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fd43683-676f-4414-8024-c355536fbedf', '詠懷', '詠懷', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["愁花變出白髭鬚，半世辛勤一事無。","道在或期君夢想，貧來爭奈鬼揶揄。","馬卿自愧長嬰疾，顏子誰憐不是愚。","借取秦宮臺上鏡，爲時開照漢妖狐。"]', '["愁花变出白髭鬚，半世辛勤一事無。","道在或期君梦想，貧来爭奈鬼揶揄。","马卿自愧长嬰疾，顏子誰怜不是愚。","借取秦宮台上镜，爲时开照漢妖狐。"]', '诗', 'shi', '', NULL, '詠懷 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae4776cb-0cb8-4a59-bad7-7a8aefac04bb', '郊村獨遊', '郊村独游', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["歲閏堪憐曆候遲，出門惟與野雲期。","驚魚擲上綠荷芰，棲鳥啄餘紅荔枝。","末路可能長薄命，修途應合有良時。","市頭相者休相戲，蹙膝先生半自知。"]', '["歲閏堪怜曆候遲，出门惟與野云期。","驚鱼擲上綠荷芰，棲鸟啄餘紅荔枝。","末路可能长薄命，修途應合有良时。","市头相者休相戲，蹙膝先生半自知。"]', '诗', 'shi', '', NULL, '郊村獨遊 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ba25404-349f-4d70-9525-2f77dfbb34af', '經故翰林楊左丞池亭', '經故翰林楊左丞池亭', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["八角紅亭蔭綠池，一朝青草蓋遺基。","薔薇藤老開花淺，翡翠巢空落羽奇。","春榜幾深門下客，樂章多取集中詩。","平生德義人間誦，身後何勞更立碑。"]', '["八角紅亭蔭綠池，一朝青草蓋遺基。","薔薇藤老开花淺，翡翠巢空落羽奇。","春榜幾深门下客，乐章多取集中诗。","平生德義人间誦，身後何勞更立碑。"]', '诗', 'shi', '', NULL, '經故翰林楊左丞池亭 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d5bf8b-816a-4da3-9e56-090971dc50a1', '經故廣平員外舊宅', '經故廣平員外旧宅', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["門巷蕭條引涕洟，遺孤三歲著麻衣。","綠楊樹老垂絲短，翠竹林荒著筍稀。","結社僧因秋朔弔，買書船近葬時歸。","平生欲獻匡君策，抱病猶言未息機。"]', '["门巷蕭條引涕洟，遺孤三歲著麻衣。","綠楊樹老垂絲短，翠竹林荒著筍稀。","結社僧因秋朔弔，買书船近葬时归。","平生欲獻匡君策，抱病猶言未息機。"]', '诗', 'shi', '', NULL, '經故廣平員外舊宅 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('848fdc67-9da0-410d-9f64-75fe24f8571d', '潘丞相舊宅', '潘丞相旧宅', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["綠樹垂枝蔭四鄰，春風還似舊時春。","年年燕是雕梁主，處處花隨落月塵。","七貴竟爲長逝客，五侯尋作不歸人。","秋槐影薄蟬聲盡，休謂龍門待化鱗。"]', '["綠樹垂枝蔭四鄰，春风還似旧时春。","年年燕是雕梁主，处处花隨落月塵。","七貴竟爲长逝客，五侯尋作不归人。","秋槐影薄蟬声尽，休謂龙门待化鱗。"]', '诗', 'shi', '', NULL, '潘丞相舊宅 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf0f1447-3bb9-4615-9c54-9d16d3d84dfe', '門外閑田數畝長有泉源因築直堤分爲兩沼', '门外闲田數畝长有泉源因築直堤分爲兩沼', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["左右澄漪小檻前，直堤高築古平川。","十分春水雙簷影，一片秋空兩月懸。","前岸好山搖細浪，夾門嘉樹合晴煙。","坐來暗起江湖思，速問溪翁買釣船。"]', '["左右澄漪小檻前，直堤高築古平川。","十分春水雙簷影，一片秋空兩月懸。","前岸好山搖細浪，夾门嘉樹合晴煙。","坐来暗起江湖思，速问溪翁買釣船。"]', '诗', 'shi', '', NULL, '門外閑田數畝長有泉源因築直堤分爲兩沼 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98db85c6-7dce-4fa1-ae00-515612996689', '北園', '北园', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["北園乾葉旋空枝，蘭蕙還將衆草衰。","籠鳥上天猶有待，病龍興雨豈無期。","身閑不厭頻來客，年老偏憐最小兒。","生事罷求名與利，一窗書策是年支。"]', '["北园乾葉旋空枝，蘭蕙還將衆草衰。","籠鸟上天猶有待，病龙兴雨豈無期。","身闲不厭頻来客，年老偏怜最小兒。","生事罷求名與利，一窗书策是年支。"]', '诗', 'shi', '', NULL, '北園 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a33915db-c40d-4db0-b8c7-5e466d286899', '溪上要一隻白簟扇蓋頭垂釣去年就節推侍御請之蒙惠一柄紫花紋者雖則鱗華具甚紕薄不及清源所出因就南郡陳常侍請之遂成拙句', '溪上要一隻白簟扇蓋头垂釣去年就節推侍御請之蒙惠一柄紫花紋者雖則鱗华具甚紕薄不及清源所出因就南郡陳常侍請之遂成拙句', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["難求珍箑過炎天，遠就金貂乞月圓。","直在引風欹角枕，且圖遮日上漁船。","但令織取無花簟，不用挑爲飲露蟬。","莫道如今時較晚，也應留得到明年。"]', '["难求珍箑過炎天，远就金貂乞月圓。","直在引风欹角枕，且圖遮日上漁船。","但令织取無花簟，不用挑爲饮露蟬。","莫道如今时較晚，也應留得到明年。"]', '诗', 'shi', '', NULL, '溪上要一隻白簟扇蓋頭垂釣去年就節推侍御請之蒙惠一柄紫花紋者雖則鱗華具甚紕薄不及清源所出因就南郡陳常侍請之遂成拙句 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c8dbcc7-39e8-42fb-9628-0a3effa2e4eb', '招隱', '招隐', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["齒髮那能敵歲華，早知休去避塵沙。","鬼神只闞高明里，倚伏不干棲隱家。","陶景豈全輕組綬，留侯非獨愛煙霞。","贈君吉語堪銘座，看取朝開暮落花。"]', '["齒髮那能敵歲华，早知休去避塵沙。","鬼神只闞高明里，倚伏不干棲隐家。","陶景豈全轻組綬，留侯非独愛煙霞。","贈君吉語堪銘座，看取朝开暮落花。"]', '诗', 'shi', '', NULL, '招隱 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36c90b34-7388-4ba4-b3f4-25081e74f014', '憶山中友人', '憶山中友人', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["憶得當年接善鄰，苦將閑事強夫君。","鬬開碧沼分明月，各領青山占白雲。","近日藥方多繕寫，舊來詩草半燒焚。","金門幾欲言西上，惆悵關河正用軍。"]', '["憶得當年接善鄰，苦將闲事強夫君。","鬬开碧沼分明月，各領青山占白云。","近日藥方多繕寫，旧来诗草半燒焚。","金门幾欲言西上，惆悵关河正用軍。"]', '诗', 'shi', '', NULL, '憶山中友人 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddab1b9c-d710-48a3-8307-e7b86ba18c4c', '溪隱', '溪隐', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["將名將利已無緣，深隱清溪擬學仙。","絕却腥羶勝服藥，斷除桮酒合延年。","蝸牛殼漏寧同舍，榆莢花開不是錢。","鸞鶴久從籠檻閉，春風却放紙爲鳶。"]', '["將名將利已無緣，深隐清溪擬学仙。","絕却腥羶勝服藥，斷除桮酒合延年。","蝸牛殼漏寧同舍，榆莢花开不是錢。","鸾鹤久從籠檻閉，春风却放紙爲鳶。"]', '诗', 'shi', '', NULL, '溪隱 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbfd76de-eb93-43f6-a461-2a4742d996ae', '酒醒', '酒醒', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["酒醒欲得適閑情，騎馬那勝策杖行。","天暖天寒三月暮，溪南溪北兩村名。","沙澄淺水魚知釣，花落平田鶴見耕。","望斷長安故交遠，來書未說九河清。"]', '["酒醒欲得適闲情，騎马那勝策杖行。","天暖天寒三月暮，溪南溪北兩村名。","沙澄淺水鱼知釣，花落平田鹤见耕。","望斷长安故交远，来书未说九河清。"]', '诗', 'shi', '', NULL, '酒醒 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e679b661-fc40-4f60-9b3e-27b35ca8435d', '夢斷', '梦斷', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["夢斷紗窗半夜雷，別君花落又花開。","漁陽路遠書難寄，衡嶽山高月不來。","玄燕有情穿繡戶，靈龜無應祝金杯。","人生若得長相對，螢火生煙草化灰。"]', '["梦斷紗窗半夜雷，別君花落又花开。","漁陽路远书难寄，衡嶽山高月不来。","玄燕有情穿繡戶，靈龟無應祝金杯。","人生若得长相对，螢火生煙草化灰。"]', '诗', 'shi', '', NULL, '夢斷 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9e317fc-4dd6-4078-94ca-d1c3446be8f6', '人事', '人事', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["人事飄如一炷煙，且須求佛與求仙。","豐年甲子春無雨，良夜庚申夏足眠。","顏氏豈嫌瓢裏飲，孟光非取鏡中妍。","平生生計何爲者，三逕蒼苔十畝田。"]', '["人事飄如一炷煙，且須求佛與求仙。","豐年甲子春無雨，良夜庚申夏足眠。","顏氏豈嫌瓢裏饮，孟光非取镜中妍。","平生生計何爲者，三逕蒼苔十畝田。"]', '诗', 'shi', '', NULL, '人事 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80b8e616-350e-4d40-a1bd-9a455b8da076', '休說', '休说', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["休說人間有陸沈，一樽閑待月明斟。","時來不怕滄溟闊，道大却憂潢潦深。","白首釣魚應是分，青雲干祿已無心。","梓桐賦罷相如隱，誰爲君前永夜吟。"]', '["休说人间有陸沈，一樽闲待月明斟。","时来不怕滄溟闊，道大却憂潢潦深。","白首釣鱼應是分，青云干祿已無心。","梓桐賦罷相如隐，誰爲君前永夜吟。"]', '诗', 'shi', '', NULL, '休說 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc19bbc5-840c-40d0-a2a9-a2344d442b4b', '嘉運', '嘉運', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["嘉運良時兩阻修，釣竿簑笠樂林丘。","家無寸帛渾閑事，身似浮雲且自由。","庭際鳥啼花旋落，潭心月在水空流。","晨炊一箸紅銀粒，憶著長安索米秋。"]', '["嘉運良时兩阻修，釣竿簑笠乐林丘。","家無寸帛渾闲事，身似浮云且自由。","庭際鸟啼花旋落，潭心月在水空流。","晨炊一箸紅銀粒，憶著长安索米秋。"]', '诗', 'shi', '', NULL, '嘉運 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53924571-55d4-4f7a-ad55-0612145d85ca', '綠鬢', '綠鬢', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["綠鬢先生自出林，孟光同樂野雲深。","躬耕爲食古人操，非織不衣賢者心。","眼衆豈能分瑞璧，舌多須信爍良金。","君看黃閣南遷客，一過瀧州絕好音。"]', '["綠鬢先生自出林，孟光同乐野云深。","躬耕爲食古人操，非织不衣賢者心。","眼衆豈能分瑞璧，舌多須信爍良金。","君看黄閣南遷客，一過瀧州絕好音。"]', '诗', 'shi', '', NULL, '綠鬢 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf523960-aab4-4bfd-bfee-69b38ed9ebab', '驕侈', '驕侈', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["驕侈阽危儉素牢，鏡中形影豈能逃。","石家恃富身還滅，顏子非貧道不遭。","蝙蝠亦能知日月，鸞鳳那肯啄腥臊。","古今人事惟堪醉，好脫霜裘換綠醪。"]', '["驕侈阽危儉素牢，镜中形影豈能逃。","石家恃富身還滅，顏子非貧道不遭。","蝙蝠亦能知日月，鸾鳳那肯啄腥臊。","古今人事惟堪醉，好脫霜裘換綠醪。"]', '诗', 'shi', '', NULL, '驕侈 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77f3889c-87a0-4696-aa7c-27fb20302718', '龍蟄二首 一', '龙蟄二首 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["龍蟄蛇蟠却待伸，和光何惜且同塵。","伍員豈是吹簫者，冀缺非同執耒人。","神劍觸星當變化，良金成器在陶鈞。","穰侯休忌關東客，張祿先生竟相秦。"]', '["龙蟄蛇蟠却待伸，和光何惜且同塵。","伍員豈是吹簫者，冀缺非同執耒人。","神劍觸星當变化，良金成器在陶鈞。","穰侯休忌关东客，張祿先生竟相秦。"]', '诗', 'shi', '', NULL, '龍蟄二首 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e17507c-69f5-4245-ba92-fa6b94f27061', '龍蟄二首 二', '龙蟄二首 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["休說雄才間代生，到頭難與運相爭。","時通有詔徵枚乘，世亂無人薦禰衡。","逐日莫矜駑馬步，司晨誰要牝雞鳴。","中林且作煙霞侶，塵滿關河未可行。"]', '["休说雄才间代生，到头难與運相爭。","时通有詔徵枚乘，世亂無人薦禰衡。","逐日莫矜駑马步，司晨誰要牝雞鳴。","中林且作煙霞侶，塵满关河未可行。"]', '诗', 'shi', '', NULL, '龍蟄二首 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ace23fcc-74dc-438a-a1c6-259fcf745bd2', '逐臭蒼蠅', '逐臭蒼蠅', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["逐臭蒼蠅豈有爲，清蟬吟露最高奇。","多藏苟得何名富，飽食嗟來未勝飢。","窮寂不妨延壽考，貪狂總待算毫釐。","首陽山翠千年在，好奠冰壺弔伯夷。"]', '["逐臭蒼蠅豈有爲，清蟬吟露最高奇。","多藏苟得何名富，飽食嗟来未勝飢。","窮寂不妨延壽考，貪狂總待算毫釐。","首陽山翠千年在，好奠冰壺弔伯夷。"]', '诗', 'shi', '', NULL, '逐臭蒼蠅 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30a32dfc-174c-42a5-8063-b6b6cd16f389', '牡丹花二首 一', '牡丹花二首 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["看徧花無勝此花，翦雲披雪蘸丹砂。","開當青律二三月，破却長安千萬家。","天縱穠華刳鄙吝，春教妖豔毒豪奢。","不隨寒令同時放，倍種雙松與辟邪。"]', '["看徧花無勝此花，翦云披雪蘸丹砂。","开當青律二三月，破却长安千万家。","天縱穠华刳鄙吝，春教妖豔毒豪奢。","不隨寒令同时放，倍種雙松與辟邪。"]', '诗', 'shi', '', NULL, '牡丹花二首 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09215f0d-4ce9-4b2f-8be9-b6c9f63816f4', '牡丹花二首 二', '牡丹花二首 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["萬萬花中第一流，淺霞輕染嫩銀甌。","能狂綺陌千金子，也惑朱門萬戶侯。","朝日照開攜酒看，暮風吹落遶欄收。","詩書滿架塵埃撲，盡日無人畧舉頭。"]', '["万万花中第一流，淺霞轻染嫩銀甌。","能狂綺陌千金子，也惑朱门万戶侯。","朝日照开携酒看，暮风吹落遶欄收。","诗书满架塵埃撲，尽日無人畧舉头。"]', '诗', 'shi', '', NULL, '牡丹花二首 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b622df6-8c0d-4e75-81c6-4b53f3175d76', '尚書座上賦牡丹花得輕字韻其花自越中移植', '尚书座上賦牡丹花得轻字韻其花自越中移植', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["流蘇凝作瑞華精，仙閣開時麗日晴。","霜月冷銷銀燭焰，寶甌圓印綵雲英。","嬌含嫩臉春妝薄，紅蘸香綃豔色輕。","早晚有人天上去，寄他將贈董雙成。"]', '["流蘇凝作瑞华精，仙閣开时丽日晴。","霜月冷銷銀燭焰，寶甌圓印綵云英。","嬌含嫩臉春妝薄，紅蘸香綃豔色轻。","早晚有人天上去，寄他將贈董雙成。"]', '诗', 'shi', '', NULL, '尚書座上賦牡丹花得輕字韻其花自越中移植 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d864cd0-5723-4c05-8aca-2f41e09d5528', '依韻和尚書再贈牡丹花', '依韻和尚书再贈牡丹花', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["爛銀基地薄紅妝，羞殺千花百卉芳。","紫陌昔曾遊寺看，朱門今在遶欄望。","龍分夜雨資嬌態，天與春風發好香。","多著黃金何處買，輕橈挑過鏡湖光。"]', '["爛銀基地薄紅妝，羞殺千花百卉芳。","紫陌昔曾游寺看，朱门今在遶欄望。","龙分夜雨資嬌態，天與春风發好香。","多著黄金何处買，轻橈挑過镜湖光。"]', '诗', 'shi', '', NULL, '依韻和尚書再贈牡丹花 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0e7f319-5a64-462b-9c5c-d5bfd9a64815', '郡庭惜牡丹', '郡庭惜牡丹', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["腸斷東風落牡丹，爲祥爲瑞久留難。","青春不駐堪垂淚，紅豔已空猶倚欄。","積蘚下銷香蘂盡，晴陽高照露華乾。","明年萬葉千枝長，倍發芳菲借客看。"]', '["腸斷东风落牡丹，爲祥爲瑞久留难。","青春不駐堪垂泪，紅豔已空猶倚欄。","積蘚下銷香蘂尽，晴陽高照露华乾。","明年万葉千枝长，倍發芳菲借客看。"]', '诗', 'shi', '', NULL, '郡庭惜牡丹 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7e1f3d0-96a1-4e49-947b-a21cfbd49c25', '追和白舍人詠白牡丹', '追和白舍人詠白牡丹', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["蓓蕾抽開素練囊，瓊葩薰出白龍香。","裁分楚女朝雲片，翦破姮娥夜月光。","雪句豈須徴柳絮，粉腮應恨帖梅妝。","檻邊幾笑東籬菊，冷折金風待降霜。"]', '["蓓蕾抽开素練囊，瓊葩薰出白龙香。","裁分楚女朝云片，翦破姮娥夜月光。","雪句豈須徴柳絮，粉腮應恨帖梅妝。","檻邊幾笑东籬菊，冷折金风待降霜。"]', '诗', 'shi', '', NULL, '追和白舍人詠白牡丹 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb7908b9-a0c4-4c31-9441-25276bdbcabc', '憶牡丹', '憶牡丹', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["綠樹多和雪霰栽，長安一別十年來。","王侯買得價偏重，桃李落殘花始開。","宋玉鄰邊腮正嫩，文君機上錦初裁。","滄洲春暮空腸斷，畫看猶將勸酒杯。"]', '["綠樹多和雪霰栽，长安一別十年来。","王侯買得價偏重，桃李落殘花始开。","宋玉鄰邊腮正嫩，文君機上錦初裁。","滄洲春暮空腸斷，畫看猶將勸酒杯。"]', '诗', 'shi', '', NULL, '憶牡丹 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e400182d-2270-4b83-9724-d51906a96a0c', '惜牡丹', '惜牡丹', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["今日狂風揭錦筵，預愁吹落夕陽天。","閑看紅豔只須醉，謾惜黃金豈是賢。","南國好偷誇粉黛，漢宮宜摘贈神仙。","良時雖作鶯花主，白馬王孫恰少年。"]', '["今日狂风揭錦筵，預愁吹落夕陽天。","闲看紅豔只須醉，謾惜黄金豈是賢。","南国好偷誇粉黛，漢宮宜摘贈神仙。","良时雖作鶯花主，白马王孫恰少年。"]', '诗', 'shi', '', NULL, '惜牡丹 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7612d5ee-f82c-47dc-a27f-811c9615a202', '覽柳渾汀洲採白蘋之什因成一章', '覽柳渾汀洲採白蘋之什因成一章', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["採盡汀蘋恨別離，鴛鴦鸂鶒總雙飛。","月明南浦夢初斷，花落洞庭人未歸。","天遠有書隨驛使，夜長無燭照寒機。","年來泣淚知多少，重疊成痕在繡衣。"]', '["採尽汀蘋恨別離，鴛鴦鸂鶒總雙飞。","月明南浦梦初斷，花落洞庭人未归。","天远有书隨驛使，夜长無燭照寒機。","年来泣泪知多少，重叠成痕在繡衣。"]', '诗', 'shi', '', NULL, '覽柳渾汀洲採白蘋之什因成一章 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9913526a-c1e9-40c1-a2c5-a28adcf0193d', '司直巡官無諸移到玫瑰花', '司直巡官無諸移到玫瑰花', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["芳菲移自越王臺，最似薔薇好並栽。","穠豔盡憐勝綵繪，嘉名誰贈作玫瑰。","春藏錦繡風吹拆，天染瓊瑤日照開。","爲報朱衣早邀客，莫教零落委蒼苔。"]', '["芳菲移自越王台，最似薔薇好並栽。","穠豔尽怜勝綵繪，嘉名誰贈作玫瑰。","春藏錦繡风吹拆，天染瓊瑤日照开。","爲報朱衣早邀客，莫教零落委蒼苔。"]', '诗', 'shi', '', NULL, '司直巡官無諸移到玫瑰花 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8d4604c-d4e4-4dc7-90dd-bcc65478d830', '梅花', '梅花', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["瓊瑤初綻嶺頭葩，蘂粉新妝姹女家。","舉世更誰憐潔白，癡心皆盡愛繁華。","玄冥借與三冬景，謝氏輸他六出花。","結實和羹知有日，肯隨羌笛落天涯。"]', '["瓊瑤初綻嶺头葩，蘂粉新妝姹女家。","舉世更誰怜潔白，癡心皆尽愛繁华。","玄冥借與三冬景，謝氏輸他六出花。","結實和羹知有日，肯隨羌笛落天涯。"]', '诗', 'shi', '', NULL, '梅花 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e37b8b3-ff91-4dd3-9eb0-00aebb409500', '茘枝二首 一', '茘枝二首 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["朱彈星丸粲日光，綠瓊枝散小香囊。","龍綃殼綻紅紋粟，魚目珠涵白膜漿。","梅熟已過南嶺雨，橘酸空待洞庭霜。","蠻山蹋曉和煙摘，拜捧金盤奉越王。"]', '["朱彈星丸粲日光，綠瓊枝散小香囊。","龙綃殼綻紅紋粟，鱼目珠涵白膜漿。","梅熟已過南嶺雨，橘酸空待洞庭霜。","蠻山蹋晓和煙摘，拜捧金盤奉越王。"]', '诗', 'shi', '', NULL, '茘枝二首 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dee099f-fae2-4659-84ea-8f7ddc35de9f', '茘枝二首 二', '茘枝二首 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["日日薰風卷瘴煙，南園珍菓茘枝先。","靈鴉啄破瓊津滴，寶器盛來蚌腹圓。","錦里只聞銷醉客，蘂宮惟合贈神仙。","何人刺出[猩猩]血，深染羅紋遍殼鮮。"]', '["日日薰风卷瘴煙，南园珍菓茘枝先。","靈鴉啄破瓊津滴，寶器盛来蚌腹圓。","錦里只闻銷醉客，蘂宮惟合贈神仙。","何人刺出[猩猩]血，深染羅紋遍殼鲜。"]', '诗', 'shi', '', NULL, '茘枝二首 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35e41385-8a07-4dd9-88fa-39d625c3bf67', '菊花', '菊花', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["桓景登高事可尋，黃花開處綠畦深。","消災辟惡君須採，冷露寒霜我自禁。","籬物早榮還早謝，澗松同德復同心。","陶公豈是居貧者，剩有東籬萬朵金。"]', '["桓景登高事可尋，黄花开处綠畦深。","消災辟惡君須採，冷露寒霜我自禁。","籬物早榮還早謝，澗松同德复同心。","陶公豈是居貧者，剩有东籬万朵金。"]', '诗', 'shi', '', NULL, '菊花 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f32b206-fc43-488f-928a-d798e24d5eee', '畫松', '畫松', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["澗底陰森驗筆精，筆閑開展覺神清。","曾當月照還無影，若許風吹合有聲。","枝偃只應玄鶴識，根深且與茯苓生。","天台道士頻來見，說似株株倚赤城。"]', '["澗底陰森驗笔精，笔闲开展覺神清。","曾當月照還無影，若許风吹合有声。","枝偃只應玄鹤識，根深且與茯苓生。","天台道士頻来见，说似株株倚赤城。"]', '诗', 'shi', '', NULL, '畫松 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8fc13a0-c241-4751-9578-42a43d067f1b', '草木', '草木', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["草木無情亦可嗟，重開明鏡照無涯。","菊英空折羅含宅，榆莢不生原憲家。","天命豈憑醫藥石，世途還要辟蟲沙。","仙翁乞取金盤露，洗却蒼蒼兩鬢華。"]', '["草木無情亦可嗟，重开明镜照無涯。","菊英空折羅含宅，榆莢不生原憲家。","天命豈憑醫藥石，世途還要辟蟲沙。","仙翁乞取金盤露，洗却蒼蒼兩鬢华。"]', '诗', 'shi', '', NULL, '草木 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a52ffef2-aefd-4b5a-90c2-e072d81f9a12', '松', '松', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["澗底青松不染塵，未逢良匠競誰分。","龍盤勁節岩前見，鶴唳翠梢天上聞。","大廈可營誰擇木，女蘿相附欲凌雲。","皇王自有增封日，修竹徒勞號此君。"]', '["澗底青松不染塵，未逢良匠競誰分。","龙盤勁節岩前见，鹤唳翠梢天上闻。","大廈可營誰擇木，女蘿相附欲凌云。","皇王自有增封日，修竹徒勞號此君。"]', '诗', 'shi', '', NULL, '松 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12447b12-0cd6-4d51-9f99-02627b800ee4', '竹', '竹', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["翠染琅玕粉漸開，東南移得會稽栽。","游絲挂處漁竿去，綠水夾時龍影來。","風觸有聲含六律，露沾如洗絕浮埃。","王猷舊宅無人到，抱却清陰蓋綠苔。"]', '["翠染琅玕粉漸开，东南移得會稽栽。","游絲挂处漁竿去，綠水夾时龙影来。","风觸有声含六律，露沾如洗絕浮埃。","王猷旧宅無人到，抱却清陰蓋綠苔。"]', '诗', 'shi', '', NULL, '竹 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a4d219-f300-40c7-b487-51c387da70cd', '尚書打毬小驄步驟最奇因有所贈', '尚书打毬小驄步驟最奇因有所贈', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["善價千金未可論，燕王新寄小龍孫。","逐將白日馳青漢，銜得流星入畫門。","步驟最能隨手轉，性靈多恐會人言。","桃花雪點多雖貴，全假當場一顧恩。"]', '["善價千金未可論，燕王新寄小龙孫。","逐將白日驰青漢，銜得流星入畫门。","步驟最能隨手轉，性靈多恐會人言。","桃花雪点多雖貴，全假當場一顧恩。"]', '诗', 'shi', '', NULL, '尚書打毬小驄步驟最奇因有所贈 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84412caa-a379-46b3-b323-146d35f2a39a', '尚書惠蠟面茶', '尚书惠蠟面茶', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["武夷春暖月初圓，採摘新芽獻地仙。","飛鵲印成香蠟片，啼猿溪走木蘭船。","金槽和碾沈香末，冰椀輕涵翠縷煙。","分贈恩深知最異，晚鐺宜煮北山泉。"]', '["武夷春暖月初圓，採摘新芽獻地仙。","飞鵲印成香蠟片，啼猿溪走木蘭船。","金槽和碾沈香末，冰椀轻涵翠縷煙。","分贈恩深知最異，晚鐺宜煮北山泉。"]', '诗', 'shi', '', NULL, '尚書惠蠟面茶 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ed7af94-11ab-4363-9f99-47d25c0a2fbf', '勸酒', '勸酒', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["休向尊前愬羽觥，百壺清酌與君傾。","身同綠樹年年老，事比紅塵日日生。","六國英雄徒反覆，九原松柏甚分明。","醉鄉路與乾坤隔，豈信人間有利名。"]', '["休向尊前愬羽觥，百壺清酌與君傾。","身同綠樹年年老，事比紅塵日日生。","六国英雄徒反覆，九原松柏甚分明。","醉乡路與乾坤隔，豈信人间有利名。"]', '诗', 'shi', '', NULL, '勸酒 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c7fd124-e276-4fdd-9473-edbdcbfcd11a', '斷酒', '斷酒', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["因論沈湎覺前非，便碎金罍與羽巵。","採茗早馳三蜀使，看花甘負五侯期。","窗間近火劉伶傳，坐右新銘管仲辭。","此事十年前已說，匡廬山下老僧知。"]', '["因論沈湎覺前非，便碎金罍與羽巵。","採茗早驰三蜀使，看花甘負五侯期。","窗间近火劉伶傳，坐右新銘管仲辞。","此事十年前已说，匡廬山下老僧知。"]', '诗', 'shi', '', NULL, '斷酒 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e22e9fb-2113-4f57-adf5-8bc9d6e7c77f', '憶舊山', '憶旧山', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["澗竹岩雲有舊期，二年頻長鬢邊絲。","遊魚不愛金桮水，棲鳥敢求瓊樹枝。","陶景戀深松檜影，留侯拋却帝王師。","龍爭虎攫皆閑事，數疊山光在夢思。"]', '["澗竹岩云有旧期，二年頻长鬢邊絲。","游鱼不愛金桮水，棲鸟敢求瓊樹枝。","陶景戀深松檜影，留侯拋却帝王師。","龙爭虎攫皆闲事，數叠山光在梦思。"]', '诗', 'shi', '', NULL, '憶舊山 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38d28ed7-484f-4b2c-89d1-06f7ca6c0037', '西華', '西华', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["五千仞有餘神秀，一一排雲上泬㵳。","疊嶂出關分二陝，殘岡過水作中條。","巨靈廟破生春草，毛女峰高入絳[霄]。","拜祝金天乞陰德，爲民求主降神堯。"]', '["五千仞有餘神秀，一一排云上泬㵳。","叠嶂出关分二陝，殘岡過水作中條。","巨靈廟破生春草，毛女峰高入絳[霄]。","拜祝金天乞陰德，爲民求主降神堯。"]', '诗', 'shi', '', NULL, '西華 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e1020a6-b044-4bed-8073-5a12547bcdf0', '嵐似屏風', '嵐似屏风', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["嵐似屏風草似茵，草邊時膾錦花鱗。","山中宰相陶弘景，谷口耕夫鄭子真。","宦達到頭思野逸，才多未必笑清貧。","君看東洛平泉宅，只有年年百卉春。"]', '["嵐似屏风草似茵，草邊时膾錦花鱗。","山中宰相陶弘景，谷口耕夫鄭子真。","宦達到头思野逸，才多未必笑清貧。","君看东洛平泉宅，只有年年百卉春。"]', '诗', 'shi', '', NULL, '嵐似屏風 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('804553f3-65d9-4b1d-85c1-63a3f8c7ac78', '憶潼關', '憶潼关', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["洞壑雙扉入到初，似從深穽覩高墟。","天開白日臨軍國，山夾黃河護帝居。","隋煬遠遊宜不反，奉春長策竟何如。","須知皇漢能扃鐍，延得年過四百餘。"]', '["洞壑雙扉入到初，似從深穽覩高墟。","天开白日臨軍国，山夾黄河護帝居。","隋煬远游宜不反，奉春长策竟何如。","須知皇漢能扃鐍，延得年過四百餘。"]', '诗', 'shi', '', NULL, '憶潼關 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('435e32de-910b-41c1-a27e-e6c964eced61', '憶潼關早行', '憶潼关早行', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["行客起看仙掌月，落星斜照濁河泥。","故山遠處高飛雁，去馬鳴時先早雞。","關柳不知誰氏種，岳碑猶見聖君題。","蒭蕘十軸僮三尺，豈謂青雲便有梯。"]', '["行客起看仙掌月，落星斜照濁河泥。","故山远处高飞雁，去马鳴时先早雞。","关柳不知誰氏種，岳碑猶见聖君題。","蒭蕘十軸僮三尺，豈謂青云便有梯。"]', '诗', 'shi', '', NULL, '憶潼關早行 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('901a1f29-906e-4ac3-a8e2-6fe76c973c3a', '鴻門', '鴻门', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["耨月耕煙水國春，薄徒應笑作農人。","皇王尚法三推禮，白社寧忘四體勤。","雨灑簑衣芳草暗，鳥啼雲樹小村貧。","猶勝墮力求飧者，五斗低腰走世塵。"]', '["耨月耕煙水国春，薄徒應笑作農人。","皇王尚法三推禮，白社寧忘四體勤。","雨灑簑衣芳草暗，鸟啼云樹小村貧。","猶勝墮力求飧者，五斗低腰走世塵。"]', '诗', 'shi', '', NULL, '鴻門 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('487ebdc1-cb5b-4327-8ecc-8b38ae3252f2', '憶長安行', '憶长安行', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["舊歷關中憶廢興，僭奢須戒儉須憑。","火光只是燒秦冢，賊眼何曾視灞陵。","鐘鼓煎催人自急，侯王更換恨難勝。","不如坐釣清溪月，心共寒潭一片澄。"]', '["旧歷关中憶廢兴，僭奢須戒儉須憑。","火光只是燒秦冢，賊眼何曾視灞陵。","鐘鼓煎催人自急，侯王更換恨难勝。","不如坐釣清溪月，心共寒潭一片澄。"]', '诗', 'shi', '', NULL, '憶長安行 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9188b860-b609-4232-a350-324ace45bbc2', '憶長安上省年', '憶长安上省年', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["忽憶關中逐計車，歷坊騎馬信空虛。","三秋病起見新鴈，八月夜長思舊居。","宗伯帳前曾獻賦，相君門下再投書。","如今說著猶堪泣，兩宿都堂過歲除。"]', '["忽憶关中逐計车，歷坊騎马信空虛。","三秋病起见新鴈，八月夜长思旧居。","宗伯帳前曾獻賦，相君门下再投书。","如今说著猶堪泣，兩宿都堂過歲除。"]', '诗', 'shi', '', NULL, '憶長安上省年 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('637289d5-aa1e-4c13-972a-a41f128c8d54', '長安述懷', '长安述懷', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["黃河冰合尚來遊，知命知時肯躁求。","詞賦有名堪自負，春風落第不曾羞。","風塵色裏凋雙鬢，[鼙]鼓聲中歷幾州。","十載公卿早言屈，何須課夏更冥搜。"]', '["黄河冰合尚来游，知命知时肯躁求。","词賦有名堪自負，春风落第不曾羞。","风塵色裏凋雙鬢，[鼙]鼓声中歷幾州。","十載公卿早言屈，何須課夏更冥搜。"]', '诗', 'shi', '', NULL, '長安述懷 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('045cee6c-a56b-4340-b251-984ed0c5cdb4', '長安即事三首 一', '长安即事三首 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["拋擲清溪舊釣鉤，長安寒暑再環周。","便隨鶯羽三春化，只說蟬聲一度愁。","掃雪自憐窗紙照，上天寧愧海槎流。","明時則待金門詔，肯羨班超萬戶侯。"]', '["拋擲清溪旧釣鉤，长安寒暑再环周。","便隨鶯羽三春化，只说蟬声一度愁。","掃雪自怜窗紙照，上天寧愧海槎流。","明时則待金门詔，肯羨班超万戶侯。"]', '诗', 'shi', '', NULL, '長安即事三首 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2702d6d4-922f-4674-8f77-31ff0280a3a9', '長安即事三首 二', '长安即事三首 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["無酒窮愁結自舒，飲河求滿不求餘。","身登霄漢平時第，家得干戈定後書。","富貴敢期蘇季子，清貧方見馬相如。","明時用即匡君去，不用何妨却釣魚。"]', '["無酒窮愁結自舒，饮河求满不求餘。","身登霄漢平时第，家得干戈定後书。","富貴敢期蘇季子，清貧方见马相如。","明时用即匡君去，不用何妨却釣鱼。"]', '诗', 'shi', '', NULL, '長安即事三首 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb5dd857-d103-4b94-aa53-95aaa2833e87', '長安即事三首 三', '长安即事三首 三', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["拖紫腰金不要論，便堪歸隱白雲村。","更無名籍強金榜，豈有花枝勝杏園。","綺席促時皆國器，羽觥飛處盡王孫。","高眠亦是前賢事，爭報春闈莫大恩。"]', '["拖紫腰金不要論，便堪归隐白云村。","更無名籍強金榜，豈有花枝勝杏园。","綺席促时皆国器，羽觥飞处尽王孫。","高眠亦是前賢事，爭報春闈莫大恩。"]', '诗', 'shi', '', NULL, '長安即事三首 三 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fec157bb-e22e-4671-8f51-9a1ef41777e1', '東京次新安道中', '东京次新安道中', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["賊去兵來歲月長，野蒿空滿壞墻匡。","旋從古轍成深谷，幾見金輿過上陽。","洛水送年催代謝，嵩山擎日拂穹蒼。","殊時異世爲儒者，不見文皇與武皇。"]', '["賊去兵来歲月长，野蒿空满壞墻匡。","旋從古轍成深谷，幾见金輿過上陽。","洛水送年催代謝，嵩山擎日拂穹蒼。","殊时異世爲儒者，不见文皇與武皇。"]', '诗', 'shi', '', NULL, '東京次新安道中 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d10a53b2-68ab-41e3-aefa-577a624a9edc', '山陰故事', '山陰故事', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["坦腹夫君不可逢，千年猶在播英風。","紅鵝化鶴青天遠，綵筆成龍綠水空。","愛竹只應憐直節，書裙多是爲奇童。","吹笙緱嶺登山後，東注清流豈有窮。"]', '["坦腹夫君不可逢，千年猶在播英风。","紅鵝化鹤青天远，綵笔成龙綠水空。","愛竹只應怜直節，书裙多是爲奇童。","吹笙緱嶺登山後，东注清流豈有窮。"]', '诗', 'shi', '', NULL, '山陰故事 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a35772d-80a6-40f4-a28d-abe2563f444a', '溫陵即事', '溫陵即事', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["早年師友教爲文，賣却魚舟網典墳。","國有安危期日諫，家無擔石暫從軍。","非才豈合攀丹桂，多病猶堪伴白雲。","爭得千鍾季孫粟，滄洲歸與故人分。"]', '["早年師友教爲文，賣却鱼舟網典墳。","国有安危期日諫，家無擔石暫從軍。","非才豈合攀丹桂，多病猶堪伴白云。","爭得千鍾季孫粟，滄洲归與故人分。"]', '诗', 'shi', '', NULL, '溫陵即事 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d21c2ab-0e9f-4f59-a306-43f8330875d2', '溫陵殘臘書懷寄崔尚書', '溫陵殘臘书懷寄崔尚书', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["濟川無楫擬何爲，三傑還從漢祖推。","心學庭槐空發火，鬢同門柳即垂絲。","中興未遇先懷策，除夜相催也課[詩]。","江上年年接君子，一杯春酒一枰棊。"]', '["濟川無楫擬何爲，三傑還從漢祖推。","心学庭槐空發火，鬢同门柳即垂絲。","中兴未遇先懷策，除夜相催也課[诗]。","江上年年接君子，一杯春酒一枰棊。"]', '诗', 'shi', '', NULL, '溫陵殘臘書懷寄崔尚書 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbc61131-c76e-42d7-a5cd-bae9ea9c9ae0', '義通里寓居即事', '義通里寓居即事', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["家住寒梅翠嶺東，長安時節詠途窮。","牡丹窠小春餘雨，楊柳絲疎夏足風。","愁鬢已還年紀白，衰容寧藉酒杯紅。","長卿甚有凌雲作，誰與清吟遶帝宮。"]', '["家住寒梅翠嶺东，长安时節詠途窮。","牡丹窠小春餘雨，楊柳絲疎夏足风。","愁鬢已還年紀白，衰容寧藉酒杯紅。","长卿甚有凌云作，誰與清吟遶帝宮。"]', '诗', 'shi', '', NULL, '義通里寓居即事 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('878ddb03-de81-4a25-b806-0c2ad6e3778a', '上陽宮詞', '上陽宮词', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["點點苔錢上玉墀，日斜空望六龍西。","妝臺塵暗青鸞掩，宮樹月明黃鳥啼。","庭草可憐分雨露，君恩深恨隔雲泥。","銀蟾借與金波路，得入重輪伴羿妻。"]', '["点点苔錢上玉墀，日斜空望六龙西。","妝台塵暗青鸾掩，宮樹月明黄鸟啼。","庭草可怜分雨露，君恩深恨隔云泥。","銀蟾借與金波路，得入重輪伴羿妻。"]', '诗', 'shi', '', NULL, '上陽宮詞 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b509e742-e44e-485d-97a7-93de676e1afc', '西寨寓居 一', '西寨寓居 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["閑讀南華對酒杯，醉攜筇竹畫蒼苔。","豪門有利人爭去，陋巷無權客不來。","解報可能醫病雀，重燃誰肯照寒灰。","嚴陵萬古清風在，好櫂東溪詠釣臺。"]', '["闲读南华对酒杯，醉携筇竹畫蒼苔。","豪门有利人爭去，陋巷無權客不来。","解報可能醫病雀，重燃誰肯照寒灰。","嚴陵万古清风在，好櫂东溪詠釣台。"]', '诗', 'shi', '', NULL, '西寨寓居 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('867c1506-8f35-484f-887d-85f6aaf71134', '西寨寓居 二', '西寨寓居 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["功智爭馳澹薄空，猶懷忠信擬何從。","鴟鳶啄腐疑雛鳳，神鬼欺貧笑伯龍。","烈日不融雙鬢雪，病身全仰竹枝筇。","崇侯入輔嚴陵退，堪憶啼猨萬仞峯。"]', '["功智爭驰澹薄空，猶懷忠信擬何從。","鴟鳶啄腐疑雛鳳，神鬼欺貧笑伯龙。","烈日不融雙鬢雪，病身全仰竹枝筇。","崇侯入輔嚴陵退，堪憶啼猨万仞峯。"]', '诗', 'shi', '', NULL, '西寨寓居 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0586535-efbf-4b52-8455-90e586bb5c5c', '題福州天王閣', '題福州天王閣', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["絕境宜棲獨角仙，金張到此亦忘還。","三門裏面千層閣，萬井中心一朵山。","江拗碧灣盤洞府，石排青壁護禪關。","有時海上看明月，輾出冰輪疊浪間。"]', '["絕境宜棲独角仙，金張到此亦忘還。","三门裏面千層閣，万井中心一朵山。","江拗碧灣盤洞府，石排青壁護禪关。","有时海上看明月，輾出冰輪叠浪间。"]', '诗', 'shi', '', NULL, '題福州天王閣 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('199b4541-4639-4288-9865-5d441e6cb43d', '憶薦福寺南院', '憶薦福寺南院', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["憶昔長安落第春，佛宮南院獨遊頻。","燈前不動惟金像，壁上曾題盡古人。","鶗鴂聲中雙闕雨，牡丹花際六街塵。","啼猨溪上將歸去，合問昇平詣秉鈞。"]', '["憶昔长安落第春，佛宮南院独游頻。","灯前不动惟金像，壁上曾題尽古人。","鶗鴂声中雙闕雨，牡丹花際六街塵。","啼猨溪上將归去，合问昇平詣秉鈞。"]', '诗', 'shi', '', NULL, '憶薦福寺南院 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d1f04b5-77fd-4d68-8de6-4e0c8ab73c87', '塔院小屋四壁皆是卿相題名因成四韻', '塔院小屋四壁皆是卿相題名因成四韻', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["雁塔攙空映九衢，每看華宇每踟躕。","題名盡是台衡迹，滿壁堪爲宰輔圖。","鸞鳳豈巢荆棘樹，虬龍多蟄帝王都。","誰知遠客思歸夢，夜夜無船自過湖。"]', '["雁塔攙空映九衢，每看华宇每踟躕。","題名尽是台衡迹，满壁堪爲宰輔圖。","鸾鳳豈巢荆棘樹，虬龙多蟄帝王都。","誰知远客思归梦，夜夜無船自過湖。"]', '诗', 'shi', '', NULL, '塔院小屋四壁皆是卿相題名因成四韻 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e36c5e5-1b70-4526-99a5-ecb43cabe484', '題名琉璃院', '題名琉璃院', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["一條溪遶翠巖隈，行脚僧言勝五臺。","農罷樹陰黃犢臥，齋時山下白衣來。","松因往日門人種，路是前生長老開。","三卷貝多金粟語，可能長誦免輪迴。"]', '["一條溪遶翠巖隈，行脚僧言勝五台。","農罷樹陰黄犢臥，斋时山下白衣来。","松因往日门人種，路是前生长老开。","三卷貝多金粟語，可能长誦免輪迴。"]', '诗', 'shi', '', NULL, '題名琉璃院 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef82e2b3-a58c-403b-be83-7adf4af8529b', '寺中偶題', '寺中偶題', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["聽話金仙眉相毫，每來皆得解塵勞。","鶴棲雲路看方貴，僧倚松門見始高。","名利罷燒心內火，雪霜偏垢鬢邊毛。","銀蟾未出金烏在，更上層樓眺海濤。"]', '["听話金仙眉相毫，每来皆得解塵勞。","鹤棲云路看方貴，僧倚松门见始高。","名利罷燒心內火，雪霜偏垢鬢邊毛。","銀蟾未出金烏在，更上層楼眺海濤。"]', '诗', 'shi', '', NULL, '寺中偶題 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78bcfba7-e85c-4092-8b7a-387f26b4a072', '山寺寓居', '山寺寓居', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["高臥東林最上方，水聲山翠剔愁腸。","白雲送雨籠僧閣，黃葉隨風入客堂。","終去四明成大道，暫從雙鬢許秋霜。","披緇學佛應無分，鶴氅談空亦不妨。"]', '["高臥东林最上方，水声山翠剔愁腸。","白云送雨籠僧閣，黄葉隨风入客堂。","終去四明成大道，暫從雙鬢許秋霜。","披緇学佛應無分，鹤氅談空亦不妨。"]', '诗', 'shi', '', NULL, '山寺寓居 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e10ced72-23f6-43c4-80c9-e0b38766dacb', '寄僧寓題', '寄僧寓題', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["佛頂抄經憶惠休，衆人皆謂我悠悠。","浮生真箇醉中夢，閑事莫添身外愁。","百歲付于花暗落，四時隨却水奔流。","安眠靜笑思何報，日夜焚修祝郡侯。"]', '["佛頂抄經憶惠休，衆人皆謂我悠悠。","浮生真箇醉中梦，闲事莫添身外愁。","百歲付于花暗落，四时隨却水奔流。","安眠静笑思何報，日夜焚修祝郡侯。"]', '诗', 'shi', '', NULL, '寄僧寓題 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc0e6ce-b1b7-4563-ad88-bf2ffcc2a98c', '游靈隱天竺二寺', '游靈隐天竺二寺', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["丹井冷泉虛易到，兩山真界實難名。","石和雲霧蓮華氣，月過樓臺桂子清。","騰踏回橋巡像設，羅穿曲洞出龍成。","更憐童子呼猿去，颯颯蕭蕭下樹行。"]', '["丹井冷泉虛易到，兩山真界實难名。","石和云霧蓮华氣，月過楼台桂子清。","腾踏回橋巡像設，羅穿曲洞出龙成。","更怜童子呼猿去，颯颯蕭蕭下樹行。"]', '诗', 'shi', '', NULL, '游靈隱天竺二寺 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25c0f378-00fb-4883-acc7-fe326c7fa02d', '醉題邑宰南塘屋壁', '醉題邑宰南塘屋壁', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["萬古清淮照遠天，黃河濁浪不相關。","縣留東道三千客，宅鎖南塘一片山。","草色淨經秋雨綠，燒痕寒入曉窗斑。","閩王美錦求賢製，未許陶公解印還。"]', '["万古清淮照远天，黄河濁浪不相关。","縣留东道三千客，宅鎖南塘一片山。","草色淨經秋雨綠，燒痕寒入晓窗斑。","閩王美錦求賢製，未許陶公解印還。"]', '诗', 'shi', '', NULL, '醉題邑宰南塘屋壁 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24694808-e097-4d8e-93aa-702bb937fe05', '題泗洲塔', '題泗洲塔', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["十年前事已悠哉，旋被鐘聲早暮催。","明月似師生又沒，白雲如客去還來。","煙籠瑞閣僧經靜，風打虛窗佛幌開。","惟有南邊山色在，重重依舊上高臺。"]', '["十年前事已悠哉，旋被鐘声早暮催。","明月似師生又沒，白云如客去還来。","煙籠瑞閣僧經静，风打虛窗佛幌开。","惟有南邊山色在，重重依旧上高台。"]', '诗', 'shi', '', NULL, '題泗洲塔 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b953594-f83c-4d53-bf31-b92964be303b', '東歸題屋壁', '东归題屋壁', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["塵埃歸去五湖東，還是衡門一畝宮。","舊業旋從征賦失，故人多逐亂離空。","因悲盡室如懸罄，却擬攜家學轉蓬。","見說武王天上夢，無情曾與傅岩通。"]', '["塵埃归去五湖东，還是衡门一畝宮。","旧業旋從征賦失，故人多逐亂離空。","因悲尽室如懸罄，却擬携家学轉蓬。","见说武王天上梦，無情曾與傅岩通。"]', '诗', 'shi', '', NULL, '東歸題屋壁 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c53bbead-5457-40ab-b7ef-e0fa3a0e002b', '寓題', '寓題', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["酒壺棋局似閑人，竹笏藍衫老此身。","託客買書重得卷，愛山移宅近爲鄰。","鳴蛩閣上風吹病，落葉庭中月照貧。","見說天池波浪闊，也應涓滴濺窮鱗。"]', '["酒壺棋局似闲人，竹笏藍衫老此身。","託客買书重得卷，愛山移宅近爲鄰。","鳴蛩閣上风吹病，落葉庭中月照貧。","见说天池波浪闊，也應涓滴濺窮鱗。"]', '诗', 'shi', '', NULL, '寓題 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('269d6946-b825-4664-a402-c2b617ac75de', '偶題', '偶題', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["閑補亡書見廢興，偶然前古也填膺。","秦宮猶自拜張祿，楚幕不知留范增。","大道豈全關曆數，雄圖強半屬賢能。","燕臺財力知多少，誰築黃金到九層。"]', '["闲補亡书见廢兴，偶然前古也填膺。","秦宮猶自拜張祿，楚幕不知留范增。","大道豈全关曆數，雄圖強半屬賢能。","燕台財力知多少，誰築黄金到九層。"]', '诗', 'shi', '', NULL, '偶題 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd94dc9b-07fa-4e9a-8e10-6c00d40ec320', '寓題述懷', '寓題述懷', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["大道真風早晚還，妖訛成俗汙乾坤。","宣尼既沒蘇張起，鳳鳥不來雞雀喧。","芻少可能供驥子，草多誰復訪蘭蓀。","堯廷忘却徴元凱，天闕重關十二門。"]', '["大道真风早晚還，妖訛成俗汙乾坤。","宣尼既沒蘇張起，鳳鸟不来雞雀喧。","芻少可能供驥子，草多誰复訪蘭蓀。","堯廷忘却徴元凱，天闕重关十二门。"]', '诗', 'shi', '', NULL, '寓題述懷 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a0a0754-e046-4601-82fc-7d7a6ecec3d1', '將入城靈口道中作', '將入城靈口道中作', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["路上長安惟咫尺，灞陵西望接秦源。","依稀日下分天闕，隱映雲邊是國門。","錦袖臂鷹河北客，青桑鳴雉渭南村。","高風九萬程途近，與報滄洲欲化鯤。"]', '["路上长安惟咫尺，灞陵西望接秦源。","依稀日下分天闕，隐映云邊是国门。","錦袖臂鷹河北客，青桑鳴雉渭南村。","高风九万程途近，與報滄洲欲化鯤。"]', '诗', 'shi', '', NULL, '將入城靈口道中作 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c592f0a-9a96-4b1d-8cd7-e26530c21100', '新屋', '新屋', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["耳順何爲土木勤，叔孫牆屋有前聞。","縱然一世如紅葉，猶得十年吟白雲。","性逸且圖稱野客，才難非敢傲明君。","清甜數尺沙泉井，平與鄰家晝夜分。"]', '["耳順何爲土木勤，叔孫牆屋有前闻。","縱然一世如紅葉，猶得十年吟白云。","性逸且圖稱野客，才难非敢傲明君。","清甜數尺沙泉井，平與鄰家晝夜分。"]', '诗', 'shi', '', NULL, '新屋 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31773437-9b6c-41a4-900c-a1de4f30b06f', '新葺茆堂 一', '新葺茆堂 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["翦竹誅茆就水濱，靜中還得保天真。","只聞神鬼害盈滿，不見古今爭賤貧。","樹影便爲廊廡屋，草香權當綺羅茵。","堦前一片泓澄水，借與汀禽活紫鱗。"]', '["翦竹誅茆就水濱，静中還得保天真。","只闻神鬼害盈满，不见古今爭賤貧。","樹影便爲廊廡屋，草香權當綺羅茵。","堦前一片泓澄水，借與汀禽活紫鱗。"]', '诗', 'shi', '', NULL, '新葺茆堂 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b38eb2c-07f2-4c81-a519-72c5c329ca3c', '新葺茆堂 二', '新葺茆堂 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["耨水耕山息故林，壯圖嘉話負前心。","素絲鬢上分愁色，絡緯牀頭和苦吟。","筆研不才當付火，方書多誑罷燒金。","同年二十八君子，遊楚遊秦斷好音。"]', '["耨水耕山息故林，壯圖嘉話負前心。","素絲鬢上分愁色，絡緯牀头和苦吟。","笔研不才當付火，方书多誑罷燒金。","同年二十八君子，游楚游秦斷好音。"]', '诗', 'shi', '', NULL, '新葺茆堂 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('063991b4-455d-4ebe-8378-0dc051da3050', '茆亭', '茆亭', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["鴛瓦虹梁計已疎，織茅編竹稱貧居。","翦平恰似山僧笠，掃靜真同道者廬。","秋晚捲簾看過雁，月明憑檻數跳魚。","重門公子應相笑，四壁風霜老讀書。"]', '["鴛瓦虹梁計已疎，织茅編竹稱貧居。","翦平恰似山僧笠，掃静真同道者廬。","秋晚捲簾看過雁，月明憑檻數跳鱼。","重门公子應相笑，四壁风霜老读书。"]', '诗', 'shi', '', NULL, '茆亭 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec34f784-d237-4b08-bc9a-c9f0e27d06ac', '客廳', '客廳', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["移却松筠致客堂，淨泥環堵貯荷香。","衡茅只要免風雨，藻梲不須高棟梁。","豐蔀仲尼明演易，作歌五子恨雕牆。","燕臺漢閣王侯事，青史千年播耿光。"]', '["移却松筠致客堂，淨泥环堵貯荷香。","衡茅只要免风雨，藻梲不須高棟梁。","豐蔀仲尼明演易，作歌五子恨雕牆。","燕台漢閣王侯事，青史千年播耿光。"]', '诗', 'shi', '', NULL, '客廳 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da0c9dfa-cfdc-4701-ae32-7b1acd002659', '詠寫真', '詠寫真', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["寫得衰容似十全，閑開僧舍靜時懸。","瘦于南國從軍日，老却東堂射策年。","潭底看身寧有異，鏡中引影更無偏。","借將前輩真儀比，未愧金鑾李謫仙。"]', '["寫得衰容似十全，闲开僧舍静时懸。","瘦于南国從軍日，老却东堂射策年。","潭底看身寧有異，镜中引影更無偏。","借將前輩真儀比，未愧金鑾李謫仙。"]', '诗', 'shi', '', NULL, '詠寫真 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('378c18a9-f8f7-41ee-ad31-cb4fb9cae5ba', '放榜日', '放榜日', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["喧喧車馬欲朝天，人探東堂榜已懸。","萬里便隨金鸑鷟，三台仍借玉連錢。","花浮酒影彤霞爛，日照衫光瑞色鮮。","十二街前樓閣上，卷簾誰不看神仙。"]', '["喧喧车马欲朝天，人探东堂榜已懸。","万里便隨金鸑鷟，三台仍借玉連錢。","花浮酒影彤霞爛，日照衫光瑞色鲜。","十二街前楼閣上，卷簾誰不看神仙。"]', '诗', 'shi', '', NULL, '放榜日 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa151c98-47ec-43b0-b5db-7eddcc7152bd', '曲江宴日呈諸同年', '曲江宴日呈諸同年', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["鷦鷯驚與鳳皇同，忽向中興遇至公。","金榜連名昇碧落，紫花封勅出瓊宮。","天知惜日遲遲暮，春爲催花旋旋紅。","好是慈恩題了望，白雲飛盡塔連空。"]', '["鷦鷯驚與鳳皇同，忽向中兴遇至公。","金榜連名昇碧落，紫花封勅出瓊宮。","天知惜日遲遲暮，春爲催花旋旋紅。","好是慈恩題了望，白云飞尽塔連空。"]', '诗', 'shi', '', NULL, '曲江宴日呈諸同年 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7228cdd0-1804-47b8-866d-ab052ebede04', '渤海賓貢高元固先輩閩中相訪云本國人寫得夤斬蛇劍御溝水人生幾何賦家皆以金書列爲屏障因而有贈', '渤海賓貢高元固先輩閩中相訪云本国人寫得夤斬蛇劍御溝水人生幾何賦家皆以金书列爲屏障因而有贈', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["折桂何年下月中，閩山來問我雕蟲。","肯銷金翠書屏上，誰把芻蕘過日東。","郯子昔時遭孔聖，繇余往代諷秦宮。","嗟嗟大國金門士，幾個人能振素風。"]', '["折桂何年下月中，閩山来问我雕蟲。","肯銷金翠书屏上，誰把芻蕘過日东。","郯子昔时遭孔聖，繇余往代諷秦宮。","嗟嗟大国金门士，幾個人能振素风。"]', '诗', 'shi', '', NULL, '渤海賓貢高元固先輩閩中相訪云本國人寫得夤斬蛇劍御溝水人生幾何賦家皆以金書列爲屏障因而有贈 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b70b6be-fd22-4502-be04-24a0a22fcbf9', '偶吟', '偶吟', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["千卷長書萬首詩，朝蒸藜藿暮烹葵。","清時名立難皆我，晚歲途窮亦問誰。","碧岸釣歸惟獨笑，青山耕徧亦何爲。","尋常抖擻懷中策，可便降他兩鬢絲。"]', '["千卷长书万首诗，朝蒸藜藿暮烹葵。","清时名立难皆我，晚歲途窮亦问誰。","碧岸釣归惟独笑，青山耕徧亦何爲。","尋常抖擻懷中策，可便降他兩鬢絲。"]', '诗', 'shi', '', NULL, '偶吟 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b20cb5b-a414-458c-87a4-aef3132f6788', '贈表弟黃校書輅', '贈表弟黄校书輅', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["產破身窮爲學儒，我家諸表愛詩書。","嚴陵雖說臨溪隱，晏子還聞近市居。","佳句麗偷紅菡萏，吟窗冷落白蟾蜍。","閑來共話無生理，今古悠悠事總虛。"]', '["產破身窮爲学儒，我家諸表愛诗书。","嚴陵雖说臨溪隐，晏子還闻近市居。","佳句丽偷紅菡萏，吟窗冷落白蟾蜍。","闲来共話無生理，今古悠悠事總虛。"]', '诗', 'shi', '', NULL, '贈表弟黃校書輅 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a70a51da-5d7b-40cc-911e-cc8560ec284d', '輦下贈屯田何員外', '輦下贈屯田何員外', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["封章頻得帝咨嗟，報國唯將直破邪。","身到西山書幾達，官登南省鬢初華。","廚非寒食還無火，菊待重陽擬泛茶。","內翰好才兼好古，秋來應數到君家。"]', '["封章頻得帝咨嗟，報国唯將直破邪。","身到西山书幾達，官登南省鬢初华。","廚非寒食還無火，菊待重陽擬泛茶。","內翰好才兼好古，秋来應數到君家。"]', '诗', 'shi', '', NULL, '輦下贈屯田何員外 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a5f05c1-2b26-46a3-b8df-c5bd3d67aed4', '贈月君', '贈月君', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["出水蓮花比性靈，三生塵夢一時醒。","神傳尊勝陀羅咒，佛授金剛般若經。","懿德好書添女誡，素容堪畫上銀屏。","鳴梭軋軋纖纖手，窗戶流光織女星。"]', '["出水蓮花比性靈，三生塵梦一时醒。","神傳尊勝陀羅咒，佛授金剛般若經。","懿德好书添女誡，素容堪畫上銀屏。","鳴梭軋軋纖纖手，窗戶流光织女星。"]', '诗', 'shi', '', NULL, '贈月君 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f567eb-2afa-4e62-b01d-f34bcb64db76', '贈垂光同年', '贈垂光同年', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["丹桂攀來十七春，如今始見茜袍新。","須知紅杏園中客，終作金鑾殿裏臣。","逸少家風惟筆札，玄成世業是陶鈞。","他時黃閣朝元處，莫忘同年射策人。"]', '["丹桂攀来十七春，如今始见茜袍新。","須知紅杏园中客，終作金鑾殿裏臣。","逸少家风惟笔札，玄成世業是陶鈞。","他时黄閣朝元处，莫忘同年射策人。"]', '诗', 'shi', '', NULL, '贈垂光同年 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bd5bbf9-71de-455f-843b-763270f3b781', '贈楊著', '贈楊著', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["藻麗熒煌冠士林，白華榮養有曾參。","十年去里荆門改，八歲能詩相座吟。","李廣不侯身漸老，子山操賦恨何深。","釣魚臺上頻相訪，共說長安淚滿襟。"]', '["藻丽熒煌冠士林，白华榮養有曾參。","十年去里荆门改，八歲能诗相座吟。","李廣不侯身漸老，子山操賦恨何深。","釣鱼台上頻相訪，共说长安泪满襟。"]', '诗', 'shi', '', NULL, '贈楊著 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cba6322-fb6e-4282-ae0a-39a35f8f0761', '贈黃校書先輩璞閑居', '贈黄校书先輩璞闲居', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["馭得驪龍第四珠，退依僧寺卜貧居。","青山入眼不干祿，白髮滿頭猶著書。","東澗野香添碧沼，南園夜雨長秋蔬。","月明掃石吟詩坐，諱却全無儋石儲。"]', '["馭得驪龙第四珠，退依僧寺卜貧居。","青山入眼不干祿，白髮满头猶著书。","东澗野香添碧沼，南园夜雨长秋蔬。","月明掃石吟诗坐，諱却全無儋石儲。"]', '诗', 'shi', '', NULL, '贈黃校書先輩璞閑居 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79932791-0698-4671-b01b-9dd4ebdf24e3', '尚書榮拜恩命夤疾中輙課惡詩二首以申攀讚 一', '尚书榮拜恩命夤疾中輙課惡诗二首以申攀讚 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["明公家鑿鳳皇池，弱冠封侯四海推。","富貴有期天授早，關河多難勅來遲。","昴星人傑當王佐，黃石仙翁識帝師。","昨日詔書猶漏缺，未言商也最能詩。"]', '["明公家鑿鳳皇池，弱冠封侯四海推。","富貴有期天授早，关河多难勅来遲。","昴星人傑當王佐，黄石仙翁識帝師。","昨日詔书猶漏缺，未言商也最能诗。"]', '诗', 'shi', '', NULL, '尚書榮拜恩命夤疾中輙課惡詩二首以申攀讚 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4066c46-b92e-4fa2-9b28-2b1b539d4110', '尚書榮拜恩命夤疾中輙課惡詩二首以申攀讚 二', '尚书榮拜恩命夤疾中輙課惡诗二首以申攀讚 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["東郊迎入紫泥封，此日天仙下九重。","三五月明臨闞澤，百千人衆看王恭。","旗傍綠樹遙分影，馬蹋浮雲不見蹤。","借問乘軺何處客，相庭雄幕卷芙蓉。"]', '["东郊迎入紫泥封，此日天仙下九重。","三五月明臨闞澤，百千人衆看王恭。","旗傍綠樹遙分影，马蹋浮云不见蹤。","借问乘軺何处客，相庭雄幕卷芙蓉。"]', '诗', 'shi', '', NULL, '尚書榮拜恩命夤疾中輙課惡詩二首以申攀讚 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8384058-ed16-4f24-9d49-d50d652b9a64', '府主僕射王[摶]生日', '府主僕射王[摶]生日', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["熊羆先兆慶垂休，天地氤氳瑞氣浮。","李樹影籠周柱史，昴星光照漢酇侯。","數鍾龜鶴千年算，律正乾坤八月秋。","勳業定應歸鼎鼐，生靈豈獨化東甌。"]', '["熊羆先兆慶垂休，天地氤氳瑞氣浮。","李樹影籠周柱史，昴星光照漢酇侯。","數鍾龟鹤千年算，律正乾坤八月秋。","勳業定應归鼎鼐，生靈豈独化东甌。"]', '诗', 'shi', '', NULL, '府主僕射王[摶]生日 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed4450d9-d7ec-49c3-b278-06bf94028db8', '獻內翰楊侍郎', '獻內翰楊侍郎', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["窗開青瑣見瑤臺，冷拂星辰逼上台。","丹鳳詔成中使取，白龍香近聖君來。","欲言溫署三緘口，閑賦宮詞八斗才。","莫擬吟雲避榮貴，廟堂玉鉉待鹽梅。"]', '["窗开青瑣见瑤台，冷拂星辰逼上台。","丹鳳詔成中使取，白龙香近聖君来。","欲言溫署三緘口，闲賦宮词八斗才。","莫擬吟云避榮貴，廟堂玉鉉待鹽梅。"]', '诗', 'shi', '', NULL, '獻內翰楊侍郎 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b63f9cc0-4dee-4de8-bb11-ec4863fe2682', '送劉常侍', '送劉常侍', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["懷君何計更留連，忍送文星上碧天。","杜預注通三十卷，漢皇枝紹幾千年。","言端信義如明月，筆下篇章似湧泉。","他日有書隨雁足，東溪無令訪漁船。"]', '["懷君何計更留連，忍送文星上碧天。","杜預注通三十卷，漢皇枝紹幾千年。","言端信義如明月，笔下篇章似湧泉。","他日有书隨雁足，东溪無令訪漁船。"]', '诗', 'shi', '', NULL, '送劉常侍 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('145c2908-93f9-48ac-a1a2-6d626e253a30', '送盧拾遺歸華山', '送盧拾遺归华山', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["紫殿諫多防佞口，清秋假滿別明君。","惟憂急詔歸青瑣，不得經時臥白雲。","千載茯苓攜鶴斸，一峰仙掌與僧分。","門前舊客期相薦，猶望飛書及主文。"]', '["紫殿諫多防佞口，清秋假满別明君。","惟憂急詔归青瑣，不得經时臥白云。","千載茯苓携鹤斸，一峰仙掌與僧分。","门前旧客期相薦，猶望飞书及主文。"]', '诗', 'shi', '', NULL, '送盧拾遺歸華山 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a13f6163-3ba5-4a55-8254-46396a0b249b', '春末道陳先輩之清源', '春末道陳先輩之清源', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["貧中惟是長年華，每羨君行自嘆嗟。","歸日捧持明月寶，去時期刻刺桐花。","春風避酒多游寺，曉騎聽雞早入衙。","千乘侯王若相問，飛書與報白雲家。"]', '["貧中惟是长年华，每羨君行自嘆嗟。","归日捧持明月寶，去时期刻刺桐花。","春风避酒多游寺，晓騎听雞早入衙。","千乘侯王若相问，飞书與報白云家。"]', '诗', 'shi', '', NULL, '春末道陳先輩之清源 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6880baf7-81bd-4134-bf2d-554af414cf65', '上盧三拾遺以言見黜', '上盧三拾遺以言见黜', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["骨鯁如君道尚存，近來人事不須論。","疾危必厭神明藥，心惑多嫌正直言。","冷眼靜看真好笑，傾懷與說却爲冤。","因思周廟當時誡，金口三緘示後昆。"]', '["骨鯁如君道尚存，近来人事不須論。","疾危必厭神明藥，心惑多嫌正直言。","冷眼静看真好笑，傾懷與说却爲冤。","因思周廟當时誡，金口三緘示後昆。"]', '诗', 'shi', '', NULL, '上盧三拾遺以言見黜 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4d7a5bd-54a8-41a1-8a51-6c25abf677bb', '送王校書往清源', '送王校书往清源', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["南國賢侯待德風，長途仍借九花驄。","清歌早貫驪龍[頷]，丹桂曾攀玉兔宮。","楊柳堤邊梅雨熟，鷓鴣聲裏麥田空。","吟詩臺上如相問，與說蟠溪直釣翁。"]', '["南国賢侯待德风，长途仍借九花驄。","清歌早貫驪龙[頷]，丹桂曾攀玉兔宮。","楊柳堤邊梅雨熟，鷓鴣声裏麦田空。","吟诗台上如相问，與说蟠溪直釣翁。"]', '诗', 'shi', '', NULL, '送王校書往清源 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6925574e-9548-4808-be6d-574cd2708b56', '岳州端午日送人游郴連', '岳州端午日送人游郴連', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["五月巴陵值積陰，送君千里客于郴。","北風吹雨黃梅落，西日過湖青草深。","競渡岸傍人挂錦，採芳城上女遺簪。","九嶷雲闊蒼梧暗，與說重華舊德音。"]', '["五月巴陵值積陰，送君千里客于郴。","北风吹雨黄梅落，西日過湖青草深。","競渡岸傍人挂錦，採芳城上女遺簪。","九嶷云闊蒼梧暗，與说重华旧德音。"]', '诗', 'shi', '', NULL, '岳州端午日送人游郴連 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4f93697-8213-41c7-b8d9-f8a519994305', '賀清源太保王延[彬] 一', '賀清源太保王延[彬] 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["蘂珠宮裏謫神仙，八載溫陵萬戶閑。","心地闊于雲夢澤，官資高却太行山。","姜牙兆寄熊羆內，陶侃文成掌握間。","應笑清溪舊門吏，年年扶病掩柴關。"]', '["蘂珠宮裏謫神仙，八載溫陵万戶闲。","心地闊于云梦澤，官資高却太行山。","姜牙兆寄熊羆內，陶侃文成掌握间。","應笑清溪旧门吏，年年扶病掩柴关。"]', '诗', 'shi', '', NULL, '賀清源太保王延[彬] 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82e9575f-1a4e-4777-9bc7-3c7fa084434d', '賀清源太保王延[彬] 二', '賀清源太保王延[彬] 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["武榮江畔蔭祥雲，寵拜天人慶郡人。","五色鶴綾花上勅，九霄龍尾道邊臣。","英雄達處誰言命，富貴來時自逼身。","更待春風飛吉語，紫泥分付與陶鈞。"]', '["武榮江畔蔭祥云，寵拜天人慶郡人。","五色鹤綾花上勅，九霄龙尾道邊臣。","英雄達处誰言命，富貴来时自逼身。","更待春风飞吉語，紫泥分付與陶鈞。"]', '诗', 'shi', '', NULL, '賀清源太保王延[彬] 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('691e4775-8ccb-4b71-84ff-82ac1c4da4f5', '病中春日即事寄主人尚書二首 一', '病中春日即事寄主人尚书二首 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["身比秋荷覺漸枯，至君經國墮前圖。","層冰照日猶能暖，病骨逢春却未蘇。","鏡裏白鬚撏又長，枝頭黃鳥靜還呼。","庾樓恩化通神聖，何計能教擲得盧。"]', '["身比秋荷覺漸枯，至君經国墮前圖。","層冰照日猶能暖，病骨逢春却未蘇。","镜裏白鬚撏又长，枝头黄鸟静還呼。","庾楼恩化通神聖，何計能教擲得盧。"]', '诗', 'shi', '', NULL, '病中春日即事寄主人尚書二首 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9926ddbe-74ff-4a59-b126-d782ef439de4', '病中春日即事寄主人尚書二首 二', '病中春日即事寄主人尚书二首 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["風拍衰肌久未蠲，破窗頻見月團圓。","更無舊日同人問，只有多情太守憐。","臘內送將三折股，歲陰分與五銖錢。","玄穹若假年齡在，願捧銅盤爲國賢。"]', '["风拍衰肌久未蠲，破窗頻见月團圓。","更無旧日同人问，只有多情太守怜。","臘內送將三折股，歲陰分與五銖錢。","玄穹若假年齡在，願捧銅盤爲国賢。"]', '诗', 'shi', '', NULL, '病中春日即事寄主人尚書二首 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd847855-f80b-4f29-88b3-b678f619dd69', '寄華山司空侍郎二首 一', '寄华山司空侍郎二首 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["金闕爭權競獻功，獨逃徴詔臥三峰。","雞羣未必容於鶴，蛛網何繇捕得龍。","清論盡應書國史，靜籌皆可息邊烽。","風霜落滿千林木，不近青青澗底松。"]', '["金闕爭權競獻功，独逃徴詔臥三峰。","雞羣未必容於鹤，蛛網何繇捕得龙。","清論尽應书国史，静籌皆可息邊烽。","风霜落满千林木，不近青青澗底松。"]', '诗', 'shi', '', NULL, '寄華山司空侍郎二首 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6131114-b8b0-459d-a9d4-6007440ed2db', '寄華山司空侍郎二首 二', '寄华山司空侍郎二首 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["非雲非鶴不從容，誰敢輕量傲世蹤。","紫殿幾徴王佐業，青山未拆詔書封。","閑吟每待秋空月，早起長先野寺鐘。","前古負材多爲國，滿懷經濟欲何從。"]', '["非云非鹤不從容，誰敢轻量傲世蹤。","紫殿幾徴王佐業，青山未拆詔书封。","闲吟每待秋空月，早起长先野寺鐘。","前古負材多爲国，满懷經濟欲何從。"]', '诗', 'shi', '', NULL, '寄華山司空侍郎二首 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('310c8e8a-2a0b-4496-afdf-914008e3c797', '寄盧端公同年仁烱時遷都洛陽新立幼主', '寄盧端公同年仁烱时遷都洛陽新立幼主', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["上陽宮闕翠華歸，百辟傷心序漢儀。","崑岳有炎瓊玉碎，洛川無竹鳳皇飢。","須簪白筆匡明主，莫許黃㼐博少師。","惆悵宸居遠于日，長吁空摘鬢邊絲。"]', '["上陽宮闕翠华归，百辟傷心序漢儀。","崑岳有炎瓊玉碎，洛川無竹鳳皇飢。","須簪白笔匡明主，莫許黄㼐博少師。","惆悵宸居远于日，长吁空摘鬢邊絲。"]', '诗', 'shi', '', NULL, '寄盧端公同年仁烱時遷都洛陽新立幼主 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('655f7202-fcaa-4f14-8546-d219efba6dcb', '寄天台陳希畋', '寄天台陳希畋', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["陰山冰凍嘗迎夏，蟄戶雲雷只待春。","呂望豈嫌垂釣老，西施不恨浣紗貧。","坐爲羽獵車中相，飛作君王掌上身。","拍手相思惟大笑，我曹寧比等閑人。"]', '["陰山冰凍嘗迎夏，蟄戶云雷只待春。","呂望豈嫌垂釣老，西施不恨浣紗貧。","坐爲羽獵车中相，飞作君王掌上身。","拍手相思惟大笑，我曹寧比等闲人。"]', '诗', 'shi', '', NULL, '寄天台陳希畋 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8759348-e486-4e64-a088-413bb15e481b', '寄兩浙羅書記', '寄兩浙羅书記', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["進即湮沈退却升，錢塘風月過金陵。","鴻才入貢無人換，白首從軍有詔徴。","博簿集成時輩駡，讒書編就薄徒憎。","憐君道在名長在，不到慈恩最上層。"]', '["進即湮沈退却升，錢塘风月過金陵。","鴻才入貢無人換，白首從軍有詔徴。","博簿集成时輩駡，讒书編就薄徒憎。","怜君道在名长在，不到慈恩最上層。"]', '诗', 'shi', '', NULL, '寄兩浙羅書記 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f3128b3-622e-4e75-848f-82188348ff7d', '邑宰相訪翼日有寄', '邑宰相訪翼日有寄', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["淵明深念郤詵貧，踏破莓苔看甑塵。","碧沼共攀紅菡萏，金鞍不卸紫麒麟。","殘陽妬害催歸客，薄酒甘嘗罰主人。","夜半夢醒追復想，欲長攀接有何因。"]', '["淵明深念郤詵貧，踏破莓苔看甑塵。","碧沼共攀紅菡萏，金鞍不卸紫麒麟。","殘陽妬害催归客，薄酒甘嘗罰主人。","夜半梦醒追复想，欲长攀接有何因。"]', '诗', 'shi', '', NULL, '邑宰相訪翼日有寄 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feaf2a35-a756-4a8d-a6cd-0e673c9e3a9f', '白酒兩瓶送崔侍御', '白酒兩瓶送崔侍御', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["雪化霜融好潑醅，滿壺冰凍向春開。","求從白石洞中得，攜向百花巖畔來。","幾夕露珠寒貝齒，一泓銀水冷瓊杯。","湖邊送與崔夫子，誰見嵇山盡日頹。"]', '["雪化霜融好潑醅，满壺冰凍向春开。","求從白石洞中得，携向百花巖畔来。","幾夕露珠寒貝齒，一泓銀水冷瓊杯。","湖邊送與崔夫子，誰见嵇山尽日頹。"]', '诗', 'shi', '', NULL, '白酒兩瓶送崔侍御 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93be9b41-f876-4516-ab2a-e9b29cb39505', '依韻酬常循州', '依韻酬常循州', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["早年花縣拜潘郎，尋忝飛鳴出桂堂。","日走登天長似箭，人同紅樹豈經霜。","帆分南浦知離別，駕在東州更可傷。","公論一麾將塞詔，且隨徴令過瀟湘。"]', '["早年花縣拜潘郎，尋忝飞鳴出桂堂。","日走登天长似箭，人同紅樹豈經霜。","帆分南浦知離別，駕在东州更可傷。","公論一麾將塞詔，且隨徴令過瀟湘。"]', '诗', 'shi', '', NULL, '依韻酬常循州 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7af43a17-25bc-4308-832c-5ac0fb99483c', '謝主人惠綠酒白魚', '謝主人惠綠酒白鱼', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["早起雀聲送喜頻，白魚芳酒寄來珍。","馨香乍揭春風甕，撥刺初辭夜雨津。","樽闊最宜澄桂液，網疎殊未損霜鱗。","不曾垂釣兼親醞，堪愧金臺醉飽身。"]', '["早起雀声送喜頻，白鱼芳酒寄来珍。","馨香乍揭春风甕，撥刺初辞夜雨津。","樽闊最宜澄桂液，網疎殊未損霜鱗。","不曾垂釣兼親醞，堪愧金台醉飽身。"]', '诗', 'shi', '', NULL, '謝主人惠綠酒白魚 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06cc25ec-bdbd-441e-86e0-d424d86f8ed2', '蜀', '蜀', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["雖倚關張敵萬夫，豈勝恩信作良圖。","能均漢祚三分業，不負荆州六尺孤。","綠水有魚賢已得，青桑如蓋瑞先符。","君王幸是中山後，建國如何號蜀都。"]', '["雖倚关張敵万夫，豈勝恩信作良圖。","能均漢祚三分業，不負荆州六尺孤。","綠水有鱼賢已得，青桑如蓋瑞先符。","君王幸是中山後，建国如何號蜀都。"]', '诗', 'shi', '', NULL, '蜀 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ad91f5b-a9dc-4986-a754-11cb52d17c38', '魏', '魏', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["伐罪書勳令不常，爭教爲帝與爲王。","十年小怨誅桓邵，一檄深讐怨孔璋。","在井蟄龍如屈伏，食槽驕馬忽騰驤。","姦雄事過分明見，英識空懷許子將。"]', '["伐罪书勳令不常，爭教爲帝與爲王。","十年小怨誅桓邵，一檄深讐怨孔璋。","在井蟄龙如屈伏，食槽驕马忽腾驤。","姦雄事過分明见，英識空懷許子將。"]', '诗', 'shi', '', NULL, '魏 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d079073b-2d39-4817-b0f3-5c554bf1bf72', '吳', '吳', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["一主參差六十年，父兄猶慶授孫權。","不迎曹操真長策，終謝張昭見碩賢。","建業龍盤雖可貴，武昌魚味亦何偏。","秦嬴謾作東遊計，紫氣黃旗豈偶然。"]', '["一主參差六十年，父兄猶慶授孫權。","不迎曹操真长策，終謝張昭见碩賢。","建業龙盤雖可貴，武昌鱼味亦何偏。","秦嬴謾作东游計，紫氣黄旗豈偶然。"]', '诗', 'shi', '', NULL, '吳 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f540c53c-1df2-4e3f-832e-2790f1c5c0ba', '兩晉', '兩晉', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["三世深謀啓帝基，可憐孀婦與孤兒。","罪歸成濟皇天恨，戈犯明君萬古悲。","巴蜀削平輕似紙，勾吳吞却美如飴。","誰知高鼻能知數，競向中原簸戰旗。"]', '["三世深謀啓帝基，可怜孀婦與孤兒。","罪归成濟皇天恨，戈犯明君万古悲。","巴蜀削平轻似紙，勾吳吞却美如飴。","誰知高鼻能知數，競向中原簸戰旗。"]', '诗', 'shi', '', NULL, '兩晉 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec748d17-d6b4-4468-b1ac-901c32d34367', '宋二首 一', '宋二首 一', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["天爵休將儋石論，一身恭儉萬邦尊。","賭將金帶驚寰海，留得耕衣誡子孫。","締構不應饒漢祖，姦雄何足數王敦。","草中求活非吾事，豈啻橫身向廟門。"]', '["天爵休將儋石論，一身恭儉万邦尊。","賭將金带驚寰海，留得耕衣誡子孫。","締構不應饒漢祖，姦雄何足數王敦。","草中求活非吾事，豈啻橫身向廟门。"]', '诗', 'shi', '', NULL, '宋二首 一 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fcdc4cc-bb31-4cff-913c-82e027f02499', '宋二首 二', '宋二首 二', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["百萬人甘一擲輸，玄穹惟與道相符。","豈知紫殿新天子，只是丹徒舊嗇夫。","五色龍章身早見，六終鴻業數難逾。","三年未得分明夢，却爲蘭陵起霸圖。"]', '["百万人甘一擲輸，玄穹惟與道相符。","豈知紫殿新天子，只是丹徒旧嗇夫。","五色龙章身早见，六終鴻業數难逾。","三年未得分明梦，却爲蘭陵起霸圖。"]', '诗', 'shi', '', NULL, '宋二首 二 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ff4980a-2ff4-44e3-b5b9-94285e74de58', '陳', '陳', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["三惑昏昏中紫宸，萬機拋却醉臨春。","書中不禮隋文帝，井底常攜張貴嬪。","玉樹歌聲移入哭，金陵天子化爲臣。","兵戈半渡前江水，狎客猶聞爭酒巡。"]', '["三惑昏昏中紫宸，万機拋却醉臨春。","书中不禮隋文帝，井底常携張貴嬪。","玉樹歌声移入哭，金陵天子化爲臣。","兵戈半渡前江水，狎客猶闻爭酒巡。"]', '诗', 'shi', '', NULL, '陳 徐夤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3327382d-1056-4ba1-9dec-2e89f8974855', '讀史', '读史', '936abb1d-fe0e-45a1-af44-21dfcd6d1489', '唐', '["亞父淒涼別楚營，天留三傑翼龍爭。","高才無主不能用，直道有時方始平。","喜慍子文何頴悟，卷藏蘧瑗甚分明。","須知飲啄繇天命，休問黃河早晚清。"]', '["亞父淒涼別楚營，天留三傑翼龙爭。","高才無主不能用，直道有时方始平。","喜慍子文何頴悟，卷藏蘧瑗甚分明。","須知饮啄繇天命，休问黄河早晚清。"]', '诗', 'shi', '', NULL, '讀史 徐夤 shi');
